window.__D("text/zohar/c003",{"p":[[9520011149,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר (ישעיהו י׳:ל׳) צַהֲלִי קוֹלֵךְ בַּת גַּלִּים הַקְשִׁיבִי לַיְשָׁה עֲנִיָּה עֲנָתוֹת. הַאי קְרָא אוּקְמוּהָ חַבְרַיָא. אֲבָל הַאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְּמָר. צַהֲלִי קוֹלֵךְ בַּת גַּלִּים, בְּרַתֵּיהּ דְּאַבְרָהָם אָבִינוּ הָכִי אוּקְמוּהָ בַּת גַּלִּים כְּדִכְתִיב, (שיר השירים ד׳:י״ב) גַּל נָעוּל. גַּלִּים אִנּוּן נְהוֹרִין דְּמִתְכַּנְשֵׁי וְאָזְלֵי וְעָאלִין לְגַוָּוהּ וּמַלְיָין לָהּ כְּדִכְתִיב, (שיר השירים ד׳:י״ג) שְׁלָחַיִךְ פַּרְדֵּס רִמּוֹנִים.</p>\n<p>הַקְשִׁיבִי לַיְשָׁה כְּמָא דְאַתְּ אָמֵר (איוב ד׳:י״א) לַיִשׁ אוֹבֵד מִבְּלִי טֶרֶף. לַיִשׁ דְּכַר. לַיְשָׁה נוּקְבָא. אַמַּאי אִקְרֵי לַיִשׁ, אִי מִשּׁוּם (משלי ל׳:ל׳) דִּכְתִיב לַיִשׁ גִּבּוֹר בַּבְּהֵמָה, אוֹ מִשּׁוּם דִּכְתִיב לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף. אֶלָּא כֹּלָּא אִיהוּ לַיִשׁ גְּבוּרָה תַּתָּאָה וּדְאָתֵי מִגְּבוּרָה עִלָּאָה. לַיִשׁ אוֹבֵד מִבְּלִי טָרֶף, בְּשַׁעֲתָא דְּאִנּוּן נְחָלִין מִסְתַּלְקִין וְלָא עָאלִין לְגַוָּוהּ, כְּדֵין אִתְקְרֵי לַיְשָׁה דְּאֲבִידַת מִבְּלִי טֶרֶף. דִּכְתִיב לַיִשׁ אוֹבֵד מִבְּלִי <Nonei></i>טֶרֶף וּבְנֵי לָבִיא יִתְפָּרְדוּ.</p>\n<p>וּמַה דְּאָמַר לַיְשָׁה הַיְינוּ עֲנִיָּה עֲנָתוֹת מִסְּכֵּנָא דְּמִסְכֵּנוּתָא כְּמָא דְאַתְּ אָמֵר, (ירמיהו א׳:א׳) מִן הַכֹּהֲנִים אֲשֶׁר בַּעֲנָתוֹת וּכְתִיב, (מלכים א ב׳:כ״ו) עֲנָתֹת לֵךְ עַל שָׂדֶיךָ. מַאי אִירְיָא. אֶלָּא כָּל זִמְנָא דְּדָוִד מַלְכָּא הֲוָה קַיָּים, אִסְתַּלַּק אֶבְיָתָר בְּעוּתְרָא וּבְכֹלָּא. לְבָתַר אָמַר לֵיהּ שְׁלֹמֹה עֲנָתוֹת לֵךְ עַל שָׂדֶיךָ.</p>\n<p>אַמַּאי קָרֵי לֵיהּ שְׁלֹמֹה הָכִי. אֶלָּא אָמַר לֵיהּ בְּיוֹמָךְ הֲוָה אַבָּא בְּמִסְכֵּנוּ וְהַשְׁתָּא לֵךְ עַל שָׂדֶיךָ. הַשְׁתָּא אִית לוֹמַר אַמַּאי אִקְרֵי אֶבְיָתָר עֲנָתוֹת. אִי תֵימָא דְּהֲוָה מִן עֲנָתוֹת, הָא תָּנִינָן דִּכְתִיב, (שמואל א כ״ב:כ׳) וַיִּמָּלֵט בֵּן אֶחָד לַאֲחִימֶלֶךְ בֶּן אֲחִיטוּב וּשְׁמוֹ אֶבְיָתָר. וְהוּא מִנּוֹב הֲוָה, דְּהָא נוֹב עִיר הַכֹּהֲנִים הֲוָה. וְאַף עַל פִּי דְּאָמְרוּ דְּהִיא נוֹב הִיא עֲנָתוֹת וְאַמַּאי לָהּ אִקְרֵי עֲנָתוֹת בְּגִין דְּנָחֲתַת לְמִסְכֵּנוּ וְאִתְאֲבִיד קַרְתָּא עַל יְדָא דְשָׁאוּל וְאִתְאֲבִידוּ כָּהֲנִי. אֶלָּא עֲנָתוֹת כְּפַר הֲוָה, וְלָאו הוּא נוֹב, וְעַל דָּא קָרֵי לֵיהּ אֶבְיָתָר עֲנָתוֹת, בְּגִין דְּאָמַר (מלכים א ב׳:כ״ו) וְכִי הִתְעַנִּיתָ בְּכֹל אֲשֶׁר הִתְעַנָּה אָבִי. וּמִקַּרְתָּא דְנוֹב הֲוָה, וְעַל מִסְכְּנוּ דְּדָוִד דְּהֲוָה בְּיוֹמוֹי אִקְרֵי לֵיהּ הָכִי.</p>\n<p>אָמַר רַבִּי חִיָּיא בְּמִסְכְּנוּתָא הֲוָה עָלְמָא מִיּוֹמָא דְּעֲבַר אָדָם עַל פִּקּוּדֵי קוּדְשָׁא בְּרִיךְ הוּא, עַד דְּאָתָא נֹחַ וְקָרִיב קָרְבָּן וְאִתְיְישַׁב עָלְמָא. אָמַר רַבִּי יוֹסֵי לָא אִתְיְישַׁב עָלְמָא וְלָא נַפְקָא אַרְעָא מִזּוּהֲמָא דְּנָחָשׁ עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי וְאִתְאֲחִידוּ בְּאִילָנָא דְחַיֵּי כְּדֵין אִתְיְישַׁב עָלְמָא.</p>\n<p>וְאִלְמָלֵא דְהָדְרוּ יִשְׂרָאֵל וְחָאבוּ קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא לָא הֲווּ מֵתִין לְעָלְמִין. דְּהָא אִתְפַּסַּק מִנַּיְיהוּ זוּהֲמָא דְנָחָשׁ. כֵּיוָן דְּחָבוּ כְּדֵין אִתְבָּרוּ אִנּוּן לוּחֵי קַדְמָאֵי, דְּהֲווּ בְּהוּ חֵירוּ דְּכֹלָּא. חֵירוּ דְּהַהוּא נָחָשׁ דְּאִיהוּ קֵץ כָּל בָּשָׂר.</p>\n<p>וְכַד קָמוּ לֵיוָאֵי לְקַטְלָא קְטָלָא, כְּדֵין אִתְעַר חִוְיָא בִּישָׁא וְהֲוָה אָזִיל קַמַּיְיהוּ וְלָא יָכִיל לְשַׁלְטָאָה בְּהוּ, בְּגִין דְּהֲווּ יִשְׂרָאֵל מִזְדָּרְזִין כֻּלְהוּ בְּחֲגִירוּ מְזַיְינָן וְלָא יָכִיל הַהוּא נָחָשׁ לְשַׁלְטָאָה בְּהוּ. וְכֵיוָן דְּאָמַר לְמשֶׁה (שמות ל״ג:ה׳) וְעַתָּה הוֹרֵד עֶדְיְךָ מֵעָלֶיךָ, אִתְיְיהִיב רְשׁוּ לְהַאי נָחָשׁ לְשַׁלְטָאָה עֲלַיְיהוּ.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, (שמות ל״ג:ו׳) וַיִּתְנַצְּלוּ בְּנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חֹרֵב. וַיִּתְנַצְּלוּ וַיְנַצְּלוּ מִבָּעֵי לֵיהּ. אֶלָּא וַיִּתְנַצְּלוּ עַל יְדָא דְּאַחֲרָא בְּגִין דְּאִתְיְיהִיב רְשׁוּ לְנָחָשׁ לְשַׁלְטָאָה. אֶת עֶדְיָם מֵהַר חוֹרֵב דְּקִבְּלוּ מִטּוּרָא דְחוֹרֵב כַּד אִתְיְיהִיב אוֹרַיְיתָא לְיִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי חִיָּיא נֹחַ דְּהֲוָה צַדִּיק אַמַּאי לָא הֲוָה בָּטִיל מוֹתָא מֵעָלְמָא. אֶלָּא בְּגִין דְּעַד לָא סָלְקַת זוּהֲמָא מֵעָלְמָא. וְעוֹד דְּאִנּוּן לָא הֲווּ מְהֵימְנִין בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְכֻלְהוּ אֲחִידָן בְּטַרְפֵּי אִילָנָא לְתַתָּא וּמִתְלַבְּשָׁאן בְּרוּחַ מְסָאֳבָא.</p>\n<p>וְתוּ לְבָתַר אוֹסְפוּ לְמֶחטֵי וּלְמֵהַךְ בָּתַר יֵצֶר הָרָע כַּד בְּקַדְמִיתָא: וְאוֹרַיְיתָא קַדִּישָׁא דְּאִיהִי אִילָנָא דְחַיֵּי אַכַּתֵּי לָא נָחִית לָהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא. וְתוּ דְּאִיהוּ אַמְשִׁיךְ לֵיהּ בְּעָלְמָא לְבָתַר דִּכְתִיב וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלה וְהָא אִתְּמָר.</p>"],[9520011150,"<p>עַד דְּהֲווּ אָזְלֵי, חָמוּ חַד יוּדָאי דְּהֲוָה אָתֵי. אָמַר רַבִּי יוֹסֵי הַאי בַּר נָשׁ יוּדָאי אִיהוּ וְאִתְחֲזֵי. כַּד מָטָא גַּבַּיְיהוּ שְׁאִילוּ לֵיהּ. אָמַר לוֹן שְׁלִיחָא דְמִצְוָה אֲנָא. דְּהָא אֲנַן דָּיְירֵי בִּכְפַר דְּרָאמִין, וּמָטֵי זִמְנָא דְחַג, וְאֲנַן צְרִיכִין לוּלָב וְזִינִין דְּעִמֵּיהּ, וְאֲנָא אָזִיל לְקָטְעָא לוֹן לְמִצְוָה. אֲזְלוּ כְּחֲדָא.</p>\n<p>אָמַר לְהוּ הַהוּא יוּדָאי הַנִּי אַרְבַּע מִינִין דְּלוּלָב דְּבְּכֻלְהוֹ אָתָאן לְרַצוּיֵי עָלְמָא (נ\"א על מיא) שְׁמַעְתּוּן אַמַּאי אֲנַן צְרִיכִין לוֹן בַּחַג. אָמַר לֵיהּ כְּבָר אִתְעָרוּ בְּהוּ חַבְרַיָיא. אֲבָל אִי מִלָּה חַדְתָּא אִיהוּ תְּחוֹת יְדָךְ אֵימָא לָהּ.</p>\n<p>אָמַר לוֹן וַדַּאי הַהוּא אֲתַר דְּאֲנַן דָּיְירֵי בֵּיהּ הוּא זְעֵיר וְכֻלְהוּ עָסְקֵי בְּאוֹרַיְיתָא. וְאִית עֲלָן צוּרְבָא מֵרַבָּנָן רַבִּי יִצְחָק בַּר יוֹסֵי מֵחוֹזָאָה שְׁמֵיהּ. וּבְכָל יוֹמָא וְיוֹמָא אָמַר לָן מִלִּין חַדְתִּין בְּאוֹרַיְיתָא. וְאָמַר דְּהָא בְּחַג זִמְנָא הוּא לְשַׁלְטָאָה. (ישראל שליטין בההוא זמנא, ונקיטנא לולב דמתחזי דאנן נציחנא עלייהו על כל אנון דאקרון הממ העם ולשלטאה עלייהו) (אזי עבר על נפשנו המים הזדונים ברוך יי שלא נתננו טרף לשניהם. וכי אית שנים למים, אלא) (ס\"א דכל אנון רברבין) אִנּוּן שְׁאָר עַמִּין. אִנּוּן רַבְרְבִין מְמַנָּן עַל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וּמִתְבָּרְכָאן מִסִּטְרַיְיהוּ דְיִשְׂרָאֵל וְקָרִינָן לוֹן מַיִם הַזֵּידוֹנִים. כְּמָא דְאַתְּ אָמֵר, (תהילים קכ״ד:ה׳) הַמַּיִם הַזֵּדוֹנִים.</p>\n<p>וּבְגִין לְשַׁלְטָאָה עֲלַיְיהוּ אָתֵינָא בְּרָזָא דִשְׁמָא קַדִּישָׁא בְּאִנּוּן אַרְבַּע מִינִין שֶׁבַּלּוּלָב לְרַצּוּיֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא (עלייהו) וּלְשַׁלְטָאָה <Nonei></i>עֲלַיְיהוּ בְּרָזָא דִשְׁמָא קַדִּישָׁא. וּלְאַתְעָרָא עֲלָן מַיִין קַדִּישִׁין לְנַסְכָא עַל גַּבֵּי מַדְבְּחָא.</p>\n<p>תּוּ אָמַר לוֹן בְּרֹאשׁ הַשָּׁנָה אִתְעֲרוּתָא קַדְמָאָה אִיהוּ בְּעָלְמָא. מַאי אִתְעֲרוּתָא קַדְמָאָה. דָּא בֵּי דִינָא דִּלְתַתָּא (נ\"א דא ראש השנה ממש) דְּאִתְעַר לְמֵידַן עַלְמָא. וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל עָלְמָא בְּדִינָא וְדָאִין עָלְמָא.</p>\n<p>וְשָׁלְטָא הַאי בֵּי דִינָא לְמֵידַן עָלְמָא, עַד יוֹמָא דְכִפּוּרֵי דְּנָהֲרִין אַנְפָּהָא, וְלָא אִשְׁתְּכַח חִוְיָא דַּלְטוֹרָא בְּעָלְמָא. דְּאִיהוּ אִתְעַסַּק בַּמֶה דְאַתְיָין לֵיהּ הַהוּא שָׂעִיר דְּאִיהוּ מִסִּטְרָא דְּרוּחַ מְסָאֳבָא כְּדְקָא חָזֵי לֵיהּ. וּבְגִין דְּאִתְעַסַּק בְּהַהוּא שָׂעִיר לָא קָרִיב לְמַקְדְּשָׁא.</p>\n<p>וְשָׂעִיר דָּא כְּהַהוּא שָׂעִיר דְּרֹאשׁ חֹדֶשׁ דְּאִתְעַסַּק בֵּיהּ וְאַנְהִירוּ אַנְפָּהָא דְרֹאשׁ הַשָׁנָה (נ\"א כך בראש השנה) (נ\"א אנהירו) (אנפוי דמקדשא). וְעַל דָּא יִשְׂרָאֵל כֻּלְהוּ מַשְׁכְּחִין רַחֲמֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִתְעֲבַר חוֹבַיְיהוּ. וְרָזָא חָדָא אָמַר לוֹן וְלָא אִתְיְיהִיב רְשׁוּ לְגַלָּאָה בַּר לְחֲסִידֵי קַדִּישִׁין עֶלְיוֹנִין חַכִּימִין. אָמַר רַבִּי יוֹסֵי מַאן אִיהוּ. אָמַר לוֹן עַד לָא בָּדִיקְנָא בְּכוּ.</p>\n<p>אֲזְלוּ. לְבָתַר אָמַר לוֹן. כַּד סִיהֲרָא אִתְקְרִיבַת בְּשִׁמְשָׁא. אַתְעַר קוּדְשָׁא בְּרִיךְ הוּא סִטְרָא דְצָפוֹן וְאָחִיד בָּהּ בִּרְחִימוּ וּמָשִׁיךְ לָהּ לְגַבֵּיהּ, וְדָרוֹם אִתְעַר מִסִּטְרָא אָחֳרָא. וְסִיהֲרָא סַלְקָא וּמִתְחַבְּרָא בְּמִזְרָח. וּכְדֵין יָנְקָא מִתְּרֵין סִטְרִין וּנְטִילַת בִּרְכָאן בַּחֲשַׁאי, וּכְדֵין אִתְבָּרְכָא סִיהֲרָא וְאִתְמַלְיָיא. וְהָכָא אִתְקְרִיבַת אִתְּתָא בְּבַעֲלָהּ.</p>\n<p>כְּמָה דְאִית רָזָא דִּיוּקְנָא שַׁיְיפֵי (נ\"א בתיקוני דשייפי) דְאָדָם וְתִיקּוּנוֹי. הָכִי נָמֵי אִית (נ\"א איהו) רָזָא דְּדִיוּקְנָא דְּשַׁיְיפֵי נוּקְבָא וְתִקּוּנִי דְנוּקְבָא. וְכֹלָּא פָּרִישׁ בְּגַוָון. הָכִי נָמֵי אִית לְעֵילָא (ד\"א מאן) אָחִיד בָּהּ וְאִתְעַר לָקֳבֵל בִּרְחִימוּ הָכִי נֲמֵי אִית לְתַתָּא רָזָא וְתִקּוּנָא דְּאָדָם תַּתָּאָה אָחֳרָא תְּחוֹת סִיהֲרָא (ד\"א ותקונא דנוקבא).</p>\n<p>כְּמָה דִדְרוֹעָא שְׂמָאלָא (תשא קצד ב, פקודי רלג ב) לְעֵילָא אָחִיד בָּהּ וְאִתְעַר לְקֳבְלָהּ בִּרְחִימוּ. הָכִי נָמֵי אִית לְתַתָּא. (ווי העמודים כלהו קיימי שייפין לאתאחדא דא בדא ולאתקשרא דא בדא קשרי מהימנותא סטרא דקדושא מסטרא דרוח מסאבא דאיהו רזא דנחש לתתא). הַאי נָחָשׁ אִיהוּ דְרוֹעָא שְׂמָאלָא דְרוּחַ מְסָאֳבָא. וְאָחִיד בֵּיהּ מַאן דְּרָכִיב בֵּיהּ וְקָרָבָא לְגַבֵּי דְסִיהֲרָא וּמָשִׁיךְ לָהּ בֵּינַיְיהוּ נ\"א בִּדְבִיקוּ דְּקוּטְפָא וְאִסְתָּאֳבַת.</p>\n<p>וּכְדֵין יִשְׂרָאֵל לְתַתָּא מְקָרְבִין שָׂעִיר. וְהַהוּא נָחָשׁ אִתְמְשַׁךְ אֲבַתְרֵיהּ דְּהַהוּא שָׂעִיר. וְסִיהֲרָא אִתְדְּכִיאַת וְסַלְקָאת לְעֵילָא וְאִתְקְּשָׁרַת לְעֵילָא לְאִתְבָּרְכָא. וּנְהִירִין אַנְפָּהָא מַה דְּאִתְחַשְׁכַת לְתַתָּא.</p>\n<p>כְּדֵין הָכָא בְּיוֹמָא דְכִפּוּרֵי כֵּיוָן דְּהַהוּא חִוְיָא בִּישָׁא אִתְעַסַּק בְּהַהוּא שָׂעִיר. סִיהֲרָא אִתְפָּרְשַׁת מִנֵּיהּ וְאִתְעַסְּקַת (בישראל) לְאוֹלָפָא עֲלַיְיהוּ סָנֵיגוֹרְיָא וְסוֹכֶכֶת עֲלַיְיהוּ כְּאִמָּא עַל בְּנִין. וְקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לוֹן מִלְּעֵילָא וּמָחִיל לוֹן.</p>\n<p>לְבָתַר יִשְׂרָאֵל כַּד מָטוּ לַחַג מִתְעָרֵי סִטְרָא דְּיָמִינָא לְעֵילָא. בְּגִין דְּיִתְקַשַּׁר בֵּיהּ סִיהֲרָא וְיִתְנְהִירוּ אַנְפָּהָא כְּדְקָא חָזֵי. וּכְדֵין פַּלְגַת (יהב) חוּלָקָא דְּבִרְכָאן לְכָל אִנּוּן מְמַנָּן דִּלְתַתָּא דְּיִתְעַסְּקוּן בְּחוּלַקְהוֹן. וְלָא יֵיתוּן לְיָנְקָא וּלְקָרָבָא בְּסִטְרָא דְּחוּלַקְהוֹן דְּיִשְׂרָאֵל.</p>\n<p>כְּגַוְונָא דָא לְתַתָּא כַּד שְׁאָר עַמִין אִתְבָּרְכוּן. כֻּלְהוֹן אִנּוּן מִתְעַסְּקִין בְּאַחְסָנַת חוּלַקְהוֹן. וְלָא הֲווּ אַתְיָין לְאִתְעָרְבָא בַּהֲדַיְיהוּ דְיִשְׂרָאֵל וּלְחָמְדָא חוּלַק אַחְסַנְתֵּיהוֹן. וּבְגִין כָּךְ יִשְׂרָאֵל אִנּוּן מָשְׁכִין בִּרְכָאן לְכָל אִנּוּן מְמַנָּן בְּגִין דְּיִתְעַסְּקוּן בְּחוּלַקְהוֹן וְלָא יִתְעָרְבוּן בַּהֲדַיְיהוּ.</p>\n<p>וְכַד סִיהֲרָא אִתְמְלֵי בִּרְכָאן לְעֵילָא כְּדְקָא יְאוּת. יִשְׂרָאֵל אָתְיָין וְיָנְקִין מִינָּהּ בִּלְחוֹדַיְיהוּ. וְעַל דָּא כְּתִיב (במדבר כ״ט:ל״ה) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. מַאי עֲצֶרֶת, כְּתַרְגּוּמוֹ כְּנִישׁוּ. כָּל מַה דִּכְנִישׁוּ מֵאִנּוּן בִּרְכָאן עִלָּאִין. לָא יָנְקִין מִנֵּיהּ עַמִּין אָחֳרָנִין בַּר יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. וּבְגִין כָּךְ כְּתִיב עֲצֶרֶת תִּהְיֶה לָכֶם. לָכֶם וְלָא לִשְׁאָר עַמִּין. לָכֶם וְלָא לִשְׁאָר מְמַנָּן.</p>\n<p>וְעַל דָּא אִנּוּן מְרַצִּין עַל הַמַּיִם לְמֵיהַב לוֹן חוּלַק בִּרְכָאן דְּיִתְעַסְּקוּן בֵּיהּ. וְלָא יִתְעָרְבוּן לְבָתַר בְּחֶדְוָותָא דְיִשְׂרָאֵל כַּד יָנְקִין בִּרְכָאן עִלָּאִין. וְעַל הַהוּא יוֹמָא כְּתִיב דּוֹדִי לִי וַאֲנִי לוֹ. דְּלָא אִתְעָרַב אוֹחֲרָא בַּהֲדָן.</p>\n<p>לְמַלְכָּא דְּזַמַּן רְחִימוֹי בִּסְעוּדָתָא עִלָּאָה דְּעֲבִיד לֵיהּ לְיוֹמָא רְשִׁימָא. הָא רְחִימוֹי דְמַלְכָּא יְדַע דְּמַלְכָּא <Nonei></i>אִתְרָעֵי בֵּיהּ. אָמַר מַלְכָּא הַשְׁתָּא אֲנָא בָּעֵי לְמֶחֱדֵי עִם רְחִימָאי. וְדָחִילְנָא דְּכַד אֲנָא בִּסְעוּדָתָא עִם רְחִימָאי יַעֲלוּן כָּל אִנּוּן קַסְטוֹרֵי מְמַנָּן וִיתִיבוּן עִמָּנָא לִפְתוֹרָא לְמִסְעַד סְעוּדָתָא דְחֶדְוָה עִם רְחִימָאי. מָה עֲבַד אַקְדִים הַהוּא רְחִימוֹי קוּסְטוּרִין דִּירוֹקֵי וּבִשְׂרָא דְתוֹרֵי וְאַקְרִיב קַמַּיְיהוּ דְּאִנּוּן קַסְטוּרֵי מְמַנָּן לְמֵיכַל. לְבָתַר יָתִיב מַלְכָּא עִם רְחִימוֹי לְהַהִיא סְעוּדָתָא עִלָּאָה מִכָּל עִדּוּנִין דְּעָלְמָא. וּבְעוֹד דְּאִיהוּ בִּלְחוֹדוֹי עִם מַלְכָּא שָׁאִיל לֵיהּ כָּל צָרְכּוֹי וְיָהִיב לֵיהּ. וְאַחֲדֵי מַלְכָּא עִם רְחִימוֹי בִּלְחוֹדוֹהִי וְלָא אִתְעָרְבִין אָחֳרָנִין בֵּינַיְיהוּ. כָּךְ יִשְׂרָאֵל עִם קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין כָּךְ כְּתִיב בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.</p>\n<p>אָמְרוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא קוּדְשָׁא בְּרִיךְ הוּא אַתְקִין אוֹרְחָא קַמָּן. זַכָּאִין אִנּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. אָתֵי נְשָׁקוּהוּ. קָרָא עֲלֵיהּ רַבִּי יוֹסֵי (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ וְרַב שְׁלוֹם בָּנָיִךְ. כַּד מָטוּ בֵּי חֲקַל יָתִיבוּ. אָמַר הַהוּא בַּר נָשׁ מַאי שְׁנָא דִּכְתִיב, (בראשית י״ט:כ״ד) וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה וְגו'. (נדפס בפקודי רכז ב) וּמַאי שְׁנָא בְּטוֹפָנָא דִּכְתִיב אֱלהִים אֱלהִים בְּכָל אֲתַר. (אמאי) וְלָא כְּתִיב וַיְיָ (בכלא).</p>\n<p>אֶלָּא תָּנִינָן בְּכָל אֲתַר דִּכְתִיב וַיְיָ הוּא וּבֵית דִּינוֹ. אֱלֹהִים סְתָם דִּינָא בִּלְחוֹדוֹי. אֶלָּא בִּסְדוֹם אִתְעֲבִיד דִּינָא וְלָא לְשֵׁיצָאָה עָלְמָא. וּבְגִין כָּךְ אִתְעָרֵב אִיהוּ בַּהֲדֵי דִינָא. אֲבָל בְּטוֹפָנָא כָּל עָלְמָא שָׁצֵי וְכָל אִנּוּן דְּאִשְׁתַּכָּחוּ (נ\"א בלחודוי) בְּעָלְמָא.</p>\n<p>וְאִי תֵימָא (ד\"א דהא) נֹחַ וּדְעִמֵּיהּ (ד\"א אשתזיבו). (נ\"א הא) סָתִים מַעֲיָנָא הֲוָה דְּלָא אִתְחֲזֵי. וְעַל דָּא כָּל מַה דְּאִשְׁתְּכַח בְּעָלְמָא שָׁצֵי לֵיהּ. וְעַל דָּא וַיְיָ בְּאִתְגַלְיָא וְלָא שָׁצֵי כֹלָּא. אֱלהִים בָּעֵי סְתִימוּ וּבָעֵי לְאִסְתַּמְּרָא דְּהָא כֹּלָּא שָׁצֵי. וְעַל דָּא אֱלהִים בִּלְחוֹדוֹי הֲוֵי.</p>\n<p>וְרָזָא דָּא (תהילים כ״ט:י׳) יְיָ לַמַּבּוּל יָשָׁב. מַהוּ יָשָׁב. אִלְמָלֵא קְרָא כְּתִיב לָא יָכְלִינָן לְמֵימַר. יָשָׁב בִּלְחוֹדוֹי דְּלָא אַתְיָא עִם דִּינָא. כְּתִיב הָכָא יָשָׁב, וּכְתִיב הָתָם (ויקרא י״ג:מ״ו) בָּדָד יֵשֵׁב בִּלְחוֹדוֹי.</p>\n<p>וּבְגִין דְּנֹחַ הֲוָה סָתִים מַעֲיָנָא. לְבָתַר כַּד אִתְעֲבִיד דִּינָא וְשָׁצֵי עָלְמָא וְנָח רוּגְזֵיהּ מַה כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ וְגו'. דְּהָא כַּד שָׁצֵי עָלְמָא לָא אִדְכַּר דְּסָתִים מַעֲיָנָא הֲוָה.</p>\n<p>וְרָזָא (ודא) אוֹלִיפְנָא קוּדְשָׁא בְּרִיךְ הוּא סָתִים וְגַלְיָא. גַּלְיָא הוּא בֵּי דִינָא דִלְתַתָּא. סָתִים הוּא אֲתַר דְּכָל בִּרְכָאן נָפְקֵי מִתַּמָּן. וּבְגִין כָּךְ כָּל מִלּוֹי דְּבַר נָשׁ דְּאִנּוּן בִּסְתִימוּ בִּרְכָאן שַׁרְיָין עֲלוֹי. וְכָל דְּאִנּוּן בְּאִתְגַּלְּיָא הַהוּא אֲתַר דְּבֵי דִינָא שָׁרְיָאן עֲלוֹי בְּגִין דְּאִיהוּ אֲתַר בְּאִתְגְּלֵי וְהַהוּא דְאִקְרֵי רַע עַיִן שַׁלִּיט עֲלֵיהּ, וְכֹלָּא הוּא בְּרָזָא עִלָּאָה כְּגַוְונָא דִלְעֵילָא.</p>\n<p>בָּכָה רַבִּי יוֹסֵי וְאָמַר זַכָּאָה דָרָא דְּרַבִּי שִׁמְעוֹן שַׁרְיָא בְּגַוֵּיהּ דְּהָא זְכוּתָא דִילֵיהּ אַזְמִין לָן בְּטוּרֵי מִלִּין עִלָּאִין כְּאִלֵּין (עד כאן). אָמַר רַבִּי יוֹסֵי הַאי בַּר נָשׁ לְאוֹדָעָא לָן מִלִּין אִלֵּין קָא אָתֵי וְשַׁדְרֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְגַבָּן. כַּד אָתוּ וְסִדְּרוּ מִלִּין קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אָמַר וַדַּאי שַׁפִּיר קָא אָמַר.</p>"],[9520011151,"<p>(נדפס בפקודי רסח ב)רַבִּי אֶלְעָזָר הֲוָה יָתִיב יוֹמָא חַד קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אֲבוּי. אָמַר לֵיהּ הַאי קֵץ כָּל בָּשָׂר אִתְהַנֵּי מֵאִנּוּן קָרְבָּנִין דְּהֲווּ יִשְׂרָאֵל מְקָרְבִין עַל גַּבֵּי מַדְבְּחָא אוֹ לָא. אָמַר לֵיהּ כֹּלָּא הֲווּ מִסְתַּפְּקֵי כְּחֲדָא לְעֵילָא וְתַתָּא.</p>\n<p>וְתָא חֲזֵי כַּהֲנִי וְלֵיוָאֵי וְיִשְׂרָאֵל אִנּוּן אִקְרוּן אָדָם בְּחִבּוּרָא דְּאִנּוּן רְעוּתִין קַדִּישִׁין דְּסָלְקִין מִגַּוַויְיהוּ. הַהוּא כִּשְׂבָּא אוֹ אִמְרָא אוֹ הַהִיא בְּהֵמָה דְּקָרְבִין אִצְטְרִיךְ עַד לָא יִתְקְרִיב עַל גַּבֵּי מַדְבְּחָא לְפָרָשָׁא עֲלָהּ כָּל חַטָּאִין וְכָל רְעוּתִין בִּישִׁין לְאִתְוַדָּאָה עֲלָהּ. וּכְדֵין הַהִיא אִתְקְרֵי בְּהֵמָה בְּכֹלָּא בְּגוֹ אִנּוּן חַטָּאִין וּבִישִׁין וְהִרְהוּרִין.</p>\n<p>כְּגַוְונָא דְּקָרְבָּנָא דַּעֲזָאזֵל דִּכְתִיב (ויקרא ט״ז:כ״א) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת בְּנֵי יִשְׂרָאֵל וְגו'. הָכִי נָמֵי הָכָא. וְכַד סָלְקָא עַל גַּבֵּי מַדְבְּחָא מְטוּלָא עַל חַד תְּרֵין. וּבְגִין כָּךְ דָא סַלְקָא לְאַתְרֵיהּ. וְדָא סַלְקָא לְאַתְרֵיהּ. דָּא בְּרָזָא דְאָדָם וְדָא בְּרָזָא דִבְהֵמָה כְּמָה דְאַתְּ אָמֵר (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ.</p>\n<p>חֲבִיתִין וְכָל שְׁאָר מְנָחוֹת לְאַתְעָרָא רוּחָא קַדִּישָׁא בִּרְעוּתָא דְּכַהֲנֵי וְשִׁירָתָא דְּלֵיוָאֵי וּבִצְלוֹתָא דְיִשְׂרָאֵל. וּבְהַהוּא תְּנָנָא וְשַׁמְנָא וְקִמְחָא דְּסָלִיק מִתְרַוָּון וּמִסְתַּפְּקִין (ס\"א ומתפנקין) (ס\"א ומתפשטין) <Nonei></i>כָּל שְׁאָר מָארֵי דְדִינִין דְּלָא יָכְלִין לְשַׁלְטָאָה בְּהַהוּא דִינָא דְאִתְמָסַר לוֹן. וְכֹלָּא בְּזִמְנָא חָדָא. תָּא חֲזֵי, כֹּלָּא אִתְעֲבִיד בְּרָזָא דִמְהֵימְנוּתָא לְאִסְתַּפְּקָא דָּא בְּדָא, וּלְאִסְתַּלָּקָא לְעֵילָא מָאן דְּאִצְטְרִיךְ עַד אֵין סוֹף.</p>"],[9520011152,"<p>(נדפס בפקודי רכא א, רסח ב) אָמַר רַבִּי שִׁמְעוֹן אֲרֵימַת יְדָאי בִּצְלוֹתִין לְעֵילָא, דְּכַד רְעוּתָא עִלָּאָה לְעֵילָא לְעֵילָא קָיְימָא עַל הַהוּא רְעוּתָא דְּלָא אִתְיְדָע וְלֹא אִתְפַּס כְּלַל לְעָלְמִין רֵישָׁא דְּסָתִים יַתִּיר לְעֵילָא. וְהַהוּא רֵישָׁא אַפִּיק מַאי דְאַפִּיק וְלָא יְדִיעַ וְנָהִיר מַאי דְנָהִיר כֹּלָּא בִּסְתִימוּ.</p>\n<p>רְעוֹ דְּמַחֲשָׁבָה עִלָּאָה לְמִרְדַּף אֲבַתְרֵיהּ וּלְאִתְנְהָרָא מִנֵּיהּ. חַד פְּרִיסוּ אִתְפְּרִיס. וּמִגּוֹ הַהוּא פְּרִיסָא בִּרְדִיפוּ דְּהַהִיא מַחֲשָׁבָה עִלָּאָה מָטֵי וְלָא מָטֵי עַד הַהוּא פְּרִיסָא נָהִיר מַה דְּנָהִיר. וּכְדֵין (ס\"א ההוא) אִיהוּ מַחֲשָׁבָה עִלָּאָה נָהִיר בִּנְהִירוּ (בסתימו) סָתִים דְּלָא יְדִיעַ וְהַהוּא מַחֲשָׁבָה לָא יָדַע.</p>\n<p>כְּדֵין בָּטַשׁ הַאי נְהִירוּ דְּמַחֲשָׁבָה דְּלָא אִתְיְידַע בִּנְהִירוּ דְּפַרְסָא דְּקָיְימָא דְּנָהִיר מִמַּה דְּלָא יְדִיעַ וְלָא אִתְיְידַע וְלָא אִתְגַּלְיָיא. וּכְדֵין (נ\"א האי) דָּא נְהִירוּ דְּמַחֲשָׁבָה דְּלָא אִתְיְידַע בָּטַשׁ בִּנְהִירוּ דִּפְרִיסָא וְנָהֲרִין כְּחֲדָא וְאִתְעֲבִידוּ תֵּשַׁע הֵיכָלִין.</p>\n<p>וְהֵיכָלִין לָאו אִנּוּן נְהוֹרִין וְלָאו אִנּוּן רוּחִין וְלָאו אִנּוּן נִשְׁמָתִין. וְלָא אִית (איהו) מָאן דְּקָיְימָא בְּהוּ. רְעוּתָא דְּכָל תֵּשַׁע נְהוֹרִין דְּקָיְימֵי כֻּלְהוּ בְּמַחֲשָׁבָה דְּאִיהוּ חַד מִנַּיְיהוּ בְּחוּשְׁבְּנָא כֻּלְהוּ לְמִרְדַּף בַּתְרַיְיהוּ בְּשַׁעֲתָא דְּקָיְימֵי בְּמַחֲשָׁבָה וְלָא מִתְדַּבְּקָן וְלָא אִתְיְידָעוּ. וְאִלֵּין לָא קָיְימֵי לָא בִּרְעוּתָא וְלָא בְּמַחֲשָׁבָה עִלָּאָה (נ\"א עלאין). תָּפְסִין בָּהּ וְלָא תָפְסִין. בְּאִלֵּין קָיְימֵי כָּל רָזֵי דִמְהֵימְנוּתָא וְכָל אִנּוּן נְהוֹרִין מֵרָזָא דְּמַחֲשָׁבָה עִלָּאָה (דלתתא ד\"א ולתתא) כֻּלְהוּ אִקְרוּן אֵין סוֹף. עַד הָכָא מָטוּ נְהוֹרִין וְלָא מָטוּן וְלָא אִתְיְידָעוּ. לָאו הָכָא רְעוּתָא וְלָא מַחֲשָׁבָה.</p>\n<p>(כדין ד\"א כד) נָהִיר מַחֲשָׁבָה וְלָא אִתְיְידַע (ידיע) מִמַּאן דְּנָהִיר. כְּדֵין אִתְלַבֵּשׁ וְאַסְתִּים גּוֹ בִּינָה וְנָהִיר לְמַאן דְנָהִיר וְאָעִיל דָּא בְּדָא עַד דְּאִתְכְּלִילוּ כֻּלְהוּ כְּחֲדָא.</p>\n<p>וּבְרָזָא דְּקָרְבָּנָא כַּד סָלִיק כֹּלָּא אִתְקַשַּׁר דָּא בְּדָא וְנָהִיר דָּא בְּדָא. כְּדֵין קָיְימֵי כֻּלְהוּ בִּסְלִיקוּ וּמַחֲשָׁבָה אִתְעַטַּר בְּאֵין סוֹף. הַהוּא נְהִירוּ דְּאִתְנְהִיר מִנֵּיהּ מַחֲשָׁבָה עִלָּאָה (דלא אתיידע בה כלל) אִקְרֵי אֵין סוֹף. וּמִנֵּיהּ אִשְׁתְּכַח וְקָיְימָא וְנָהִיר לְמַאן דְּנָהִיר וְעַל דָּא כֹּלָּא קָאִים. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָא בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, הַאי קֵץ כָּל בָּשָׂר, כְּמָה דְּקִשּׁוּרָא אִשְׁתְּכַח לְעֵילָא בְּחֵדוּ, אוּף הָכִי נָמֵי לְתַתָּא בְּחֶדְוְותָא. וּרְעוּתָא לְאִסְתַּפְּקָא כֹּלָּא לְעֵילָא וְתַתָּא. וְאִימָּא קָיְימָא עֲלַיְיהוּ דְיִשְׂרָאֵל כְּדְקָא יְאוּת.</p>\n<p>תָּא חֲזֵי, בְּכָל רֵישֵׁי יַרְחָא וְיַרְחָא כַּד סִיהֲרָא מִתְחַדְּשָׁא יָהֲבִין לֵיהּ לְהַאי קֵץ כָּל בָּשָׂר חוּלְקָא חָדָא יַתִּיר עַל קָרְבָּנִין לְאִתְעַסְקָא בֵּיהּ וְיִשְׁתַּמֵּשׁ בְּחוּלָקֵיהּ. וִיהֵא סִטְרָא דְיִשְׂרָאֵל בִּלְחוֹדַיְיהוּ. בְּגִין דְּיִתְאַחֲדוּן בְּמַלְכֵיהוֹן, וְדָא אִיהוּ שָׂעִיר. בְּגִין דְּאִיהוּ בְּחוּלָקָא דְּעֵשָׂו דִּכְתִיב בֵּיהּ שָׂעִיר (בראשית כ״ז:י״א) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. וְעַל דָּא אִיהוּ אִשְׁתַּמַּשׁ בְּחוּלָקֵיהּ. וְיִשְׂרָאֵל אִנּוּן מִשְׁתַּמְּשִׁין בְּחוּלָקֵיהוֹן. וּבְגִין כָּךְ כְּתִיב, (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגוּלָתוֹ.</p>\n<p>תָּא חֲזֵי, הַאי קֵץ כָּל בָּשָׂר, כָּל רְעוּתֵיהּ לָאו אִיהוּ אֶלָּא בְּבִשְׂרָא תָּדִיר וּבְגִין כָּךְ תִּקּוּנָא דְבִשְׂרָא תָּדִיר לְגַבֵּיהּ וְעַל דָּא אִקְרֵי קֵץ כָּל בָּשָׂר. וְכַד אִיהוּ שַׁלִּיט, שַׁלִּיט עַל גּוּפָא וְלָא עַל נִשְׁמְתָא. נִשְׁמְתָא סָלְקָא לְאַתְרָא וּבִשְׂרָא אִתְיְהִיב לְאֲתַר דָּא. כְּגַוְונָא דָא בְּקָרְבָּנָא דִּרְעוּתָא סָלְקָא לְאֲתַר חָד, וּבִשְׂרָא לְאֲתַר חָד.</p>\n<p>וּבַּר נָשׁ דְּאִיהוּ זַכָּאָה אִיהוּ קָרְבָּנָא מַמָּשׁ לְכַפָּרָה. וְאָחֳרָא דְּלָאו אִיהוּ זַכָּאָה, לָאו אִיהוּ קָרְבָּנָא בְּגִין דְּבֵיהּ מוּמָא דִּכְתִיב, (ויקרא כב) כִּי לֹא לְרָצוֹן וְגו'. וְעַל דָּא צַדִּיקַיָא כַּפָּרָה אִנּוּן דְּעָלְמָא וְקָרְבָּנָא אִנּוּן בְּעָלְמָא (עד כאן): תָּא חֲזֵי, וַיֹּאמֶר אֱלהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי. לְמֵיטַל רְשׁוּ לְאַחְשָׁכָא אַפַּיְיהוּ <Nonei></i>דִּבְנֵי עָלְמָא. וּבְגִינֵי כָךְ הִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ. (ועל דא עשה לך תבת עצי גופר בגין לאשתזבא בה ולא יכיל לשלטאה עלך. רבי חייא ורבי יוסי הוו אזלי בארחא אמר חד) כְּתִיב וַיַעַשׂ נֹחַ כְּכֹל אֲשֶׁר צִוָהוּ ה'.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה וְגו'. וְכִי אַמַּאי אֲתָא חוּשְׁבְּנָא דָא לְמִמְנֵי. אֶלָּא אִילוּ לָא הֲוָה נֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה לָא יֵיעוּל לְתֵיבוּתָא וְלָא יִתְחַבַּר בַּהֲדָהּ. כֵּיוָן דְּאִשְׁתַּלִּים בְּשֵׁשׁ מֵאוֹת שָׁנָה כְּדֵין אִתְחַבַּר בַּהֲדָהּ.</p>\n<p>וְעַל דָּא מִן יוֹמָא דְּאִשְׁתַּלִּים חוֹבַיְיהוּ דִּבְנֵי עָלְמָא אוֹרִיךְ לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַד דְּאִשְׁתַּלִּים נֹחַ בְּשֵׁשׁ מֵאוֹת שָׁנָה וְאִשְׁתַּלִּים דַּרְגֵּיהּ כְּדְקָא יְאוּת וְהֲוָה צַדִּיק שְׁלִים. וּכְדֵין עָאל לְתֵיבוּתָא. וְכֹלָּא כְּגַוְונָא דִּלְעֵילָא: וְנֹחַ בֶּן שֵׁשׁ מֵאוֹת שָׁנָה כְּמָה דְאֲמָרָן. וּבְגִינֵי כָךְ לָא אִתְּמָר כְּבֶן שֵׁשׁ מֵאוֹת שָׁנָה. (ד\"א ל\"ג לקביל שית סטרין דעלמא). תּוּ פָּתַח וְאָמַר וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם. מַאי טַעְמָא הִנְנִי כֵּיוָן דְּאָמַר וַאֲנִי. אֶלָּא אֲנִי אָנֹכִי (נ\"א הנני) כֹּלָּא מִלָּה חָדָא הִיא.</p>"],[9520011153,"<p>תָּא חֲזֵי, בְּכָל אֲתַר אֲנִי אִתְעֲבִיד גּוּפָא לְנִשְׁמְתָא וַדַּאי דִּמְקַבְּלָא מִמַּה דִּלְעֵילָא. וּבְגִין כָּךְ אִתְרְמִיז בְּאָת קַיָּימָא דִּכְתִיב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ. אֲנִי דְּקָיְימָא בְּאִתְגַּלְּיָא מְזוּמֶנֶת לְמִנְדַע. אֲנִי כָּרְסְיָא לְמַה דִּלְעֵילָא. אֲנִי דְּעֲבִידְנָא נוּקְמִין לְדָרֵי דָרִין. וַאֲנִי כָּלִיל דְּכַר וְנוּקְבָא כְּחֲדָא. לְבָתַר אִתְרְשִׁים בִּלְחוֹדוֹי דְּאִזְדַּמַּן לְמֶעְבַּד דִּינָא. הִנְנִי. מֵבִיא אֶת הַמַּבּוּל מַיִם.</p>\n<p>כֵּיוָן דְּאָמַר מֵבִיא אֶת הַמַּבּוּל לָא יְדַעְנָא דְּאִיהוּ מַיִם. אֶלָא אֶת הַמַּבּוּל לְאַסְגָאָה מַלְאַךְ הַמָּוֶת, דְּאַף עַל גַּב דְּמַיָא הֲווּ. מְחַבְּלָא (לחבלא בהון מחבלא) (ד\"א הוה) אָזִיל בְּעָלְמָא לְשֵׁיצָאָה בְּאִנּוּן מַיִין.</p>\n<p>אֲנִי יְיָ, הָכִי תָּנִינָן נְאֱמָן אֲנָא לְשַׁלְּמָא אֲגַר טַב לְצַדִּיקַיָּא וּלְאִתְפָּרַע מֵרַשִׁיעַיָּא. וּבְגִין כָּךְ אַבְטַח לוֹן קְרָא לְצַדִּיקַיָּא בְּאֲנִי לְשַׁלְּמָא אֲגַר טַב דִּלְהוֹן לְעָלְמָא דְאָתֵי. וְאַגְזִים לְרַשִׁיעַיָּא לְאִתְפְּרַע מִנַּיְיהוּ לְעָלְמָא דְאָתֵי בְּאֲנִי.</p>\n<p>לְשַׁחֵת כָּל בָּשָׂר. כְּמָה דְאוֹקִימְנָא דְּדָא הוּא מְחַבְּלָא דְעָלְמָא. וְעַל דָּא כְּתִיב, (שמות י״ב:כ״ג) וְלֹא יִתֵּן הַמַּשְׁחִית לָבֹא אֶל בָּתֵּיכֶם לִנְגוֹף. וְדָא הוּא לְשַׁחֵת כָּל בָּשָׂר מִסִּטְרָא דְּקֵץ כָּל בָּשָׂר בָּא לְפָנַי. דְּהָא כֵּיוָן דְּמָטָא זִמְנָא דְּאוֹרִיךְ לוֹן קוּדְשָׁא בְּרִיךְ הוּא (ד\"א ל\"ג ואוריך לון) עַד דְּאַשְׁלִים נֹחַ לְשֵׁשׁ מֵאוֹת שָׁנָה כְּדֵין לְשַׁחֵת כָּל בָּשָׂר. אָמַר הָכִי אוֹלִיפְנָא מִשְׁמֵיהּ דְּרַבִּי יִצְחָק (ס\"א ברבי יוסי מחוזאי) דְּאָמַר לָן (נ\"א האי דאמרי לכון).</p>"],[9520011154,"<p>פָּתַח וְאָמַר, (ישעיהו ל״ח:י״א) אָמַרְתִּי לֹא אֶרְאֶה יָהּ יָהּ בְּאֶרֶץ הַחַיִּים לֹא אַבִּיט אָדָם עוֹד עִם יוֹשְׁבֵי חָדֶל. אָמַרְתִּי לא אֶרְאֶה יָהּ, כַּמָּה אֲטִימִין אִנּוּן בְּנִי נָשָׁא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בְּמִלֵּי דְאוֹרַיְיתָא, אֶלָּא מִסְתַּכְּלֵי בְּמִלּוֹי דְעָלְמָא וְאִתְנְשֵׁי מִנַּיְיהוּ רוּחָא דְחָכְמְתָא.</p>\n<p>דְּכַד בַּר נָשׁ אִסְתַּלַּק מֵהַאי עָלְמָא וְיָהִיב חוּשְׁבְּנָא לְמָארֵיהּ מִכָּל מַה דְּעֲבַד בְּהַאי עָלְמָא בְּעוֹד דְּאִיהוּ קָאִים רוּחָא וְגוּפָא כְּחֲדָא וְחָמֵי מַה דְּחָמֵי, עַד דְּאָזִיל לְהַהוּא עָלְמָא וּפָגַע לֵיהּ לְאָדָם הָרִאשׁוֹן יָתִיב לְתַרְעָא דְגִנְתָּא דְעֵדֶן לְמֶחמֵי כָּל אִנּוּן דְּנָטְרוּ פִּקּוּדֵי דְמָארֵיהוֹן וְחָדֵי בְּהוּ.</p>\n<p>וְכַמָּה צַדִּיקַיָּא סָחֳרָנֵיהּ דְּאָדָם. אִנּוּן דְּאִתְמְנָעוּ מֵאָרְחָא דְּגֵיהִנֹּם וְסָטוּ לְגַבֵּי אָרְחָא דְּגַן עֵדֶן. וְאִלֵּין אִקְרוּן יוֹשְׁבֵי חָדֶל. וְלָא כְּתִיב יוֹשְׁבֵי חָלֶד. בְּגִין דְּלָא הֲווּ כְּמוֹ חוּלְדָה דְּגָרְרָא וּמַנְחָא וְלָא יָדְעָא לְמַאן שַׁבְקָא. אֶלָּא יוֹשְׁבֵי חָדֶל. כְּמָא דְאַתְּ אָמֵר, (ישעיהו ב׳:כ״ב) חִדְלוּ לָכֶם מִן הָאָדָם וְגו' (אלא יושבי חדל) דְּאִתְמְנַע לוֹן מֵאָרְחָא דְּגִיהִנֹּם. וְאַתְקִיפוּ בְּהוּ לְאַעָלָא לְהוּ בְּגִנְתָּא דְעֵדֶן.</p>\n<p>דָּבָר אַחֵר יוֹשְׁבֵי חָדֶל אִנּוּן מָרֵיהוֹן דִּתְשׁוּבָה דִּמְנָעוּ גַּרְמַיְיהוּ מֵאִנּוּן חוֹבִין דְּחַיָּיבַיָא. וּבְגִין דְּאָדָם הָרִאשׁוֹן תָּב בִּתְיוּבְתָּא קַמֵּי מָארֵיהּ. יָתִיב (נ\"א עם) עַל אִנּוּן דְּאִתְמְנָעוּ מֵחוֹבֵיהוֹן וְאִנּוּן בְּנֵי חָדֶל. כְּמָא דְאַתְּ אָמֵר, (תהילים ל״ט:ה׳) אֵדְעָה מֶה חָדֵל אָנִי. וּבְגִין כָּךְ אִיהוּ יָתִיב לְתַרְעָא דְּגִנְתָּא דְּעֵדֶן וְחָדֵי בְּהוּ בְּצַדִּיקַיָּא דְּאַתְיָין בְּהַהוּא אוֹרְחָא דְּגִנְתָּא דְּעֵדֶן.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב אָמַרְתִּי לא אֶרְאֶה יָהּ. וְכִי מַאן יָכִיל לְמֶחמֵי יָהּ. אֶלָּא סוֹפָא דִקְרָא אוֹכַח דִּכְתִיב יָהּ בְּאֶרֶץ הַחַיִּים. תָּא חֲזֵי, כַּד (תרומה קמא) סָלְקִין נִשְׁמָתִין לְאֲתַר צְרוֹרָא דְחַיֵּי. תַּמָּן מִתְהַנָּן בְּזָהֳרָא דְּאַסְפַּקְלַרְיָאה דְּנָהֲרָא דְּנָהִיר <Nonei></i>מֵאֲתַר עִלָאָה דְכֹלָּא. וְאִילוּ לָא מִתְלַבְּשָׁא נִשְׁמָתָא בְּזָהֲרָא דִלְבוּשָׁא אָחֳרָא לָא תִיכוֹל לְאִתְקָרָבָא לְמֶחמֵי הַהוּא נְהוֹרָא.</p>\n<p>וְרָזָא דְמִלָּה כְּמָה דְּיַהֲבֵי לְנִשְׁמָתָא לְבוּשָׁא דְּמִתְלַבְּשָׁא בֵּיהּ לְמֵיקַם בְּהַאי עָלְמָא. הָכִי נָמֵי יַהֲבֵי לָהּ לְבוּשָׁא דְּזָהֲרָא עִלָּאָה לְמֵיקַם בֵּיהּ בְּהַהוּא עָלְמָא וּלְאִסְתַּכָּלָא בְּגוֹ הַהוּא אַסְפַּקְלַרְיָאה דְּנָהֲרָא מִגּוֹ הַהוּא אֶרֶץ הַחַיִּים.</p>\n<p>תָּא חֲזֵי, משֶׁה לָא יָכִיל לְקָרְבָא לְאִסְתַּכְּלָא בַּמֶּה דְאִסְתַּכַּל אֶלָּא כַּד אִתְלַבַּשׁ בִּלְבוּשָׁא אָחֳרָא כְּמָא דְאַתְּ אָמֵר (שמות כ״ד:י״ח) וַיָּבֹא משֶׁה בְּתוֹךְ הֶעָנָן וַיַּעַל אֶל הָהָר. וְתַרְגּוּם בִּמְצִיעוּת עֲנָנָא. וְאִתְלַבַּשׁ בָּהּ כְּמַאן דְּאִתְלַבַּשׁ בִּלְבוּשָׁא. וּבְגִין דָא (שמות כ׳:י״ח) וּמשֶׁה נִגַּשׁ אֶל הָעֲרָפֶל אֲשֶׁר שָׁם הָאֱלהִים וּכְתִיב, (שמות כ״ד:י״ח) וַיָּבֹא משֶׁה בְּתוֹךְ הֶעָנָן וְגו' וַיְהִי משֶׁה בָּהָר אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְיָכִיל לְאִסְתַּכָּלָא בַּמֶּה דְאִסְתַּכַּל.</p>\n<p>כְּגַוְונָא דָא מִתְלַבְּשִׁין נִשְׁמַתְהוֹן דְּצַדִּיקַיָא בְּהַהוּא עָלְמָא בִּלְבוּשָׁא כְּגַוְונָא דְּהַהוּא עָלְמָא דְּלָא יִתְנַהֵג אֶלָּא בִּלְבוּשָׁא כְּגַוְונָא דָא וְקָיְימֵי לְאִסְתַּכָּלָא בִּנְהוֹרָא דְּנָהִיר בְּהַהוּא אֶרֶץ הַחַיִּים. וְזֶהוּ יָהּ יָהּ בְּאֶרֶץ הַחַיִּים. דְּהֲוָה סָבִיר דְּלָא יִזְכֵּי לְהַהוּא נְהוֹרָא וּלְהַהוּא אִסְתַּכְּלוּתָא בְּגִין דְּנַהֲרָא דְּנָגִיד פָּסִיק לֵיהּ וְלָא אוֹלִיד. לא אַבִּיט אָדָם עוֹד דָּא אָדָם קַדְמָאָה כְּמָה דְּאִתְּמָר.</p>\n<p>וְכָל דָא לָמָּה. בְּגִין דְּאָמַר לֵיהּ נְבִיאָה כִּי מֵת אַתָּה בְּהַאי עָלְמָא וְלָא תִחְיֶה לְהַהוּא עָלְמָא. בְּגִין. דְּמָאן דְּלָא (הוה) אוֹלִיד בְּנִין בְּהַאי עָלְמָא, כַּד נָפִיק מִנֵּיהּ מְתַרְכִין לֵיהּ מִכָל מַה דְּאֲמָרָן. וְלָא שַׁרְיָא לְמֶחמֵי בְּהַהוּא נְהוֹרָא דְּנָהִיר (כל שכן וכל שכן שאר עמא ושאר בני נשא). וּמַה חִזְקִיָּה דְּהֲוָה לֵיהּ זְכוּת אָבוֹת וְאִיהוּ זַכָּאָה צַדִּיק וַחֲסִידָא כָּךְ. כָּל שֶׁכֵּן מַאן דְּלֵית לֵיהּ זְכוּת אָבוֹת וְחָטֵי קַמֵּי מָארֵיהּ.</p>\n<p>הַאי לְבוּשָׁא דְּקָאֲמָרָן אִיהוּ (אנון) מַה דְּאָמְרוּ חַבְרַיָיא חֲלוּקָא דְּרַבָּנָן דְּאִתְלְבִישׁוּ בְּהַהוּא עָלְמָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא דְּגָנִיז לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּמָּה טָבִין וְעִידוּנִין לְהַהוּא עָלְמָא, עֲלַיְיהוּ כְּתִיב, (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתֶךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ:</p>"],[9520011155,"<p>וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם עַל הָאָרֶץ. רַבִּי יְהוּדָה פָּתַח (במדבר כ׳:י״ג) הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ וַיִּקָּדֵשׁ בָּם. וְכִי בְּאֲתַר אָחֳרָא לֹא רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ. מַאי שְׁנָא הָכָא דְּקָאָמַר הֵמָּה מֵי מְרִיבָה וְלָא אָחֳרָנִין. אֶלָּא הַנֵּי מֵי מְרִיבָה הֲווּ וַדַּאי דְּיָהֲבוּ חֵילָא וְתוּקְפָא לְמָארֵיהוֹן דְּדִינָא לְאִתְתַּקְפָא. בְּגִין דְּאִית מַיִין מְתוּקִין וְאִית מַיִין מְרִירָן. אִית מַיִין צְלִילָן וְאִית מַיִין עֲכִירָן. אִית מַיִין שְׁלָם וְאִית מַיִין קְטָטוּ. וְעַל דָּא הֵמָּה מֵי מְרִיבָה אֲשֶׁר רָבוּ בְּנֵי יִשְׂרָאֵל אֶת יְיָ, דְּאַמְשִׁיכוּ עֲלַיְיהוּ לְמַאן דְּלָא אִצְטְרִיךְ וְאִסְתְּאִיבוּ בֵּיהּ הֲדָא הוּא דִכְתִיב וַיִּקּ1ָדִשׁ בָּם.</p>\n<p>אָמַר לֵיהּ רַבִּי חִזְקִיָה אִי הָכִי מַאי וַיִּקָּדֵשׁ וַיִּקָּדֵשׁוּ מִבָּעֵי לֵיהּ. אֶלָּא מִלָּה אִסְתְּלִיקַת. וַיִּקָּדֵשׁ אִתְפְּגִים מַאן דְּלָא אִצְטְרִיךְ. כִּבְיָכוֹל דְּאִתְפְּגֵימַת סִיהֲרָא. וַיִּקָּדֵּשׁ לָאו לְשִׁבְחָא אִיהוּ הָכָא. וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל כְּמָה דְּאוֹקִימְנָא לְאַיְיתָאָה מְחַבְּלָא עֲלַיְיהוּ כְּמָה דְאִנּוּן אִסְתְּאָבוּ בֵּיהּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי וַוי לוֹן לְרַשִּׁיעַיָא דְּלָא בָּעָאן לְאֲתָבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל חוֹבֵיהוֹן בְּעוֹד דְּאִנּוּן בְּהַאי עָלְמָא. דְּכַד בַּר נָשׁ אָתִיב וְאִתְנֶחָם עַל חוֹבוֹי. קוּדְשָׁא בְּרִיךְ הוּא מָחִיל לֵיהּ. וְכָל אִנּוּן דְּמִתְתַּקְפִין בְּחוֹבַיְיהוּ וְלָא בָּעוּ לְאֲתָבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל (חובוי) חוֹבֵיהוֹן. לְבָתַר (ינפול) יִנְפְּלוּ לְגֵּיהִנֹּם וְלָא יִסְקוּן לֵיהּ מִתַּמָּן לְעָלְמִין.</p>\n<p>תָּא חֲזֵי, בְּגִין דְּאַתְקִיפוּ לִבַּיְיהוּ כָּל אִנּוּן דָּרָא דְּנֹחַ וּבָעוּ לְאַחֲזָאָה חוֹבַיְיהוּ בְּאִתְגַּלְיָא. קוּדְשָׁא בְּרִיךְ הוּא אַיְיתֵי דִינָא עֲלַיְיהוּ בְּהַהוּא גַוְונָא. אָמַר רַבִּי יִצְחָק וְאֲפִילּוּ כַּד חָטֵי בַּר נָשׁ בְאִתְכַּסְיָא קוּדְשָׁא בְּרִיךְ הוּא רַחֲמָן. וְאִי תָּב בַּר נָשׁ לְגַבֵּיהּ חָפֵי עֲלֵיהּ וּמָחִיל לֵיהּ וְשָׁבִיק לֵיהּ. וְאִי לָא, גָּלֵי לֵיהּ לְעֵינֵי כֹלָּא. מְנָלָן מִסּוֹטָה.</p>\n<p>וְהָכִי נָמֵי אִתְמְחוּן אִלֵּין חַיָּיבַיָא מֵאַרְעָא בְּאִתְגַּלְיָא. וְהֵיךְ אִתְמְחוּן. אֶלָּא דְּהֲווּ נָפְקֵי מַיָיא וְהֲווּ רְתִיחָן מִן תְּהוֹמָא וְסָלְקֵי וְאַעֲבַר מִנַּיְיהוּ מָשְׁכָא. וְכֵיוָן דְּאַעֲבַר מִנַּיְיהוּ מָשְׁכָא הָכִי נָמֵי בִּשְׂרָא וְלָא אִשְׁתְּאָרוּ אֶלָּא בְּגַרְמַיְיהוּ לְחוֹד. לְקַיְימָא דִכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וְכָל אִנּוּן גַּרְמֵי אִתְפָּרְדָן דָּא מִן דָּא וְלָא אִשְׁתָּאֲרוּ כְּחֲדָא. וּמִכֹּלָא אִתְעֲבָרוּ מֵעָלְמָא. רַבִּי יִצְחָק אָמַר וַיִּמָּחוּ מִן הָאָרֶץ, מַאי וַיִּמָּחוּ, כְּמָא דְאַתְּ אָמֵר יִמָּחוּ מִסֵּפֶר חַיִּים. מִכָּאן אוֹלִיפְנָא דְּלֵית לוֹן תְּחִיָּה לְעָלְמִין וְלָא יְקוּמוּן בְּדִינָא.</p>"],[9520011156,"<p><Nonei></i>וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ. אָמַר רַבִּי אֶלְעָזָר מֵהָכָא קִיּוּמָא דִּבְרִית לְעֵילָא כְּקִיוּמָא דִּבְרִית לְתַתָּא. מַשְׁמַע דִּכְתִיב אִתָּךְ. וְאָמַר רַבִּי אֶלְעָזָר מִכָּאן אוֹלִיפְנָא דְּכַד זַכָּאִין אִנּוּן בְּעָלְמָא אִתְקְיַּים עָלְמָא לְעֵילָא וְתַתָּא. אָמַר רַבִּי שִׁמְעוֹן מִלָּה סָתִים אִיהוּ. כַּד אִתְעֲרוּתָא דִדְכוּרָא לְגַבֵּי נוּקְבָא כַּד אִיהוּ מְקַנֵּי לָהּ.</p>\n<p>תָּא חֲזֵי, רָזָא דְמִלָּה כַּד צַדִּיקָא אִיהוּ בְּעָלְמָא מִיָּד שְׁכִינְתָּא לָא אִתְעֲדִיאַת מִנֵּיהּ וְתִיאוּבְתָּא דִּילָהּ בֵּיהּ. כְּדֵין תִּיאוּבְתָּא דִלְעֵילָא לְגַבָּהּ בִּרְחִימוּ כְּתִיאוּבְתָּא דִדְכוּרָא לְנוּקְבֵיהּ כַּד אִיהוּ מְקַנִּי לָהּ. וְעַל דָּא וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ. אִתְעַר תִּיאוּבְתָּא בְּגִינָךְ. כְּגַוְונָא דָא (בראשית י״ז:כ״א) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק.</p>\n<p>וַהֲקִימוֹתִי אֶת בְּרִיתִי אִתָּךְ לְמֶהֱוֵי אָת בְּרִיתִי בְּעָלְמָא. וּלְבָתַר וּבָאתָ אֶל הַתֵּבָה, דְּאִלְמָלֵא לָאו אִיהוּ צַדִּיק (ברית) לָא יֵיעוּל לְתֵיבוּתָא דְּהָא לָא אִתְחַבַּר לַתֵּבָה בַּר צַדִּיק, וּבְגִינֵי כָךְ וּבָאתָ אֶל הַתֵּבָה וְהָא אִתְּמָר.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר בְּכָל זִמְנָא דִּבְנֵי נָשָׁא יִתְאַחֲדוּן בִּבְרִית דָּא, וְלָא יִשְׁבְּקוּן לֵיהּ, לֵית עַם וְלִישָׁן בְּעָלְמָא דְּיֵיכוּל לְאַבְאָשָׁא לוֹן. וְנֹחַ אַתְקִיף בִּבְרִית דָּא וְנָטַר לֵיהּ, בְּגִינֵי כָךְ קוּדְשָׁא בְּרִיךְ הוּא נָטַר לֵיהּ (וכל דיליה). וְכָל בְּנִי דָרֵיהּ לָא נָטְרוּ לֵיהּ, בְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אַעֲבַר לוֹן מֵעָלְמָא. וְהָא אִתְּמָר בְּהַהוּא חוֹבָא מַמָּשׁ דְּאִנּוּן חָאבוּ בְּהַהוּא גַוְונָא אִתְמְחוּן מֵעָלְמָא.</p>"],[9520011157,"<p>רַבִּי יְהוּדָה הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, וְהֲווּ עָסְקֵי בְּהַאי קְרָא דִּכְתִיב, (מלכים א י״ח:ל׳) וַיְרַפֵּא אֶת מִזְבַּח ה' הֶהָרוּס. מַאי וַיְרַפֵּא. תָּא חֲזֵי, בִּימֵי אֵלִיָּהוּ, יִשְׂרָאֵל כֻּלְהוּ שָׁבְקוּ לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא וְשָׁבְקוּ בְּרִית קַיָּימָא דִלְהוֹן. כַּד אֲתָא אֵלִיָּהוּ וְחָמָא דְקָא שָׁבְקוּ בְּנֵי יִשְׂרָאֵל הַאי בְּרִית קַיָּימָא וְאַעֲבָרוּ מִנַּיְיהוּ הַאי בְּרִית.</p>\n<p>כֵּיוָן דְּחָמָא אֵלִיָּהוּ כָךְ אֲתָא לְאַתְקָנָא מִלָּה לְדוּכְתֵּיהּ. כֵּיוָן דְּקָרִיב מִלָּה לְדוּכְתֵּיהּ אִתְּסֵי כֹּלָּא. הֲדָא הוּא דִכְתִיב וַיְרַפֵּא אֶת מִזְבַּח יְיָ הֶהָרוּס. דָּא בְּרִית קַיָּימָא (ד\"א ל\"ג דאתא לאתקנא מזבח יי ההרוס ברית קיימא) דְּהֲוָה שָׁבִיק מֵעָלְמָא. וּכְתִיב, (מלכים א י״ח:ל״א) וַיִּקַּח אֵלִיָּהוּ שְׁתֵּים עֶשְׂרֵה אֲבָנִים לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב. דָּא הוּא תִּקּוּנָא דְּמִזְבַּח יְיָ.</p>\n<p>אֲשֶׁר הָיָה דְּבַר יְיָ אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. מַאי טַעְמָא אִדְכַּר הָכָא יִשְׂרָאֵל, אֶלָּא וַדַּאי יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ וַדַּאי לְאִסְתַּלָּקָא לְעֵילָא וְלְאֲתָבָא בְּרִית קַיָּימָא לְאַתְרֵיהּ. וְהַיְנוּ דִּכְתִיב כִּי עָזְבוּ בְּרִיתְךָ בְּנִי יִשְׂרָאֵל. וּבְגִין כָּךְ אֶת מִזְבְּחוֹתֶיךָ הָרָסוּ.</p>\n<p>תָּא חֲזֵי, כָּל זִמְנָא דְּיִשְׂרָאֵל נָטְרוּ קְיָימָא קַדִּישָׁא כְּדֵין עָבְדֵי קִיּוּמָא לְעֵילָא וְתַתָּא. וְכַד שָׁבְקֵי לְהַאי בְּרִית כְּדֵין לָא אִשְׁתְּכַח קִיּוּם לְעֵילָא וְתַתָּא דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי. וּבְגִין כָּךְ וַיְרַפֵּא אֶת מִזְבַּח יְיָ הֶהָרוּס. וְכִי רְפוּאָה אִיהוּ. הָכִי הוּא וַדַּאי דְּהָא מְקַיֵּים לְהַהוּא אֲתַר דִּמְהֵימְנוּתָא תַּלְיָא בֵּיהּ.</p>\n<p>תָּא חֲזֵי, אוּף הָכִי פִּנְחָס בְּשַׁעֲתָא דְקַנֵּי לְעוֹבָדָא דְזִמְרִי אַתְקִין לְהַאי בְּרִית בְּאַתְרֵיהּ. וּבְגִין כָּךְ כְּתִיב, (במדבר כ״ה:י״ב) הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. וְכִי סַלְקָא דַעְתָּךְ דִּבְגִין פִּנְחָס הֲוָה. וּמַה קְטָטָא הֲוָה לֵיהּ לְפִנְחָס בְּהַאי בְּרִית. אֶלָּא הָכָא אִתְקְשַׁר מִלָּה בְּדוּכְתֵּיהּ. הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי. וּמָה אֶתֵּן לוֹ שָׁלוֹם (לאתחברא כל חד בדוכתיה) לְאִתְחַבְּרָא בְּרִית בְּאַתְרֵיהּ. וְעַל דָּא הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי (שלום). וּמַה (נ\"א איהו) שָׁלוֹם דְּאִיהוּ אַתְרֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ. מַה דְּאִתְפָּרַשׁ מִנֵּיהּ בְּחוֹבַיְיהוּ. בְּגִינֵיהּ אִתְחַבַּר בֵּיהּ. וְעַל דָּא הוֹאִיל וְהוּא אַתְקִין מִלָּה בְּדוּכְתֵּיהּ, מִכָּאן וּלְהָלְאָה וְהָיְתָה לוֹ וּלְזַרְעוֹ אַחֲרָיו בְּרִית כְּהֻנַּת עוֹלָם, תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו וְגו'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לֵית לָךְ מִלָּה בְּעָלְמָא דְּקוּדְשָׁא בְּרִיךְ הוּא קַנֵּי לָהּ כְּמוֹ חוֹבָא דִבְרִית כְּמָא דְאַתְּ אָמֵר, (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית. וְתָּא חֲזֵי, לָא אִשְׁתְּלִים חוֹבָא דְדָרָא דְּטוֹפָנָא, אֶלָּא בְּגִין דְּחָבוּ בְּחַבִּילוּ (דארחייהו) עַל אַרְעָא. וְאַף עַל גַּב דְּהֲווּ מְקַפְּחֵי דָא לְדָא כְּדִכְתִיב וַתִּמָּלֵא הָאָרֶץ חָמָס (וחמס מכלא הוה ובגין כך) וּכְתִיב כִּי <Nonei></i>מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. מִכָּל מָקוֹם וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים. וְהִנְנִי מַשְׁחִיתָם מִדָּה כְּנֶגֶד מִדָּה, הִנְנִי מַשְׁחִיתָם בְּחוֹבָא דְּחַבָּלוּתָא.</p>\n<p>וְאִית דְּאָמְרֵי דְּלָא אִשְׁתְּלִים קִסְטַיְיהוּ אֶלָּא בְּחוֹבָא דְּחָמָס דְּהֲווּ מְקַפְּחִין דָּא לְדָא דְּהֲווּ בִּישִׁין לַשָּׁמַיִם וְלַבְּרִיּוֹת. תָּא חֲזֵי, כַּמָּה אִנּוּן מְמַנָּן מִלְּעֵילָא דְּאִתְפָּקְדָן עַל קָלֵי דְאִנּוּן דְּמָסְרֵי דִינָא עַל חַבְרֵיהוֹן עַל מַה דְּעָבְדֵי לוֹן. וְעַל דָּא כְּתִיב כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. וּבְגִין כָּךְ כְּתִיב וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ:</p>"],[9520011158,"<p>וַיֹּאמֶר יְיָ לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ. אָמַר רַבִּי שִׁמְעוֹן אַמַּאי בְּכֻלְהוּ (ד\"א ל\"ג אמר) אֱלֹהִים וְהָכָא יְיָ. מַאי שָׁנָא הָכָא דְּאִתְּמָר יְיָ שְׁמָא עִלָּאָה דְּרַחֲמֵי. אֶלָּא רָזָא אִיהוּ דְּאוֹלִיפְנָא. לָאו אוֹרַח אַרְעָא לְקַבְּלָא אִתְּתָא אוּשְׁפִּיזָא בַּהֲדָהּ אֶלָּא בִּרְשׁוּ דְּבַעֲלָהּ.</p>\n<p>אוּף הָכִי (נמי נח) נֹחַ בָּעָא לְאַעָלָא בְּתֵיבוּתָא לְאִתְחַבְּרָא בַּהֲדָהּ. וְלָאו הֲוָה (ליה) יָאוֹת עַד דְּבַעֲלָהּ דְּתֵיבָה יָהַב לֵיהּ רְשׁוּ לְאַעֲלָאָה (בהדה). דִּכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. וּבְגִין כָּךְ אִקְרֵי הָכָא יְיָ בַּעֲלָהּ דְּתֵיבָה. וּכְדֵין עָאל נֹחַ וְאִתְחַבַּר בַּהֲדָהּ. וְכֵן אוֹלִיפְנָא דְּלֵית לֵיהּ רְשׁוּ לְאוּשְׁפִּיזָא לְמֵיעָאל לְבֵיתָא אֶלָּא בִּרְשׁוּ בַּעֲלָהּ מָארֵיהּ דְּבֵיתָא, הֲדָא הוּא דִכְתִיב לְבָתַר וַיָּבֹא נֹחַ וְגו'.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. מִכָּאן אוֹלִיפְנָא דְּלָא יְקַבֵּל בַּר נָשׁ אוּשְׁפִּיזָא בְּבֵיתֵיהּ אִי אִיהוּ חָשִׁיד בֵּיהּ דְּאִיהוּ חַיָּיבָא. אֶלָּא אִי קָאִים בְּעֵינוֹי לְזַכָּאָה דְּלָא חָשִׁיד בְּעֵינוֹי כְּלָל. הֲדָא הוּא דִכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה, מַאי טַעְמָא בְּגִין כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה.</p>\n<p>וְאוֹלִיפְנָא דְּאִי יָהִיב לֵיהּ רְשׁוּ בִּלְחוֹדוֹי וְלָא יָהִיב רְשׁוּ לְכָל אִנּוּן דְּאַתְיָין עִמֵּיהּ, לָא יֵיעוּל לוֹן לְבֵיתָא. הֲדָא הוּא דִכְתִיב בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּבָה. לְכֹלָא יָהִיב רְשׁוּתָא לְמֵיעַל. וּמִקְרָא דָא אוֹלִיפְנָא רָזָא דְּאָרְחוֹי דְאַרְעָא. (ד\"א ל\"ג בא אתה וכל ביתך אל התבה וגו').</p>"],[9520011159,"<p>רַבִּי יְהוּדָה פָּתַח (תהילים כ״ד:א׳) לְדָוִד מִזְמוֹר לַיְיָ הָאָרֶץ וּמְלוֹאָהּ תֵּבֵל וְיוֹשְׁבֵי בָהּ. הָא תָּנִינָן לְדָוִד מִזְמוֹר דְּאָמַר שִׁירָתָא וּלְבָתַר שָׁארַת עֲלֵיהּ רוּחַ קַדִּשָׁא, מִזְמוֹר לְדָוִד דְּשָׁארַת עֲלֵיהּ רוּחַ קַדִּישָׁא וּלְבָתַר אָמַר (לה) שִׁירָתָא.</p>\n<p>לַיְיָ הָאָרֶץ וּמְלוֹאָהּ, הַאי קְרָא עַל אַרְעָא דְיִשְׂרָאֵל אִתְּמָר דְּאִיהִי אַרְעָא קַדִּישָׁא. וּמְלוֹאָהּ דָּא שְׁכִינְתָּא כְּמָא דְאַתְּ אָמֵר, (דברי הימים ב ה׳:י״ד) כִּי מָלֵא כְבוֹד יְיָ אֶת בֵּית יְיָ. וּכְתִיב, (שמות מ׳:ל״ד) וּכְבוֹד יְיָ מָלֵא אֶת הַמִּשְׁכָּן. מַאי מָלֵא וְלָא מִילָא. אֶלָּא מָלֵא וַדַּאי דְּאִתְמַלְיָיא מִכֹּלָּא. דְּאִתְמַלְיָיא מִן שִׁמְשָׁא. סִיהֲרָא שְׁלִים בְּכָל סִטְרִין. מָלֵא מִכָּל טוּבָא דִלְעֵילָא. כְּאִסְקוֹפָא דָא דְּאִתְמַלְיָיא מִכָּל טוּבָא דְּעָלְמָא. וְעַל דָּא כְּתִיב לַיְיָ הָאָרֶץ וּמְלוֹאָהּ. תֵּבֵל וְיוֹשְׁבֵי בָהּ דָּא שְׁאָר אַרְעָאן.</p>\n<p>דָּבָר אַחֵר לַיְיָ הָאָרֶץ וּמְלוֹאָהּ דָּא אַרְעָא קַדִּישָׁא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בָהּ. וּמְלוֹאָהּ אִלֵּין נִשְׁמַתְהוֹן דְּצַדִּיקַיָּיא (ד\"א ל\"ג דכלהון מליין לה) אִתְמַלְיָיא (ד\"א דאתמלייא) מִנַּיְיהוּ מֵחֵילָא דְּעַמּוּדָא חַד דְּעָלְמָא קָיְימָא עֲלֵיהּ.</p>\n<p>וְאִי תֵימָא עַל חָד קָיְימָא. תָּא חֲזֵי, מַה כְּתִיב, (תהילים כ״ד:ב׳) כִּי הוּא עַל יַמִּים יְסָדָהּ. כִּי הוּא. מַאן הוּא. דָּא קוּדְשָׁא בְּרִיךְ הוּא. כְּמָא דְאַתְּ אָמֵר הוּא עָשָׂנוּ. וּכְתִיב, (איוב כ״ח:כ״ד) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט.</p>\n<p>עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ אִלֵּין שִׁבְעָה עַמּוּדִים דְּקָיְימָא (ארעא) עֲלַיְיהוּ וּמַלְיָין לָהּ. הִיא אִתְמַלְיָיא מִנַּיְיהוּ, הֵיךְ אִתְמַלְיָיא מִנַּיְיהוּ. בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא כְּדֵין אַרְעָא דָּא עַבְדַּת פֵּירִין וְאִתְמַלְיָיא מִכֹּלָּא.</p>\n<p>וּבְשַׁעֲתָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא כְּדֵין כְּתִיב, (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחרָב וְיָבֵשׁ. אָזְלוּ מַיִם מִנִּי יָם, דָּא אַרְעָא קַדִּישָׁא דְּאֲמָרָן דְּאִשְׁתַּקְיָא מִשַּׁקְיוּ עִלָּאָה. וְנָהָר יֶחֱרָב וְיָבֵשׁ, הַהוּא עַמּוּדָא חַד דְּקָאִים עֲלָהּ לְאִתְנָהֲרָא מִנֵּיהּ. וְנָהָר יֶחֱרָב וְיָבֵשׁ כְּמָא דְאַתְּ אָמֵר (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד.</p>"],[9520011160,"<p>וְאָמַר רַבִּי יְהוּדָה בְּהַהוּא זִמְנָא דְּאִתְאֲבִידוּ אִנּוּן חַיָּבִין מֵעָלְמָא קוּדְשָׁא בְּרִיךְ הוּא (עציב) (נ\"א אסתכל) אִשְׁתַּדַל עַל עָלְמָא וְלָא חָמָא מַאן (דקאים) דְּאָגִין עוֹלָה. וְאִי תֵימָא הָא נֹחַ, דְּהֲוָה לֵיהּ לְאַגָּנָא עַל (דריה) גַרְמֵיהּ וּלְאֲפָקָא מִנֵּיהּ תּוֹלָדִין לְעָלְמָא. הֲדָא הוּא דִכְתִיב כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה. בַּדּוֹר הַזֶּה דַּיְיקָא.</p>\n<p>רַבִּי יוֹסֵי <Nonei></i>אָמַר בַּדּוֹר הַזֶּה דָּא שְׁבָחָא דִּילֵיהּ דְּהֲוָה בְּהַהוּא דָרָא חַיָּיבָא וְאִשְׁתְּכַח כּוּלֵי הַאי אִישׁ צַדִּיק תָּמִים (ודאי ולאו בדרא דיליה אלא) (ס\"א ודא די ליה) וְאֲפִילּוּ בְּדָרָא דְמשֶׁה, אֲבָל לָא הֲוָה יָכִיל לְאַגָּנָא עַל עָלְמָא. בְּגִין דְּלָא אִשְׁתַּכְּחוּ עֲשָׂרָה בְּעָלְמָא כְּמָא דְאַתְּ אָמֵר, (בראשית י״ח:כ״ט) אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה וְלָא אִשְׁתַּכְּחוּ תַּמָּן, אוּף הָכָא לָא אִשְׁתַּכְּחוּ עֲשָׂרָה. אֶלָא הוּא וּתְלַת בְּנוֹי וְנוּקְבַיְיהוּ וְלָא הֲווּ עֲשָׂרָה.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאִיל לֵיהּ לְרַבִּי שִׁמְעוֹן אֲבוֹי, הָא תָּנִינָן בְּשַׁעֲתָא דְעָלְמָא אִתְמַלְיָיא חוֹבֵי בְּנֵי נָשָׁא וְדִינָא נָפַק, וַוי לְהַהוּא זַכָּאָה דְּאִשְׁתְּכַח בְּעָלְמָא דְּאִיהוּ אִתְפַּס בְּחוֹבוֹי דְחַיָיבַיָא בְּקַדְמִיתָא. נֹחַ אֵיךְ אִשְׁתְּזִיב דְּלָא אִתְפַּס בְּחוֹבַיְיהוּ. אָמַר לֵיהּ הָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאֲפָקָא מִנֵּיהּ תּוֹלָדִין לְעָלְמָא מִגּוֹ תֵּיבוּתָא. וְתוּ דְּהָא דִּינָא לָא יָכְלָא לְשַׁלְטָאָה עֲלוֹי בְּגִין דְּהֲוָה טָמִיר וְגָנִיז בַּתֵּבָה וְאִתְכַּסְיָיא מֵעֵינָא.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב, (צפניה ב׳:ג׳) בַּקְשׁוּ צֶדֶק בַּקְשׁוּ עֲנָוָה אוּלַי תִּסָּתְרוּ בְּיוֹם אַף יְיָ. וְנֹחַ בִּקֵּשׁ צֶדֶק וְעָאל בְּגַוָּוהּ לְשַׁלְטָאָה וּלְקַטְרְגָא לֵיהּ.</p>\n<p>הָכָא אִתְרְמִיז לְאִנּוּן קַדִּישֵׁי עֶלְיוֹנִין לְמִנְדַע בְּרָזָא דְּאַתְוָון קַדִּישִׁין עִלָּאִין הִפּוּכָא דְּאַתְוָון כ\"ב לְאִתְמְחֵי לְאִנּוּן חַיָּיבַיָא. וְעַל דָּא וַיִּמָּחוּ מִן הָאָרֶץ כְּתִיב. בֹּא אַתָּה וְכָל בֵּיתְךָ.</p>"],[9520011161,"<p>רַבִּי יִצְחָק פָּתַח (ישעיהו ס״ג:י״ב) מוֹלִיךְ לִימִין משֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם. (נ\"א זרוע תפארתו) דָּא זְכוּתָא דְאַבְרָהָם דְּאִיהוּ יָמִינָא מִמּשֶׁה. תִּפְאֶרֶת דְּמשֶׁה. וּבְגִין כָּךְ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם. דְּהָא זְכוּתָא דְאַבְרָהָם בּוֹקֵעַ מַיִם אִיהוּ. וְכָל דָּא לָמָה לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם.</p>\n<p>תָּא חֲזֵי, מַה בֵּין משֶׁה לִשְׁאָר בְּנֵי עָלְמָא. בְּשַׁעֲתָא דְאֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה (שמות ל״ב:י׳) וְעַתָּה הַנִּיחָה לִי וְגו'. וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָדוֹל וְגו'. מִיָּד אָמַר משֶׁה וְכִי אֶשְׁבּוֹק דִּינְהוֹן דְּיִשְׂרָאֵל בְּגִינִי. הַשְׁתָּא יֵימְרוּן כָּל אִנּוּן בְּנֵי עָלְמָא דְּאֲנָא קַטְלִית לוֹן לְיִשְׂרָאֵל. כְּמָה דְּעֲבַד נֹחַ.</p>\n<p>דְּכֵיוָן דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דִּישֵׁזִיב לֵיהּ בְּתֵיבוּתָא (כמה דאתמר) דִּכְתִיב וַאֲנִי הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם וְגו'. וּכְתִיב וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנֵי הָאֲדָמָה וַאֲנִי הִנְנִי מֵקִים אֶת בְּרִיתִי וְגו' וּבָאתָ אֶל הַתֵּבָה כֵּיוָן דְּאָמַר לֵיהּ דְּיִשְׁתְּזִיב הוּא וּבְנוֹי לָא בָּעָא רַחֲמִין עַל עָלְמָא וְאִתְאֲבִידוּ. וּבְגִין כָּךְ אִקְרוּן מֵי הַמַּבּוּל עַל שְׁמֵיהּ כְּמָא דְאַתְּ אָמֵר, (ישעיהו נ״ד:ט׳) כִּי מֵי נֹחַ זֹאת לי אשׁר נשׁבָּעַתִּי מעָבוֹר מֵי נֹחַ.</p>\n<p>אָמַר משֶׁה הַשְׁתָּא יֵימְרוּן בְּנִי עָלְמָא דְּאֲנָא קְטִילַת לוֹן בְּגִין דְּאָמַר לִי וְאֶעֱשֶׂה אוֹתְךָ לְגוֹי גָדוֹל. הַשְׁתָּא טַב לִי דְּאֵימוּת וְלָא יִשְׁתֵּצוּן יִשְׂרָאֵל. מִיָּד וַיְחַל משֶׁה אֶת פְּנֵי יְיָ אֱלֹהָיו. בָּעָא רַחֲמִין עֲלַיְיהוּ וְאִתְעַר רַחֲמֵי עַל עָלְמָא.</p>\n<p>וְאָמַר רַבִּי יִצְחָק שֵׁירוּתָא דְּבָעָא רַחֲמֵי עֲלַיְיהוּ מַאי קָאֲמַר. לָמָּה יְיָ יֶחרֶה אַפְּךָ בְּעַמֶּךָ. וְכִי מִלָּה דָא אֵיךְ אָמַר לֵיהּ משֶׁה לָמָּה. וְהָא עֲבָדוּ כּוֹכָבִים וּמַזָּלוֹת כְּמָא דְאַתְּ אָמֵר עָשׂוּ לָהֶם עֵגֶל מַסֵּכֶה וַיִּשְׁתַּחֲווּ לוֹ וַיֹּאמְרוּ אֵלֶּה וְגו'. וּמשֶׁה אָמַר לָמָּה. אֶלָּא הָכִי אוֹלִיפְנָא מַאן דִּמְרַצֶּה לְאָחֳרָא לָא בָּעֵי לְמֶעְבַּד הַהוּא חוֹבָא (דאיהו) רַב, אֶלָּא יַזְעִיר לֵיהּ קַמֵּיהּ. וּלְבָתַר יַסְגֵּי לֵיהּ קַמֵּיהּ אָחֳרָא (ד\"א ל\"ג חייבא) דִּכְתִיב אַתֶּם חֲטָאתֶם חֲטָאָה גְדֹלָה.</p>\n<p>וְלָא שָׁבִיק לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד דְּמָסַר גַּרְמֵיהּ לְמוֹתָא דִּכְתִיב וְעַתָּה אִם תִּשָּׂא חֲטָאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ. וְקוּדְשָׁא בְּרִיךְ הוּא מָחִיל לוֹן דִּכְתִיב וַיִּנָּחֶם יְיָ עַל הָרָעָה וְגו'. וְנֹחַ לָא עֲבַד כֵּן אֶלָּא בָּעָא לְאִשְׁתְּזָבָא וְשָׁבִיק כָּל עָלְמָא.</p>\n<p>וּבְכָל זִמְנָא דְדִינָא שַׁרְיָא עַל עָלְמָא, רוּחַ קוּדְשָׁא אָמַר וַוי דְּלָא אִשְׁתְּכַח כְּמשֶׁה דִּכְתִיב (ישעיהו ס״ג:י״א) וַיִּזְכּוֹר (ימי עולם משה עמו) (וגו) אַיֵּה הַמַּעֲלֵם מִיָּם וְגו'. דִּכְתִיב (שמות י״ד:ט״ו) וַיֹּאמֶר יְיָ אֶל משֶׁה מַה תִּצְעַק אֵלָי. דְּהָא אִיהוּ בִּצְלוֹתָא סָלִיק לוֹן מִן יַמָּא. וּבְגִין דְּשַׁוֵּי גַּרְמֵיהּ בִּצְלוֹתָא עֲלַיְיהוּ דְיִשְׂרָאֵל בְּיַמָּא. אִיקְרֵי (על שמיה) הַמַּעֲלֵם מִיָּם. דְּאִיהוּ אַסִּיק לוֹן מִן יַמָּא.</p>\n<p>אַיֵּה הַשָּׂם בְּקִרְבּוֹ אֶת רוּחַ קָדְשׁוֹ דָּא אִיהוּ משֶׁה דְּאַשְׁרֵי <Nonei></i>שְׁכִינְתָּא בֵּינַיְיהוּ דְיִשְׂרָאֵל. מוֹלִיכָם בַּתְּהֹמוֹת כַּד אִתְבָּקְעוּ מַיָא וְאֲזְלוּ בְּגוֹ תְּהוֹמֵי בְּיַבֶּשְׁתָּא דִּגְלִידוּ מַיָא (וכלא אתמר על משה). (נ\"א ועל דא אקרי משה עמו) בְּגִין דְּאַמְסַר גַּרְמֵיהּ עַל יִשְׂרָאֵל.</p>\n<p>אָמַר רַבִּי יְהוּדָה אַף עַל גַּב דְּזַכָּאָה הֲוָה נֹחַ לָאו אִיהוּ כְּדַאי (בגין) דְּקוּדְשָׁא בְּרִיךְ הוּא יָגִין עַל עָלְמָא בְּגִינֵיהּ. תָּא חֲזֵי, משֶׁה לָא תָּלָה מִלָּה בִּזְכוּתֵיהּ אֶלָּא בִּזְכוּת אֲבָהָן קַדְמָאֵי. אֲבָל נֹחַ לָא הֲוָה לֵיהּ בְּמַאן דְּיִתְלֵי בִּזְכוּתָא כְּמשֶׁה.</p>\n<p>אָמַר רַבִּי יִצְחָק וְעִם כָּל דָּא כֵּיוָן דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וַהֲקִמֹתִי אֶת בְּרִיתִי אִתָּךְ הֲוָה לֵיהּ לְמִבְעֵי רַחֲמֵי עֲלַיְיהוּ. וְקָרְבָּנָא דְּאַקְרִיב לְבָתַר, דְּיַקְרִיב לֵיהּ מִן קַדְמַת דְּנָא דִּלְמָא יִשָּׁכֵךְ רוּגְזָא מֵעָלְמָא.</p>\n<p>אָמַר רַבִּי יְהוּדָה מַאי הֲוָה לֵיהּ לְמֶעְבַּד דְּהָא חַיָּיבֵי עָלְמָא הֲווּ מַרְגִּיזִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ יַקְרִיב קָרְבָּנָא. אֶלָּא וַדַּאי נֹחַ דָּחִיל עַל גַּרְמֵיהּ הֲוָה, בְּגִין דְּלָא יֶעֱרַע בֵּיהּ מוֹתָא בְּגוֹ חַיָּיבֵי עָלְמָא דְּהֲוָה חָמֵי עוֹבָדֵיהוֹן בִּישָׁא כָּל יוֹמָא, וְהֵיךְ מַרְגְזָן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כָּל יוֹמָא.</p>\n<p>רַבִּי (אלעזר פתח) יִצְחָק אָמַר כָּל זִמְנָא דְּחַיָּיבֵי עָלְמָא אַסְגִּיאוּ, זַכָּאָה דְּאִשְׁתְּכַח בֵּינַיְיהוּ הוּא אִתְפַּס בְּקַדְמִיתָא. דִּכְתִיב, (יחזקאל ט׳:ו׳) וּמִמִּקְדָּשִׁי תָּחֵלּוּ. וְתָנִינָן אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְּקוּדָשִׁי. וְנֹחַ הֵיךְ שֵׁזִיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בֵּין כָּל אִנּוּן חַיָּיבַיָא. אֶלָּא בְּגִין דְּיִפְקוּן מִנֵּיהּ תּוֹלָדִין בְּעָלְמָא דְּהֲוָה צַדִּיק כְּדְקָא יְאוּת.</p>\n<p>וְתוּ דְּאִיהוּ אַתְרֵי בְּהוּ כָּל יוֹמָא וְיוֹמָא וְלָא קַבִּילוּ מִנֵּיהּ, וְקִיֵּים בְּנַפְשֵׁיהּ קְרָא דִּכְתִיב, (יחזקאל ג׳:י״ט) וְאַתָּה כִּי הִזְהַרְתָּ רָשָׁע וְגו'. וּכְתִיב וְאַתָּה אֶת נַפְשְׁךָ הִצַּלְתָּ. מִכָּאן כָּל מַאן דְּאַזְהַר לְחַיָּיבָא אַף עַל גַּב דְּלָא קַבִּיל מִנֵּיהּ הוּא שֵׁזִיב לֵיהּ לְגַרְמֵיהּ וְהַהוּא חַיָּיבָא אִתְפַּס בְּחוֹבֵיהּ. וְעַד כַּמָּה יַזְהַר לֵיהּ עַד דְּיִמְחֵי לֵיהּ הָא אוּקְמוּהָ חַבְרַיָא.</p>\n<p>רַבִּי יוֹסֵי הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן יוֹמָא חַד, אָמַר לֵיהּ מַאי חָמָא קוּדְשָׁא בְּרִיךְ הוּא לְשֵׁיצָאָה כָּל חֵיוַת בְּרָא וְעוֹף שְׁמַיָא עִמְּהוֹן דְּחַיָיבַיָא. אִי בְּנֵי נָשָׁא חָטָאן בְּעִירֵי וְעוֹפֵי שְׁמַיָא וּשְׁאָר בְּרִיָין מַה חָטוּ. אָמַר לֵיהּ בְּגִין דִּכְתִיב כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ. כֻּלְהוּ הֲווּ מְחַבְּלֵי אָרְחַיְיהוּ. שַׁבְקֵי זִינַיְהוּ וְדָבְקוּ בְּזִינָא אָחֳרָא.</p>\n<p>תָּא חֲזֵי, אִנּוּן חַיָּיבֵי עָלְמָא גָּרְמוּ הָכִי לְכָל בִּרְיָין. וּבָעוֹן (לאשכחא) לְאַכְּחָשָׁא עוֹבָדָא דִבְרֵאשִׁית. וְאִנּוּן גָּרְמוּ לְכָל בִּרְיָין לְחַבְּלָא אָרְחַיְיהוּ כְּמָה דְאִנּוּן מְחַבְּלָן. אָמַר קוּדְשָׁא בְּרִיךְ הוּא אַתּוּן בְּעִיתוּ (לאשכחא) לְאַכְּחָשָׁא עוֹבָדֵי יְדַי, אֲנָא אַשְׁלִים רְעוּתָא דִּלְכוֹן וּמָחִיתִי אֶת כָּל הַיְקוּם אֲשֶׁר עָשִׂיתִי מֵעַל פְּנִי הָאֲדָמָה. אַהֲדַר עָלְמָא לְמַיִין כְּמָה דְּהֲוָה בְּקַדְמִיתָא מַיִין בְּמַיִין וְהָא אִתְּמָר. מִכָּאן וּלְהָלְאָה אַעֲבִיד בִּרְיָין אָחֳרָנִין בְּעָלְמָא כְּדְקָא יְאוּת:</p>"],[9520011162,"<p>וַיָּבֹא נֹחַ וּבָנָיו וְאִשְׁתּוֹ וּנְשֵׁי בָנָיו אִתּוֹ. רַבִּי חִיָּיא פָּתַח וְאָמַר (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לא אֶרְאֶנּוּ נְאֻם יְיָ. כַּמָּה אִנּוּן בְּנֵי נָשָׁא אֲטִימִין לִבָּא סְתִימִין עַיְינִין דְּלָא מַשְׁגִּיחִין וְלָא יָדְעִין בִּיקָרָא דְמָארֵיהוֹן דִּכְתִיב בֵּיהּ הֲלֹא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֲנִי מָלֵא. הֵיךְ בָּעוּן בְּנִי נָשָׁא לְאִסְתַּתְּרָא מֵחוֹבַיְיהוּ וְאָמְרֵי מִי רוֹאֵנוּ וּמִי יוֹדְעֵנוּ. וּכְתִיב, (ישעיהו כ״ט:ט״ו) וְהָיָה בְּמַחְשָׁךְ מַעֲשֵׂיהֶם. לְאָן יִתְטַמְרוּן מִקַּמֵּיהּ.</p>\n<p>לְמַלְכָּא דְּבָנָה פַּלְטְרִין וְעֲבַד תְּחוֹת אַרְעָא טְמִירִין פְּצִירִין. לְיוֹמִין מָרָדוּ בְּנֵי פַּלְטְרִין בְּמַלְכָּא אַסְחַר (אצער) עֲלַיְיהוּ מַלְכָּא בְּגַיְיסוֹי. מָה עֲבָדוּ עָאלוּ וּטְמִירוּ גַּרְמַיְיהוּ תְּחוֹת נוּקְבֵי פְּסִירִין. אָמַר מַלְכָּא אֲנָא עַבְדִית לוֹן וּמִקַּמָּאי אַתּוּן בָּעָאן לְאִתְטַמָּרָא, הֲדָא הוּא דִכְתִיב אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם יְיָ. אֲנָא הוּא דַּעֲבָדִית נוּקְבֵי פְּסִירִין וְעֲבָדִית חֲשׁוֹכָא וּנְהוֹרָא וְאַתּוּן אֵיךְ יָכְלִין לְאִתְטַמָּרָא קַמָּאי.</p>\n<p>תָּא חֲזֵי, כַּד בַּר נָשׁ חָטֵי קַמֵּי מָארֵיהּ וְאַמְשִׁיךְ גַּרְמֵיהּ לְאִתְכַּסְיָא. קוּדְשָׁא בְּרִיךְ הוּא עָבִיד בֵּיהּ דִּינָא בְּאִתְגַּלְיָא. וְכַד בַּר נָשׁ אַדְכֵּי גַרְמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַסְתָּרָא לֵיהּ דְּלָא יִתְחֲזֵי בְּיוֹם אַף יְיָ. דְּוַדַּאי אִבָּעֵי לֵיהּ לְאֵינַשׁ <Nonei></i>דְּלָא יִתְחֲזֵי קַמֵּי מְחַבְּלָא כַּד שַׁרְיָא עַל עַלְמָא דְּלָא יִסְתַּכֵּל בֵּיהּ. דְּהָא כָּל אִנּוּן דְּיִתְחַזּוּן קַמֵּיהּ אִית לֵיהּ רְשׁוּ לְחַבָּלָא.</p>\n<p>וְהַיְינוּ דְקָאֲמַר רַבִּי שִׁמְעוֹן כָּל בַּר נָשׁ דְּעֵינֵיהּ בִּישָׁא, עֵינָא דִּמְחַבְּלָא שַׁרְיָא עֲלוֹי. וְאִיהוּ מְחַבְּלָא דְעָלְמָא אִקְרֵי. וְלִבָּעֵי לֵיהּ לְאִינֵישׁ לְאִסְתַּמְּרָא מִנֵּיהּ וְלָא לְאִתְקְרָבָא בַּהֲדֵיהּ דְּלָא יִתְּזַק (קמיה). וְאָסִיר לְמִקְרַב בַּהֲדֵיהּ בְּאִתְגַּלְיָא. וּמִשּׁוּם הָכִי מֵאִישׁ רַע עַיִן בָּעֵי לְאִסְתַּמְּרָא מִנִּיהּ. מִקַּמֵּי מַלְאַךְ הַמָּוֶת עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>(ועל דא) מַה כְּתִיב בְּבִלְעָם (במדבר כ״ד:ג׳) וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן. דְּעֵינָא בִּישָׁא הֲוָה לֵיהּ וּבְכָל אֲתַר דְּהֲוָה מִסְתַּכֵּל בֵּיהּ הֲוָה אַמְשִׁיךְ עֲלֵיהּ רוּחַ מְחַבְּלָא. וּבְגִין כָּךְ הֲוָה בָּעֵי לְאִסְתַּכָּלָא בְּהוּ בְּיִשְׂרָאֵל בְּגִין דִּישֵׁצֵי בְּכָל אֲתַר דְּעֵינֵיהּ הֲוָה מִסְתַּכֵּל. מַה כְּתִיב וַיִּשָּׂא בִּלְעָם אֶת עֵינָיו דְּזָקִיף עֵינָא חַד וּמָאִיךְ עֵינָא חַד בְּגִין לְאִסְתַּכָּלָא בְּהוּ בְּיִשְׂרָאֵל בְּעֵינָא בִּישָׁא.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וַיַּרְא אֶת יִשְׂרָאֵל שׁוֹכֵן לִשְׁבָטָיו. וְחָמָא דִּשְׁכִינְתָּא חַפְיָא עֲלַיְיהוּ וּרְבִיעָא עֲלַיְיהוּ מִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין תְּחוֹתָהּ וְלָא יָכִיל לְשַׁלְטָאָה עֲלַיְיהוּ עֵינֵיהּ. אָמַר אֵיךְ אֵיכוֹל לְהוֹן דְּהָא רוּחַ קַדִּישָׁא עִלָּאָה רְבִיעָא עֲלַיְיהוּ וְחָפַת לוֹן בְּגַדְפָהָא. הֲדָא הוּא דִכְתִיב כָּרַע שָׁכַב כַּאֲרִי, וּכְלָבִיא. מִי יְקִימֶנּוּ. מִי יְקִימֶנּוּ מֵעֲלַיְיהוּ בְּגִין דְּיִתְגַלְיָין וְשָׁלְטָא עֵינָא עֲלַיְיהוּ.</p>\n<p>וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְחַפְיָא לְנֹחַ לְאִסְתַּתְּרָא מֵעֵינָא דְּלָא יָכִיל רוּחַ מְסָאֳבָא לְשַׁלְטָא עֲלֵיהּ בְּגִין דְּלָא יִתְחַבֵּל וְהָא אִתְּמָר. וַיָּבֹא נֹחַ כְּמָה דְּאִתְּמָר לְאִסְתַּתְּרָא מֵעֵינָא. מִפְּנֵי מֵי הַמַּבּוּל (דהא) דְּמַיִין דָּחֲקוּ לֵיהּ. אָמַר רַבִּי יוֹסֵי חָמָא מַלְאַךְ הַמָּוֶת דְּהֲוָה אָתֵי (ד\"א ל\"ג לגביה) וּבְגִין כָּךְ עָאל לְתֵיבוּתָא וְאִסְתַּמַּר בָהּ תְּרִיסַר יַרְחֵי (שתא).</p>\n<p>וְאַמַּאי תְּרֵיסַר יַרְחִין. פְּלִיגֵי בָּהּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. חַד אָמַר י\"ב יַרְחִין דְּכָךְ אִיהוּ דִינָא דְּחַיָיבַיָא. וְחַד אָמַר לְאַשְׁלָמָא צַדִּיק (נ\"א צריך) דַּרְגִּין תְּרֵיסַר וּשְׁאָר דַּרְגִּין דְּאִתְחַזֵּי לְאֲפָקָא מִן תֵּיבָה.</p>\n<p>רַבִּי יְהוּדָה אָמַר שִׁתָּא יַרְחֵי אִנּוּן בְּמַיָא וְשִׁיתָּא יַרְחֵי בְּאֶשָׁא. וְהָא הָכָא מַיָיא הֲווּ אַמַּאי תְּרֵיסַר יַרְחֵי. אָמַר (ליה) רַבִּי יוֹסֵי בִּתְרֵי דִינִין דְּגֵיהִנֹּם אִתְדָנוּ בְּמַיָא וְאֶשָׁא. בְּמַיָא דְּמַיִין דְּנָחֲתוּ עֲלַיְיהוּ מִלְּעֵילָא הֲווּ צְנִינִין כְּתַלְגָא. בְּאֶשָׁא דְּמַיִין דְּנַפְקֵי מִתַּתָּא הֲווּ רְתִיחָן כְּאֶשָׁא. וְעַל דָּא בְּדִינָא דְּגֵיהִנֹּם אִתְדָּנוּ בְּאֶשָׁא וּמַיָיא (ובגין כך תריסר ירחי הוו דאמר רבי אלעזר דינא דחייביא בגיהנם תריסר ירחי הוו והא אוקמוה. ועל דא כל אנון חייבי עלמא אתדנו בתרין דינין אלין במיא ואשא) עַד דְּאִשְׁתֵּצִיאוּ מֵעָלְמָא. וְנֹחַ הֲוָה מִסְתַּתֵּר בְּתֵיבוּתָא וְאִתְכַּסֵּי מֵעֵינָא וּמְחַבְּלָא לָא קָרִיב לְגַבֵּיהּ, וְתֵיבוּתָא אִיהִי הֲוָה שַׁטְיָא עַל אַנְפֵּי מַיָא כְּמָא דְאַתְּ אָמֵר וַיִּשְׂאוּ אֶת הַתֵּיבָה וַתָּרָם מֵעַל הָאָרֶץ.</p>\n<p>אַרְבָּעִים יוֹם לָקוּ. דִּכְתִיב וַיְהִי הַמַּבּוּל אַרְבָּעִים יוֹם עַל הָאָרֶץ וְגו'. וְכָל שְׁאָר זִמְנָא אִתְמְחוּן מֵעָלְמָא. הֲדָא הוּא דִכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וַוי לוֹן לְאִנּוּן חַיָיבַיָא דְּהָא לָא יְקוּמוּן לְאַחְיָיא בְּעָלְמָא לְמֵיקַם בְּדִינָא הֲדָא הוּא דִכְתִיב וַיִּמָּחוּ כְּמָא דְאַתְּ אָמֵר, (תהילים ט׳:ו׳) שְׁמָם מָחִית לְעוֹלָם וָעֶד. דְּאֲפִילּוּ לְמֵיקַם בְּדִינָא לָא יְקוּמוּן:</p>"],[9520011163,"<p>וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ. רַבִּי אַבָּא פָּתַח (תהילים נ״ז:ו׳) רוּמָה עַל הַשָּׁמַיִם אֱלֹהִים עַל כָּל הָאָרֶץ כְּבוֹדֶךָ. וַוי לוֹן לְחַיָיבַיָא דְּאִנּוּן חָטָאן וּמַרְגִּיזִין לְמָארֵיהוֹן בְּכָל יוֹמָא. וּבְחוֹבַיְיהוּ דַּחְיָין לָהּ לַשְּׁכִינְתָּא מֵאַרְעָא. וְגָרְמִין דְּתִסְתַּלֵּק מֵעָלְמָא. וּשְׁכִינְתָּא אִקְרֵי אֱלֹהִים. וְעֲלָהּ כְּתִיב רוּמָה עַל הַשָּׁמַיִם אֱלהִים.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וַיִּשְׂאוּ אֶת הַתֵּבָה דְּדַחְיָין לָהּ לְבַר. וַתָּרָם מֵעַל הָאָרֶץ, דְּלָא שַׁרְיָיא בְּעָלְמָא וְאִסְתַּלְקַת מִנָּהּ. וְכַד אִסְתַּלְקַת מֵעָלְמָא, הָא לֵית מַאן דְּיַשְׁגַּח בְּעָלְמָא וְדִינָא שָׁלְטָא (בדינא) כְּדֵין עֲלוֹי. וְכַד יִתְמָחוּן חַיָּיבֵי עָלְמָא וְיִסְתַּלְּקוּן מִנֵּיהּ (דעלמא), שְׁכִינְתָּא אֲהַדְרַת מְדוֹרָהּ בְּעָלְמָא.</p>\n<p>אָמַר לֵיהּ רַבִּי יֵיסָא, אִי הָכִי הָא אַרְעָא דְיִשְׂרָאֵל דְּאִתְמָחוּן חַיָּיבַיָא דְּהֲווּ בְּהַהוּא זִמְנָא אַמַּאי לָא אֲהַדְּרַת שְׁכִינְתָּא לְאַתְרָהּ כְּדִבְקַדְמִיתָא. אָמַר לֵיהּ בְּגִין דְּלָא אִשְׁתָּאֲרוּ בָהּ שְׁאָר זַכָּאֵי עָלְמָא. אֶלָּא (אבל) בְּכָל אֲתַר דְּאֲזְלוּ נַחְתַת וְשַׁוִּיאַת <Nonei></i>מְדוֹרָהּ עִמְּהוֹן. וּמַה בְּאַרְעָא נוּכְרָאָה אָחֳרָא לָא אִתְפָּרְשָׁא מִנַּיְיהוּ, כָּל שֶׁכֵּן אִי אִשְׁתְּאָרוּ בְּאַרְעָא קַדִּישָׁא.</p>\n<p>וְהָא אִתְּמָר. בְּכָל חוֹבִין דְּחַיָּיבֵי עָלְמָא דַּחְיָין לָהּ לַשְּׁכִינְתָּא. חַד מִנַּיְיהוּ מַאן דִּמְחַבֵּל אָרְחֵיהּ עַל אַרְעָא כִּדְאֲמָרָן. וּבְגִין כָּךְ לָא חָמֵי אַנְפֵּי שְׁכִינְתָּא וְלָא עָאל בְּפַלְטֵרִין. וְעַל דָּא כְּתִיב בְּאִלֵּין וַיִּמָּחוּ מִן הָאָרֶץ אִתְמָחוּן מִן כֹּלָּא.</p>\n<p>תָּא חֲזֵי, בְּהַהוּא זִמְנָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַחְיָיאָה מֵתַיָיא, כָּל אִנּוּן מֵתִין דְּיִשְׁתַּכְּחוּן לְבַר בִּשְׁאָר אַרְעִין נוּכְרָאִין קוּדְשָׁא בְּרִיךְ הוּא יִבְרָא לוֹן גּוּפַיְיהוּ (נ\"א יוקים לון בגופייהו) כְּדְקָא חָזֵי. דְּהָא גַּרְמָא חַד דְּאִשְׁתָּאַר בֵּיהּ בְּבַר נָשׁ תְּחוֹת אַרְעָא הַהוּא גַרְמָא יִתְעֲבִיד כְּחֲמִירָא בְּעִיסָה וְעֲלֵיהּ יִבְנֵי קוּדְשָׁא בְּרִיךְ הוּא כָּל גּוּפָא.</p>\n<p>וְלָא יָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתִין אֶלָּא בְּאַרְעָא דְיִשְׂרָאֵל. דִּכְתִיב, (יחזקאל ל״ז:י״ב) הִנֵּה אֲנִי פּוֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. דְּיִתְגַּלְגְּלוּן תְּחוֹת אַרְעָא. וּלְבָתַר מַה כְּתִיב וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם וְגו'. דְּהָא בְּאַרְעָא דְיִשְׂרָאֵל יְקַבְּלוּן נִשְׁמָתִין כָּל (אנון) בְּנֵי עָלְמָא. בַּר אִלֵּין (דרא דטופנא) דְּאִסְתָּאֲבוּ וּסְאִיבוּ אַרְעָא. בְּאִלֵּין כְּתִיב וַיִּמָּחוּ מִן הָאָרֶץ. מִן הָאָרֶץ דַּיְיקָא. וְאַף עַל גַּב דְּאַקְשׁוּ וְאַפְלִיגוּ קַדְמָאֵי עַל דָּא. וַיִּמָּחוּ כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ט:כ״ט) יִמָּחוּ מִסֵּפֶר חַיִים.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן וַדַּאי לֵית לוֹן חוּלָקָא בְּעָלְמָא דְאָתֵי דִּכְתִיב וַיִּמָּחוּ מִן הָאָרֶץ. וּכְתִיב לְעוֹלָם יִירְשׁוּ אָרֶץ. אֲבָל יְקוּמוּן בְּדִין. וְעֲלַיְיהוּ כְּתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדֵרָאוֹן עוֹלָם. וּפְלוּגְתָּא בְּהָא אֲבָל כֹּלָּא כְּמָה דְאוּקְמוּהָ חַבְרַיָיא:</p>"],[9520011164,"<p>וַיִּמַּח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. רַבִּי אַבָּא אָמַר (את כל) לְאַכְלָלָא כָּל אִנּוּן שַׁלִּיטִין דְּשָׁלְטִין מְמַנָּן עַל אַרְעָא. וְדָא הוּא הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה. דְּכַד עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בִּבְנֵי עָלְמָא אַעֲבַר לְאִנּוּן שַׁלִּיטִין דִּמְמַנָּן עֲלַיְיהוּ בְּקַדְמִיתָא וּלְבָתַר לְאִנּוּן דְּיַתְבֵי תְּחוֹת גַּדְפַיְיהוּ דִּכְתִיב (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וּלְבָתַר עַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>וְהֵיךָ מִתְעַבְרָן קַמֵּיהּ. אֶלָּא אַעֲבַר לוֹן בְּנוּרָא דְּדָלִיק הֲדָא הוּא דִכְתִיב, (דברים ד׳:כ״ד) כִּי ה' אֱלהֶיךָ אֵשׁ אוֹכְלָה הוּא אֵל קַנָּא. אֶשָׁא (הוא) דְּאָכִיל אֶשָׁא. הַהוּא יָקוּם דְּעֲלַיְיהוּ (נ\"א מעבר) בְּאֶשָׁא. וְאִנּוּן דְּיַתְבֵי תְּחוֹתַיְיהוּ בְּמַיָא. וּבְגִינֵי כָּךְ וַיִּמַּח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנִי הָאֲדָמָה. וּלְבָתַר מֵאָדָם וְעַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמַיִם וַיִּמָּחוּ מִן הָאָרֶץ. כָּל אִלֵּין דִּלְתַתָּא. וַיִּשָּׁאֶר אַךְ נֹחַ. אַךְ לִמְעוּטֵי. דְּלָא אִשְׁתָּאֲרוּ בְּעָלְמָא בַּר נֹחַ וּדְעִמֵּיהּ בְּתֵיבוּתָא. רַבִּי יוֹסֵי אוֹמֵר חֲגִיר הֲוָה דְּאָכִישׁ לֵיהּ אַרְיָא וְהָא אוּקְמוּהָ:</p>"],[9520011165,"<p>וַיִּזְכֹּר אֱלהִים אֶת נֹחַ וְאֶת כָּל הַחַיָּה וְאֶת כָּל הַבְּהֵמָה אֲשֶׁר אִתּוֹ בַּתֵּבָה. רַבִּי חִיָּיא פָּתַח (משלי כ״ב:ג׳) עָרוּם רָאָה רָעָה וְנִסְתָּר. הַאי קְרָא אִתְּמָר עַל נֹחַ דְּעָאל לְתֵיבוּתָא וְאִסְתַּתַּר בָּהּ. וְעָאל לְגוֹ תֵיבוּתָא בְּזִמְנָא דְמַיָּיא דָּחֲקוּ לֵיהּ. וְהָא אִתְּמָר דְּעַד לָא עָאל לְתֵיבוּתָא חָמָא לֵיהּ לְמַלְאַךְ הַמָּוֶת דְּאָזִיל בֵּינַיְיהוּ וְאַסְחַר לוֹן. כֵּיוָן דְּחָמָא לֵיהּ, עָאל לַתֵּבָה וְאִסְתַּתַּר בְּגַוָּהּ. הֲדָא הוּא דִכְתִיב עָרוּם רָאָה רָעָה וְנִסְתָּר. רָאָה רָעָה דָּא מַלְאַךְ הַמָּוֶת וְנִסְתָּר מִקַּמֵּיהּ הֲדָא הוּא דִכְתִיב מִפְּנֵי מֵי הַמַּבּוּל.</p>\n<p>רַבִּי יוֹסֵי אָמַר עָרוּם רָאָה רָעָה וְנִסְתָּר. (ויסתר לא כתיב), אַהֲדַר עַל מַה דְּאִתְּמָר בְּזִמְנָא דְּמוֹתָא שַׁרְיָא בְּעָלְמָא בַּר נָשׁ חַכִּים יִסָּתֵר וְלָא יָקוּם לְבַר וְלָא יִתְחֲזֵי קַמֵּי מְחַבְּלָא. בְּגִין דְּכֵיוָן דְּאִתְיְיהִיב לֵיהּ רְשׁוּ, יְחַבֵּל כָּל אִנּוּן דְּיִשְׁתַּכְּחוּן קַמֵּיהּ וְיַעַבְרוּן קַמֵּיהּ בְּאִתְגַלְיָיא. וְסוֹפָא דִקְרָא וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ עָבְרִין קַמֵּיהּ וְאִתְחַזְיָין קַמֵּיהּ וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָבְרוּ, עָבְרוּ פִּקּוּדָא (דא) (נ\"א דמאריהון) וְנֶעֱנָשׁוּ. דָּבָר אַחֵר עָרוּם רָאָה רָעָה וְנִסְתָּר דָּא נֹחַ. וּפְתָאִים עָבְרוּ וְנֶעֱנָשׁוּ אִלֵּין בְּנֵי דָרֵיהּ.</p>\n<p>(ונענשו), כֵּיוָן דְּאִסְתַּתַּר וְאִשְׁתָּהֵי תַּמָּן כָּל הַהוּא זִמְנָא. <Nonei></i>לְבָתַר וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ. אָמַר רַבִּי שִׁמְעוֹן (ויזכור אלהים את נח) תָּא חֲזֵי בְּשַׁעֲתָא דְּדִינָא אִתְעֲבִיד לָא כְּתִיב בֵּיהּ זְכִירָה. כֵּיוָן דְּאִתְעֲבִיד (ביה) דִּינָא וְאִתְאֲבִידוּ חַיָּיבֵי עָלְמָא, כְּדֵין כְּתִיב בֵּיהּ זְכִירָה. דְּהָא כַּד דִּינָא שַׁרְיָא בְּעָלְמָא אִתְחַבְּרוּתָא לָא אִשְׁתְּכַח. וּמְחַבְּלָא שַׁרְיָא עַל עָלְמָא.</p>\n<p>כֵּיוָן דְּאִתְעֲבַר דִּינָא וְאִשְׁתַּכִּיךְ רוּגְזָא, תָּב כֹּלָּא לְאַתְרֵיהּ. וּבְגִין כָּךְ כְּתִיב הָכָא וַיִּזְכֹּר אֱלהִים אֶת נֹחַ. דְּבֵיהּ שַׁרְיָא זָכוֹר. דְּנֹחַ אִישׁ צַדִּיק כְּתִיב בֵּיהּ.</p>\n<p>כְּתִיב, (תהילים פ״ט:י׳) אַתָּה מוֹשֵׁל בְּגֵאוּת הַיָּם בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. בְּשַׁעֲתָא דְּיַמָּא קָפִיץ בְּגַלְגּוּלֵי וּתְהוֹמֵי סָלְקֵי וְנָחֲתֵי, קוּדְשָׁא בְּרִיךְ הוּא שָׁדַר חַד חוּטָא מִסִּטְרָא דְּיָמִינָא וּמָשִׁיךְ גַּלְגְּלוֹי וְשָׁכִיךְ זַעְפֵּיהּ וְלֵית מַאן דְּיָדַע לֵיהּ.</p>\n<p>יוֹנָה נָחַת לְיַמָּא וְאִזְדַּמַּן לֵיהּ הַהוּא נוּנָא וּבָלַע לֵיהּ. הֵיךְ לָא נָפְקַת נִשְׁמְתֵיהּ מִנֵּיהּ וְלָא פָּרְחָא מִיָּד. אֶלָא בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט בְּהַהוּא גֵּאוּתָא דְיַמָּא.</p>\n<p>וְהַהוּא גֵּאוּתָא דְיַמָּא הוּא חַד חוּטָא דִּשְׂמָאלָא דְּסָלִיק לֵיהּ לְיַמָּא לְעֵילָא וּבֵיהּ אִסְתַּלַּק. וְאִי לָאו הַהוּא חוּטָא דְּמָטֵי לֵיהּ מִסִּטְרָא דְּיָמִינָא לָא סָלְקָא לְעָלְמִין. דְכַד (דכיון) דְּהַהוּא חוּטָא נָחִית לְיַמָּא וְיַמָּא אִתְאַחִיד בָּהּ כְּדֵין אִתְעָרִין גַּלְגְּלוֹי וְשַׁאֲגָן לְמִטְרַף טַרְפָּא. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא אָתִיב לֵיהּ (לון) לְאֲחוֹרָא וְתָבִין לְאַתְרַיְיהוּ.</p>\n<p>הֲדָא הוּא דִכְתִיב בְּשׂוֹא גַלָּיו אַתָּה תְשַׁבְּחֵם. תְּשַׁבְּחֵם לְאִנּוּן גַּלֵּי יַמָּא. תְּשַׁבְּחֵם תְּתַבַּר לוֹן לְאֲתָבָא לְאַתְרַיְיהוּ. דָּבָר אַחֵר תְּשַׁבְּחֵם מַמָּשׁ שְׁבָחָא הוּא לוֹן בְּגִין דְּסָלְקִין בְּתִיאוּבְתָּא לְמֶחמֵי. מִכָּאן כָּל מָאן דְּכָסִיף לְאִסְתַּכָּלָא וּלְמִנְדַע אַף עַל גַּב דְּלָא יָכִיל (נ\"א ולא יהבין ליה רשותא) שְׁבָחָא אִיהוּ דִילֵיהּ וְכֹלָּא מְשַׁבְּחָן לֵיהּ.</p>\n<p>אָמַר רַבִּי יְהוּדָה נֹחַ כַּד הֲוָה בַּתֵּיבָה דָּחִיל הֲוָה דְּלָא יִדְכַּר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. וְכֵיוָן דְּאִתְעֲבִיד דִּינָא וְאִתְעֲבָרוּ חַיָּיבֵי עָלְמָא כְּדֵין מַה כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת נֹחַ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַרתָּא חֲזֵי, בְּשַׁעֲתָא דְדִינָא שַׁרְיָא בְּעָלְמָא לָא לִיבָּעֵי לֵיהּ לְאֵינִישׁ דְּיִדְכַּר שְׁמֵיהּ לְעֵילָא (קמיה דקודשא בריך הוא בעלמא). דְּהָא אִי אַדְכַּר שְׁמֵיהּ יִדְכְּרוּן חוֹבוֹי (כלהו) וְיֵיתוּן לְאַשְׁגָּחָא בֵּיהּ.</p>\n<p>מְנָלָן מִשּׁוּנַמִּית, דְּהַהוּא יוֹמָא יוֹם טוֹב דְּרֹאשׁ הַשָּׁנָה הֲוָה וְקוּדְשָׁא בְּרִיךְ הוּא דָּאִין עָלְמָא. וּכְדֵין אָמַר לֵיהּ אֱלִישָׁע (מלכים ב ד׳:י״ג) הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ דָּא קוּדְשָׁא בְּרִיךְ הוּא. דִּכְדֵין אִקְרֵי מֶלֶךְ. מֶלֶךְ הַקָּדוֹשׁ מֶלֶךְ הַמִּשְׁפָּט. וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יוֹשָׁבֶת. לָא בָּעֵינָא דְּיִדְכְּרוּן לִי וְיִשְׁגְּחוּן בִּי אֶלָּא בְּתוֹךְ עַמִי. מַאן דְּעֲיִּיל רֵישֵׁיהּ בֵּין עַמָּא (כלא) לָא יִשְׁגְּחוּן עֲלֵיהּ לְמֵידַן לֵיהּ לְבִישׁ. בְּגִינֵי כָךְ אָמְרָה בְּתוֹךְ עַמִּי.</p>\n<p>תָּא חֲזֵי, נֹחַ בְּשַׁעֲתָא דְרוּגְזָא שַׁרְיָא בְּעָלְמָא לָא אִדְכַּר. כֵּיוָן דְּדִינָא אִתְעֲבָר מַה כְּתִיב וַיִּזְכֹּר אֱלהִים אֶת נֹחַ הַשְׁתָּא אִדְכַּר שְׁמֵיהּ. דָּבָר אַחֵר וַיִּזְכֹּר אֱלהִים אֶת נֹחַ כְּמָה דְּאַתְּ אָמֵר וָאֶזְכֹּר אֶת בְּרִיתִי.</p>"],[9520011166,"<p>רַבִּי חִזְקִיָּה הֲוָה אָזִיל מִקַּפּוֹטְקִיָּא לְלוּד. פָּגַע בֵּיהּ רַבִּי יֵיסָא. אָמַר לֵיהּ תְּוַוהְנָא עֲלָךְ דְּאַתְּ בִּלְחוֹדָךְ. דְּהָא תָּנִינָן דְּלָא יִפּוּק בַּר נָשׁ יְחִידָאי בְּאָרְחָא. אָמַר לֵיהּ רַבְיָא חַד אָזִיל בַּהֲדָאי וְאִיהוּ אָתֵי אֲבַתְרָאי. אָמַר לֵיהּ וְעַל דָּא תְּוַוהְנָא אֵיךְ אָזִיל בַּהֲדָךְ מַאן דְּלָא תִשְׁתָּעֵי בֵּיהּ מִלֵּי דְאוֹרַיְיתָא. דְּהָא תָּנִינָן כָּל מַאן דְּאָזִיל בְּאָרְחָא וְלָאו עִמֵּיהּ מִלֵּי דְאוֹרַיְיתָא אִסְתַּכַּן בְּנַפְשֵׁיהּ. אָמַר לֵיהּ הָכִי הוּא וַדַּאי.</p>\n<p>אַדְהָכִי מָטָא הַהוּא רַבְיָא. אָמַר לֵיהּ רַבִּי יֵיסָא בְּרִי מֵאָן אֲתַר אַנְתְּ. אָמַר לֵיהּ מִקַּרְתָּא דְלוּד וְשָׁמַעְנָא דְּהַאי בַּר נָשׁ חַכִּים אָזִיל תַּמָּן וְזַמִּינָא גַרְמָאי לְפוּלְחָנִיהּ וּלְמֵיהַךְ בַּהֲדֵיהּ.</p>\n<p>אָמַר לֵיהּ בְּרִי יְדַעְתְּ מִלֵּי דְאוֹרַיְיתָא. אָמַר לֵיהּ יְדַעְנָא דְּהָא אַבָּא הֲוָה אוֹלִיף לִי בְּפָרָשַׁת קָרְבָּנוֹת וְאַרְכִינָא אוּדְנָאי לְמַאי דְּהֲוָה אָמַר עִם אָחִי דְּאִיהוּ קְשִׁישָׁא מִנָּאי. אָמַר לֵיהּ רַבִּי יֵיסָא בְּרִי אֵימָא לִי.</p>\n<p>פָּתַח וְאָמַר וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְּהוֹרָה וּמִכָּל הָעוֹף הַטָּהוֹר וַיַּעַל עוֹלוֹת בַּמִּזְבֵּחַ. וַיִּבֶן נֹחַ מִזְבֵּחַ, דָּא אִיהוּ מִזְבֵּחַ דְּאַקְרִיב בֵּיהּ אָדָם קַדְמָאָה. נֹחַ <Nonei></i>אַמַּאי קָרִיב עוֹלָה. דְּהָא עוֹלָה לָא סַלְקָא אֶלָּא בְּגִין הִרְהוּרָא דְלִבָּא (דרעותא) וְנֹחַ בְּמָּה חָב. אֶלָּא נֹחַ הִרְהֵר וְאָמַר הָא קוּדְשָׁא בְּרִיךְ הוּא גָּזַר דִּינָא עַל עָלְמָא דְּיִתְחָרַב, דִּילְמָא בְּגִין דְּשֵׁזִיב לִי כָּל זְכוּתָא פָּקַע לִי וְלָא יִשְׁתָּאַר לִי זְכוּ בְּעָלְמָא. מִיָּד וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ.</p>\n<p>הַהוּא מִזְבֵּחַ דְּאַקְרִיב בֵּיהּ אָדָם הָרִאשׁוֹן הֲוָה. אִי הָכִי אַמַּאי וַיִּבֶן. אֶלָּא בְּגִין דְּחַיָּיבֵי עָלְמָא גָּרְמוּ דְּלָא קָיְימָא בְּדוּכְתֵּיהּ. כֵּיוָן דְּאָתָא נֹחַ כְּתִיב בֵּיהּ וַיִּבֶן.</p>\n<p>וַיַּעַל עוֹלוֹת עֹלַת כְּתִיב חָדָא (הוא). כְּתִיב, (ויקרא א׳:י״ג) עוֹלָה הִוא אִשֵּׁה רֵיחַ נִיחֹחַ לַיְיָ (לעולם עולה סלקא דכר. אי) עוֹלָה סַלְקָא דְּכַר וְלָא סַלְקָא נוּקְבָא דִּכְתִיב זָכָר תָּמִים יַקְרִיבֶנּוּ. אַמַּאי כְּתִיב אִשֶּׁה דְּהָא אֵשׁ בָּעֵי לְאִשְׁתַּכְּחָא תַּמָּן.</p>\n<p>אֶלָא אַף עַל גַּב דְּעוֹלָה אִתְקְרִיב דָּכָר. וּלְאַתְרֵיהּ אִתְקְרִיב. נוּקְבָא לָא בָּעְיָא לְאִתְפָּרְשָׁא מִנֵּיהּ, אֶלָּא בָּהּ אִתְקְרִיב בְּגִין לְחַבְּרָא דָּא בְּדָא. דְּסָלְקָא נוּקְבָא לְגַבֵּי דְכוּרָא לְאִתְחַבְּרָא כְּחֲדָא. וְאַף עַל גַּב דְּאִשֶּׁה לְשׁוּם אִישִׁים.</p>\n<p>נֹחַ אִצְטְרִיךְ לֵיהּ לְמִקְרַב עוֹלָה. דְּאִיהוּ בְּאֲתַר דִּדְכוּרָא. עֲבַד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאִתְחַבְּרָא וּלְאַעֲלָאָה בַּתֵּיבָה. וְעַל דָּא אַקְרִיב עוֹלָה. עוֹלָה הוּא אִשֶּׁה. אֵשׁ ה' דְּאִתְחַבַּר (בה) שְׂמָאלָא בְּנוּקְבָא. דְּהָא (כל) נוּקְבָא מִסִּטְרָא דִשְׂמָאלָא קָא אַתְיָא וּדְכוּרָא מִסִטְרָא דִימִינָא בְּאִתְדַּבְּקוּתָא דָּא בְּדָא. וּבְגִין כָּךְ אִקְרֵי נוּקְבָא אִשֶּׁה. אִשֶּׁה קְטִירוּ דִּרְחִימוּ דְּאָחִיד בָּהּ שְׂמָאלָא לְסַלְקָא לָהּ לְעֵילָא וּלְאִתְקַשְּׁרָא כְּחֲדָא. וּבְגִין כָּךְ (ד\"א כתיב) עוֹלָה הִוא אִשֵּׁה. קְשִׁירוּ דִּדְכַר וְנוּקְבָא דָּא בְּדָא:</p>"],[9520011167,"<p>וַיָּרַח יְיָ אֶת רֵיחַ הַנִּיחֹחַ. וּכְתִיב אִשֶּׁה רֵיחַ נִיחוֹחַ. אִשֶּׁה הָכִי שְׁמַעְנָא תְּנָנָא וְאֶשָׁא מְחֻבָּרִין כְּחֲדָא. דְּהָא לֵית תְּנָנָא בְּלָא אֶשָׁא כְּמָה דִכְתִיב (שמות י״ט:י״ח) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו יְיָ בָּאֵשׁ.</p>\n<p>תָּא חֲזֵי (נשא קלז, קלח) אֵשׁ נָפִיק מִלְּגָיו וְאִיהוּ דַּק. וְאָחִיד בְּמִלָּה אָחֳרָא לְבַר דְּלָאו אִיהוּ דַּק הָכִי וְאִתְאַחֲדָן דָּא בְּדָא וּכְדֵין תְּנָנָא סָלְקָא. מַאי טַעְמָא בְּגִין דְּאִתְאֲחִיד אֶשָׁא בְּמִלָּה דְּרָגִישׁ. וְסִימָנָיךְ חוּטְמָא דְּנָפִיק בֵּיהּ תְּנָנָא מִגּוֹ אֶשָׁא.</p>\n<p>וְעַל דָּא כְּתִיב (דברים ל״ג:י׳) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךָ. בְּגִין דְּאַהֲדַר אֶשָׁא לְאַתְרֵיהּ. וְחוֹטְמָא (אתרגיש) אִתְכְּנִישׁ בְּהַהוּא רֵיחָא לְגוֹ לְגוֹ עַד דְּאִתְאַחִיד כֹּלָּא וְתָב לְאַתְרֵיהּ. וְאִתְקְרִיב כֹּלָּא לְגוֹ מַחְשָׁבָה וְאִתְעֲבִיד רְעוּתָא חָדָא. וּכְדֵין רֵיחַ נִיחֹחַ. דְּנָח רוּגְזָא וְאִתְעֲבִיד נַיְיחָא.</p>\n<p>דְּהָא תְּנָנָא אִתְכְּנִישׁ וְעֲיִּיל וְקָמִיט בְּאֶשָׁא וְאֶשָׁא אָחִיד בִּתְנָנָא וְעַיְילֵי תַּרְוַויְיהוּ לְגוֹ לְגוֹ עַד דְּנָח רוּגְזָא. וְכַד אִתְאֲחִיד (אחיד) כֹּלָא דָּא בְדָא וְנָח רוּגְזָא, כְּדֵין הוּא נַיְיחָא, וּקְשִׁירוּ חַד וְאִתְקְרֵי נַיְיחָא. נַיְיחָא דְרוּחָא חֶדְוָותָא דְּכֹלָּא כְּחֲדָא. נְהִירוּ דְּבוֹצִינִין נְהִירוּ דְּאַנְפִּין. וּבְגִין כָּךְ כְּתִיב, וַיָּרַח יְיָ אֶת רֵיחַ הַנִּיחֹחַ. כְּמַאן דְּאָרַח וְכָנִישׁ כֹּלָּא לְגוֹ אַתְרֵיהּ.</p>\n<p>אַתָא רַבִּי יֵיסָא וּנְשָׁקֵיהּ. אָמַר וּמַה כָּל הָדֵין טָבָא אִית תְּחוֹת יְדָךְ וְלָא יְדַעְנָא בֵּיהּ. אָמַר אַהֲדַרְנָא מִן אוֹרְחָא, וְנִתְחַבֵּר בַּהֲדָךְ. אֲזְלוּ. אָמַר רַבִּי חִזְקִיָּה אָרְחָא דָא בַּהֲדֵי שְׁכִינְתָּא נְהַךְ דְּהָא מִתַקְנָא קַמָּן. אָחִיד בִּידָא דְּהַהוּא יְנוּקָא וְאֲזְלוּ. אָמְרוּ לֵיהּ אֵימָא לָן קְרָא חַד מֵאִנוּן דְּאָמַר לָךְ אֲבוּךְ.</p>\n<p>פָּתַח הַהוּא יְנוּקָא וְאָמַר (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְשִׁיקוֹת פִּיהוּ, דָּא הוּא תְּאוֹבְתָּא עִלָּאָה דְּיִפּוּק (דנפקא) רְעוּתָא מִפּוּמָא לְנַשְׁקָא וְלָא נָפִיק מֵחוֹטְמָא כַּד אֶשָׁא נָפְקָא, דְּהָא כַּד אִתְחַבֵּר פּוּמָא לְנַשְׁקָא נָפִיק אֶשָׁא בִּרְעוּתָא בִּנְהִירוּ דְאַנְפִּין בְּחֶדְוָה דְּכֹלָא בְּאִתְדַּבְּקוּתָא דְנַיְיחָא.</p>\n<p>וּבְגִין כָּךְ כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן. מֵהַהוּא יַיִן (יין) דְּמֶחדֵי וְנָהִיר אַנְפִּין וְחָיְיכִין עַיְינִין וְעָבִיד רְעוּתָא. וְלָאו מִיַּיִן דִּמְשַׁכֵּר (דשכיר) וְעָבִיד רוּגְזָא וְאַחְשִׁיךְ אַנְפִּין וְלָהֲטָאן עַיְינִין יַיִן דְּרוּגְזָא.</p>\n<p>וְעַל דָּא בְּגִין דְּחֲמַר דָּא טַב, נָהִיר אַנְפִּין וְחָדֵי עַיְינִין וְעָבִיד תִּיאוּבְתָּא דִרְחִימוּ, מַקְרִיבִין לֵיהּ כָּל יוֹמָא עַל גַּבֵּי מַדְבְּחָא <Nonei></i>שִׁעוּרָא דְּמַאן דְּשָׁתֵי לֵיהּ חָדֵי לֵיהּ וְעָבִיד לֵיהּ נַיְיחָא דִכְתִיב (במדבר כ״ח:ה׳) וְנִסְכּוֹ יַיִן רְבִיעִית הַהִין. וּבְגִין כָּךְ כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן. מֵהַהוּא יַיִן דְּאִתְעַר רְחִימוּתָא וְתִיאוּבְתָּא.</p>\n<p>וְכֹלָּא כְּמָה דִלְתַתָּא אִתְעַר רְחִימוּתָא דִּלְעֵילָא. תְּרֵין שְׁרַגִּין כַּד אִתְדָעַךְ נְהוֹרָא דִּלְעֵילָא בִּתְנָנָא דְסָלִיק מֵהַהוּא דִלְתַתָּא אִתְדְּלִיק הַהוּא דִלְעֵילָא. אָמַר רַבִּי חִזְקִיָה הָכִי הוּא וַדַּאי דְּעָלְמָא עִלָּאָה תַּלְיָא בְּתַתָּאָה וְתַתָּאָה בְּעִלָּאָה, וּמֵזִמְנָא דְּאִתְחְרִיב בֵּי מַקְדְּשָׁא בִּרְכָאן לָא אִשְׁתַּכָּחוּ לְעֵילָא וְתַתָּא. לְאַחֲזָאָה דְּדָא בְּדָא תַּלְיָא.</p>\n<p>וְאָמַר רַבִּי יוֹסֵי בִּרְכָאן לָא אִשְׁתַּכָּחוּ וּלְוָוטִין אִשְׁתַּכָּחוּ, דְּהָא יְנִיקוּ דְּכֹלָּא בְּהַהוּא סִטְרָא נָפְקֵי (ד\"א וברכאן לא נפקי), מַאי טַעְמָא, בְּגִין דְּיִשְׂרָאֵל לָא שַׁרְיָין בְּאַרְעָא וְלָא פָּלְחֵי פּוּלְחָנָא דְאִצְטְרִיךְ לְאַדְלָקָא בּוֹצִינִין וּלְאִשְׁתַּכָּחָא בִּרְכָאן, וּבְגִין כָּךְ לָא מִשְׁתַּכְּחֵי לְעֵילָא וְתַתָּא, וְעָלְמָא לָא יָתִיב בְּקִיּוּמֵיהּ כְּדְקָא יְאוּת.</p>\n<p>וְאֲמַר רַבִּי חִזְקִיָּה לא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַאי הוּא, אָמַר רַבִּי יֵיסָא הָכִי שְׁמַעְנָא מֵרַבִּי שִׁמְעוֹן דְּאָמַר כָּל זִמְנָא דְּאֶשָׁא דִּלְעֵילָא אוֹסִיף לְתָקְפָא, תְּנָנָא דְּאִיהוּ דִינָא דִלְתַתָּא אַתְקִיף רוּגְזָא וְשָׁצֵי כֹּלָּא. בְּגִין דְּכַד נָפִיק אֶשָׁא לֵית לֵיהּ פֶּסֶק (קמיה) עַד דְּיִשְׁתְּלִים דִּינָא. וְכַד דִּינָא דִּלְתַתָּא לָא אוֹסִיף לְאִתְתַּקְפָא בְּדִינָא דִלְעֵילָא עָבִיד דִּינָא וּפָסִיק וְלָא יִשְׁתַּלַּם דִּינָא לְשֵׁיצָאָה. וּבְגִין כָּךְ כְּתִיב לֹא אוֹסִיף לְמֵיהַב תּוֹסֶפֶת לְאִתְתַּקְפָא דִינָא דִלְתַתָּא.</p>\n<p>אָמַר הַהוּא יְנוּקָא שְׁמַעְנָא בְּגִין דִּכְתִיב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרְךָ. דְּהָא בְּהַהִיא שַׁעֲתָא דְּאִתְלַטְיָא אַרְעָא בְּחוֹבָא דְאָדָם. אִתְיְיהִיב רְשׁוּ לְשַׁלְטָאָה עֲלָהּ הַהוּא חִוְיָא בִישָׁא דְּאִיהוּ מְחַבְּלָא דְעָלְמָא וְשָׁצֵי בְּנֵי עָלְמָא. מֵהַהוּא יוֹמָא דְּקָרִיב נֹחַ קָרְבָּנָא, וְאָרַח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִתְיְיהִיב רְשׁוּ לְאַרְעָא לְנַפְקָא מִתְּחוֹת הַהוּא נָחָשׁ וְנָפְקָא מִמְסָאָבָא. וְעַל דָּא מַקְרִיבִין יִשְׂרָאֵל קָרְבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְאַנְהָרָא אַפֵּי אַרְעָא. אָמַר רַבִּי חִזְקִיָּה יָאוֹת הוּא (והיא) וְהַאי הֲוָה תָּלֵי עַד דְּקָיְימוּ יִשְׂרָאֵל עַל טוּרָא דְסִינַי. אָמַר רַבִּי יִיִסָא קוּדְשָׁא בְּרִיךְ הוּא אַזְעִיר לָהּ לְסִיהֲרָא וְשָׁלְטָא הַהוּא נָחָשׁ, אֲבָל בְּגִין חוֹבָא דְּאָדָם אִתְלַטְיָיא בְּגִין לְמֵילַט עָלְמָא. בְּהַהוּא יוֹמָא (דאתייהבת אורייתא) נַפְקַת אַרְעָא מֵהַהִיא קְלָלָה וְקָיְימָא סִיהֲרָא בְּהַהִיא גְרִיעוּתָא, בַּר בְּשַׁעֲתָא דְקוּרְבָּנָא אִשְׁתַּכָּחוּ בְּעָלְמָא וְיִשְׂרָאֵל יָתְבִין עַל אַרְעֲהוֹן.</p>\n<p>אָמַר רַבִּי יֵיסָא לְהַהוּא יְנוּקָא מַה שְּׁמָךְ, אָמַר לֵיהּ אַבָּא. אָמַר לֵיהּ אַבָּא תְּהֵא בְּכֹלָּא בְּחָכְמָה וּבְשָׁנִין. קָרָא עֲלֵיהּ (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ וְתָגֵל יוֹלַדְתֶּךָ.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא רוּחַ מְסָאֳבָא מִן עָלְמָא כְּמָה (ד\"א ל\"ג דאתמר) דִכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה יְיָ אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי יְיָ דִּבֶּר.</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַנְהָרָא לְסִיהֲרָא וְלְאֲפָקָא לָהּ מֵחֲשׁוֹכָא בְּגִין הַהוּא חִוְיָא בִישָׁא. כְּמָה דִכְתִיב, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. מַאי אוֹר, הַהוּא אוֹר דְּגָנִיז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדָא דִבְרֵאשִׁית:</p>"],[9520011168,"<p>וַיְבָרֶךָ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגו'. רַבִּי אַבָּא פָּתַח וְאָמַר, (משלי י׳:כ״ב) בִּרְכַּת יְיָ הִיא תַעֲשִׁיר וְלא יוֹסִיף עֶצֶב עִמָּהּ. בִּרְכַּת יְיָ דָּא שְׁכִינְתָּא דְּאִיהִי אִתְפַּקְדָא עַל בִּרְכָאן דְּעָלְמָא, וּמִנָּהּ נָפְקֵי בִּרְכָאן לְכֹלָּא.</p>\n<p>תָּא חֲזֵי מַה כְּתִיב בְּקַדְמִיתָא וַיֹּאמֶר יְיָ לְנֹחַ בֹּא אַתָּה וְכָל בֵּיתְךָ אֶל הַתֵּיבָה וְגו'. כְּמָה דְּאִתְּמָר דְּמָארֵיהּ דְּבֵיתָא יָהַב לֵיהּ רְשׁוּ לְמֵיעָאל. לְבָתַר אִתְּתָא אָמְרָה לֵיהּ לְנַפְקָא. בְּקַדְמִיתָא עָאל בִּרְשׁוּתָא דְבַעֲלָהּ, לְסוֹף נָפַק בִּרְשׁוּ דְאִתְּתָא. מִכָּאן אוֹלִיפְנָא מָארֵיהּ <Nonei></i>דְּבֵיתָא יָעִיל וְאִתְּתָא תָּפִיק, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר אֱלהִים אֶל נֹחַ לֵאמֹר צֵא מִן הַתֵּבָה. דְּרְשׁוּ הֲוָה בִידָהָא לְאֲפָקָא לֵיהּ לְאוּשְׁפִּיזָא וְלָא לְאַעֲלָא לֵיהּ.</p>\n<p>כֵּיוָן דְּנָפַק יָהַב מַתְּנָן לָהּ, בְּגִין דְּאִיהִי בְּבֵיתָא וּבֵיתָא בִּידָהָא. וְאִנוּן מַתְּנָן דְּיָהַב לָהּ בְּגִין לְאַסְגָּאָה לָהּ רְחִימוּתָא בְּבַעֲלָהּ. מִכָּאן אוֹלִיפְנָא אוֹרַח אַרְעָא לְאוּשְׁפִּיזָא. (למיהב בידא דבעלה כד נפק יהב מתנן לאתתיה ולא בידה ובגין כך כיון דיהב ליה מתנן) וְעַל דָּא לְבָתַר דְּיָהַב לָהּ מַתְּנָן לְאַסְגָּאָה לָהּ רְחִימוּתָא בְּבַעֲלָהּ (נ\"א כיון דנפק יהב מתנן ונבזבזן בידא דבעלה למיהב לאתתיה ולמחדי בה ולאסגאה לה רחימותא בבעלה, הדא הוא דכתיב ויקח מכל וגו' ויעל עולות במזבח, אלין מתנן דיהב בידא דבעלה בגין לאסגאה לה רחימותא בעלמא, ומכאן אוליפנא אורח ארעא לאושפיזא דיהב מתנן בידא דבעלה לאתתיה ולא בידהא, ועל דא ויעל עולות במזבח, קורבנא לדכורא לאסגאה רחימותא בבעלה ברכא ליה) בָּרְכָא לֵיהּ, דִּכְתִיב וַיְבָרֶךְ אֱלהִים אֶת נֹחַ וְאֶת בָּנָיו וַיֹּאמֶר לָהֶם פְּרוּ וּרְבוּ וְגו'. וּבְגִין כָּךְ כְּתִיב, (משלי י׳:כ״ב) בִּרְכַּת יְיָ הִיא תַעֲשִׁיר. וַדַּאי כְּמָה דְאִתְּמָר.</p>\n<p>וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. רָזָא דִּכְתִיב בְּעִצָּבוֹן תֹּאכֲלֶנָּה. עִצָּבוֹן עֲצִיבוּ וְרוּגְזָא בְּלָא נְהִירוּ דְאַנְפִּין. כַּד אִתְחֲשַׁךְ סִיהֲרָא וּבִרְכָאן לָא מִשְׁתַּכְּחֵי. בְּעִצָּבוֹן סִטְרָא דְרוּחָא אָחֳרָא דְּאִמְנַע בִּרְכָאן מֵעָלְמָא, וּבְגִין כָּךְ וְלֹא יוֹסִיף עֶצֶב עִמָּהּ. וְדָא הוּא רָזָא דִכְתִיב, (בראשית ח׳:כ״א) לא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה:</p>"],[9520011169,"<p>וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה. מִכָּאן וּלְהָלְאָה יְהֵא לְכוֹן דְּיּוֹקְנִין דִּבְנֵי נָשָׁא דְּהָא בְּקַדְמִיתָא לָא הֲווּ דִּיוּקְנִין דִּבְנֵי נָשָׁא. תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב, (בראשית ט׳:ו׳) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וּכְתִיב, (בראשית ה׳:א׳) בִּדְמוּת אֱלהִים עָשָׂה אוֹתוֹ. כֵּיוָן דְּחָטוּ אִשְׁתַּנּוּ דְּיוּקְנַיְיהוּ מֵהַהוּא דִּיוּקְנָא עִלָּאָה וְאִתְהַפָּכוּ אִנוּן לְמִדְחַל מִקַּמֵּי חֵיוָון בְּרָא.</p>\n<p>בְּקַדְמִיתָא כָּל בְּרִיָּין דְּעָלְמָא זָקְפָן עַיְינִין וְחָמָאן דִּיוּקְנָא קַדִּישָׁא עִלָּאָה וְזָעָאן וְדָחֲלִין מִקַּמֵּיהּ. כֵּיוָן דְּחָטוּ אִתְהַפַּךְ דְּיוּקְנַיְיהוּ מֵעֵינַיְיהוּ לִדְיוּקְנָא אָחֳרָא. וְאִתְהַפַּךְ דִּבְנֵי נָשָׁא זָעִין וְדָחֲלִין קַמֵּי שְׁאָר בְּרִיָּין.</p>\n<p>תָּא חֲזֵי, כָּל אִנוּן בְּנֵי נָשָׁא דְּלָא חָטָאן קַמֵּי מָארֵיהוֹן וְלָא עָבְרִין עַל פִּקּוּדֵי אוֹרַיְיתָא. זִיו דִּיוּקְנָא דִּלְהוֹן לָא אִשְׁתַּנֵּי מֵחֵיזוּ דִּדְיוּקְנָא עִלָּאָה. וְכָל בְּרִיָּין דְּעָלְמָא זָעִין וְדָחֲלִין קַמֵּיהּ. וּבְשַׁעֲתָא דִּבְנִי נָשָׁא עָבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, אִתְחַלַּף דִּיוּקְנָא דִלְהוֹן וְכֻלְהוּ זָעִין וְדָחֲלִין מִקַּמֵּי בְּרִיָין אָחֳרָנִין, בְּגִין דְּאִתְחַלַּף דִּיוּקְנָא עִלָּאָה וְאִתְעֲבַר מִנַּיְיהוּ, וּכְדֵין שָׁלְטֵי בְּהוּ חֵיוַת בְּרָא, דְּהָא לָא חָמוּ בְּהוּ הַהוּא דִּיוּקְנָא עִלָאָה כִּדְקָחָזֵי.</p>\n<p>וְעַל כָּךְ הַשְׁתָּא כֵּיוָן דְּעָלְמָא אִתְחַדַּשׁ כְּמִלְּקַדְּמִין, בָּרִיךְ לוֹן בְּרָכָה דָא וְשַׁלִּיט לוֹן עַל כֹּלָּא, כְּמָא דְאַתְּ אָמֵר וְכָל דְּגֵי הַיָּם בְּיֶדְכֶם נִתָּנוּ. וְאֲפִילּוּ נוּנֵי יַמָּא. רַבִּי חִיָּיא אָמַר בְּיֶדְכֶם נִתָּנוּ. מִקַּדְמַת דְּנָא. דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא מְסַר כֹּלָּא בִּידֵהוֹן דִּכְתִיב וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגו'.</p>\n<p>וַיְבָרֶךָ אֱלהִים אֶת נֹחַ. רַבִּי חִזְקִיָּה פָּתַח (תהלים לכ) לְדָוִד מַשְׂכִּיל אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה. הַאי קְרָא אוּקְמוּהָ, אֲבָל קְרָא דָא בְּרָזָא דְּחָכְמְתָא אִתְּמָר. דְּהָא תָּנִינָן בַּעֲשָׂרָה זִינֵי שְׁבָחָא שַׁבַּח דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא וְחַד מִנַּיְיהוּ מַשְׂכִּיל. וְהוּא דַּרְגָּא חַד מֵאִנוּן עֲשָׂרָה. וְדָוִד אַתְקִין גַּרְמֵיהּ עַד לָא יִשְׁרֵי עֲלוֹי הַאי דַּרְגָּא.</p>\n<p>אַשְׁרֵי נְשׂוּי פֶּשַׁע, דְּהָא בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַתְקִיל חוֹבֵי וְזַכְוָון דִּבְנֵי נָשָׁא דְּהַהוּא (ד\"א כד ההוא) תִיקְלָא דְּבִסְטַר חוֹבִין מִסְתַּלְּקִין וְאִנוּן אוֹחֳרָנִין זַכְיָין דְּאִנוּן בְּתִיקְלָא אָחֳרָא מַכְרִיעִין לְתַתָּא דָּא הוּא נְשׂוּי פֶּשַׁע.</p>\n<p>כְּסוּי חֲטָאָה בְּשַׁעֲתָא דְדִינָא שַׁרְיָא בְּעָלְמָא דִּיהֵא מְחַפְיָא דְּלָא יִשְׁלוֹט עֲלוֹי מְחַבְּלָא, כְּמָה דְּהֲוָה לְנֹחַ דְּכַסֵּי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵהַהוּא חֲטָאָה דְּאַמְשִׁיךְ עֲלֵיהּ אָדָם עַל עָלְמָא. דְּכֵיוָן דְּחֲטָאָה דָא אַנְגִיד אָדָם עַל עַלְמָא, שְׁאָר בְּרִיָּין שָׁלְטָאן וּבַר נָשׁ דָּחִיל מִנַּיְיהוּ וְעָלְמָא לָא אַתְקִין בְּתִקּוּנִיהּ. וּבְגִין כָּךְ כַּד נָפַק נֹחַ מִתֵּיבוּתָא קוּדְשָׁא בְּרִיךְ הוּא בָּרְכֵיהּ. דִּכְתִיב וַיְבָרֶךְ אֱלֹהִים אֶת נֹחַ וְאֶת בָּנָיו וְגו':</p>\n<p>וְאַתֶּם פְּרוּ וּרְבוּ. בְּהַנֵּי בִּרְכָאן לָא אִשְׁתַּכָּחוּ נוּקְבֵי, אֶלָּא אֶת נֹחַ וְאֶת בָּנָיו, אֲבָל נוּקְבֵי לָא אָמַר קְרָא. אָמַר רַבִּי שִׁמְעוֹן וְאַתֶּם כְּלָלָא דִּדְכוּרֵי <Nonei></i>וְנוּקְבֵי כְּחֲדָא. וְתוּ אֶת נֹחַ לְאַסְגָּאָה נוּקְבֵיהּ. וְאֶת בָּנָיו לְאַסְגָּאָה נוּקְבֵי דִלְהוֹן.</p>\n<p>וּבְגִין כָּךְ כְּתִיב אַתֶּם פְּרוּ וּרְבוּ לְמֶעְבַּד תּוֹלְדוֹת מִכָּאן וּלְהָלְאָה שִׁרְצוּ בָאָרֶץ. וְהָכָא יָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא שֶׁבַע פִּקּוּדֵי אוֹרַיְיתָא לוֹן וּלְכָל דְּאָתוּ אֲבַּתְרַיְיהוּ, עַד דְּקָיְימוּ יִשְׂרָאֵל בְּטוּרָא דְסִינַי וְאִתְיְיהַב לוֹן כָּל פִּקּוּדֵי אוֹרַיְיתָא כְּחֲדָא:</p>"],[9520011170,"<p>וַיֹּאמֶר אֱלֹהִים לְנֹחַ וְגו'. זֹאת אוֹת הַבְּרִית אֲשֶׁר אֲנִי נוֹתֵן בֵּינִי וּבֵינֵיכֶם וְגו'. אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן. נָתַתִּי מִקַּדְמַת דְּנָא. רַבִּי שִׁמְעוֹן פָּתַח (יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַה כְּתִיב לְעֵילָא וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי בְּלֶכְתָּן. אִלֵּין אַרְבַּע חֵיוָון רַבְרְבָן עִלָּאִין קַדִּישִׁין דְּהַהוּא רָקִיעַ מִתְתַּקְּנָא עֲלַיְיהוּ. וְכֻלְהוּ גַדְפַיְיהוּ (ד\"א ל\"ג פרישן) מִתְחַבְּרָאן דָּא בְּדָא לְחַפְיָיא גוּפַיְיהוּ.</p>\n<p>וּבְשַׁעֲתָא דְּאִנוּן פָּרְשֵׂי גַדְפַיְיהוּ, אִשְׁתְּמַע קוֹל גַּדְפִין דְּכֻלְהוּ דְּאָמְרֵי שִׁירָתָא, הֲדָא הוּא דִכְתִיב כְּקוֹל שַׁדַּי. דְּלָא אִשְׁתְּכִיךְ לְעָלְמִין. כְּמָה דִכְתִיב, (תהילים ל׳:י״ג) לְמַעַן יְזַמֶּרְךָ כָבוֹד וְלא יִדּוֹם. וּמַאי אָמְרֵי, (תהילים צ״ח:ב׳) הוֹדִיעַ יְיָ יְשׁוּעָתוֹ לְעֵינֵי הַגּוֹים גִּלָּה צִדְקָתוֹ.</p>\n<p>קוֹל הֲמֻלָּה כְּקוֹל מַחֲנְה, כְּקוֹל מַשִּׁרְיָיתָא קַדִּישָׁא כַּד מִתְחַבְּרָן כָּל חֵילִין עִלָּאִין לְעֵילָא. וּמַאי אָמְרֵי קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְיָ צְבָאוֹת מְלא כָל הָאָרֶץ כְּבוֹדוֹ. אֲהַדְּרוּ לְדָרוֹם אָמְרוּ קָדוֹשׁ, אֲהַדְּרוּ לְצָפוֹן אָמְרוּ קָדוֹשׁ. אֲהַדְּרוּ לְמִזְרָח אָמְרוּ קָדוֹשׁ. אֲהַדְּרוּ לְמַעֲרָב אָמְרוּ בָּרוּךְ.</p>\n<p>וְהַאי רָקִיעַ קָאִים עַל רֵישֵׁיהוֹן. וּבְכָל אֲתַר דְּאִיהִי אָזְלָא, אַסְחָרוּ אַפִּין לְהַהִיא סִטְרָא דְּאִתְכְּלִילוּ אַנְפִּין בֵּיהּ. אִסְחָרוּ אַנְפִּין לְאַרְבַּע זָוְיָין, וְכֻלְהוּ מִסְתַּחֲרִין לְתַתָּא.</p>\n<p>בְּרִבּוּעָא דִילֵיהּ אִתְגְּלִיפַת בְּאַרְבַּע אַנְפִּין, אַנְפֵּי אַרְיֵה. אַנְפֵּי נִשְׁרָא. אַנְפֵּי שׁוֹר. אַנְפֵּי אָדָם. גָּלִיף בְּכֻלְהוּ אָדָם. אַנְפֵּי אַרְיֵ\"ה אָדָם. אַנְפֵּי נֶשֶׁ\"ר אָדָם. אַנְפֵּי שׁוֹ\"ר (ד\"א אדם). כֻּלְהוּ כְּלִילָן בֵּיהּ. וּבְגִין כָּךְ כְּתִיב וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם.</p>\n<p>וְהַאי רָקִיעַ דְּאִתְרַבַּע כֻּלְהוּ גְּוָונִין כְּלִילָן בֵּיהּ, אַרְבַּע גְּוָונִין אִתְחַזְּיָין בֵּיהּ גְּלִיפִין בְּאַרְבַּע אַרְבַּע. בְּאַרְבַּע גְּלִיפִין רְשִׁימִין טְהִירִין עִלָּאִין וְתַתָּאִין. כַּד מִתְפָּרְשָׁאן גְּוָונִין דְּאִנוּן אַרְבַּע סָלְקִין תְּרֵיסַר. גַּוָון יָרֹק. גַּוָון סוּמָק. גַּוָּון חִוַּור. גַּוָון סַפִּיר דְאִתְכְּלִילוּ מִכָּל גְּוָונִין. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶּעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנּוֹגַהּ סָבִיב הוּא מַרְאֶה דְּמוּת כְּבוֹד יְיָ. חֵיזוּ דִּגְוָונִין דְּכֹלָּא. וּבְגִין כָּךְ אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן.</p>\n<p>מַאי קַשְׁתִּי, כְּמָה דְאִתְּמָר בְּיוֹסֵף דִּכְתִיב, (בראשית מ״ט:כ״ד) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ. בְּגִין דְּיוֹסֵף צַדִּיק אִקְרֵי, וּבְגִין כָּךְ קַשְׁתּוֹ דָּא בְּרִית דְּקֶשֶׁת דְּאִתְכְּלִיל בְּצַדִּיק, דִּבְרִית דָּא בְּדָא אִתְאַחִיד. וּבְגִין דְּנֹחַ הֲוָה צַדִיק, קָיְימָא דִילֵיהּ קֶשֶׁת.</p>\n<p>וַיָּפוֹזוּ. מַאי וַיָּפוֹזוּ, אַנְהִירוּ בַּחֲמִידוּ דְכֹלָּא. כְּמָא דְאַתְּ אָמֵר (תהילים י״ט:י״א) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים. אִתְנְהִירוּ בִּנְהִירוּ עִלָּאָה כַּד נָּטַר בְּרִית. וּבְגִין כָּךְ אִקְרֵי יוֹסֵף הַצַּדִּיק. עַל דָּא אִקְרֵי הַקֶּשֶׁת בְּרִית, כָּלִיל דָּא בְּדָא.</p>\n<p>זָהֲרָא יְקָרָא עִלָּאָה חֵיזוּ דְּכָל חֵיזוּ חָזוּ כְּחֵיזוּ טְמִירִין (נ\"א טמירא) גְּוָונִין טְמִירִין. גְּוָונִין דְּלָא אִתְגַּלְיָין. וְלֵית רְשׁוּ לְאִסְתַּכָּלָא בְּעֵינָא בַּקֶּשֶׁת כַּד אִתְחֲזֵי בְּעָלְמָא דְּלָא יִתְחֲזֵי קְלָנָא בִּשְׁכִינְתָּא. וְכֵן גְּוָונִין דְּקֶשֶׁת הוּא חֵיזוּ סוֹסְטִיפָא קְטִירָא כְּחֵיזוּ יְקָרָא עִלָּאָה דְּלָא לְאִסְתַּכָּלָא.</p>\n<p>וְכֵיוָן דְּאַרְעָא חָמַאת לְהַאי קֶשֶׁת קְיָימָא קַדִּישָׁא, אִתְקָיְימַת בְּקִיּוּמָא. וְעַל דָּא וְהָיְתָה לְאוֹת בְּרִית בֵּין אֱלהִים וְגו'. הַאי דְּאֲמָרָן דְּאִלֵּין תְּלַת גְּוָונִין וְחַד דְּאִתְכְּלִיל בֵּינַיְיהוּ כֻּלְהוּ רָזָא חָדָא. וּבְגוֹ עֲנָנָא סָלְקָא לְאִתְחֲזָאָה.</p>\n<p>(יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר. הַאי הִיא אֶבֶן שְׁתִיָּה דְּאִיהִי נְקוּדָה חָדָא דְּכָל עָלְמָא. וְקָיְימָא עֲלָהּ קֹדֶשׁ הַקֳּדָשִׁים. וּמַאי הִיא, כֻּרְסְיָיא קַדִּישָׁא עִלָּאָה דְּאִיהִי מְמַנָּא עַל אִלֵּין אַרְבַּע דְּמוּת כִּסֵּא בְּאַרְבַּע סָמְכִין, וְדָא הוּא תּוֹרָה שֶׁבְּעַל פֶּה.</p>\n<p>וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֶה אָדָם עָלָיו מִלְּמַעְלָה. דָּא הוּא תּוֹרָה שֶׁבִּכְתָב. מִכָּאן דְּתוֹרָה שֶׁבִּכְתָב יְשַׁוּוּן <Nonei></i>יָתָהּ עַל תּוֹרָה שֶׁבְּעַל פֶּה. בְּגִין דְּהַאי כֻּרְסְיָיא לְדָא, כְּמַרְאֵה אָדָם דְּאִיהוּ דִּיוּקְנָא דְּיַעֲקֹב דְּאִיהוּ יָתִיב עֲלָהּ.</p>"],[9520011171,"<p>רַבִּי יְהוּדָה קָם לֵילְיָא חַד לְמִלְעֵי בְּאוֹרַיְיתָא בְּפַלְגוּ לֵילְיָא בְּבֵי אוּשְׁפִּיזָא בְּמָתָא מַחְסֵיָא. וְהֲוָה תַּמָּן בְּבֵיתָא חַד יוּדָאי דְּאֲתָא בִּתְרֵי קְסִירָא דְקַטְפִירָא. פָּתַח רַבִּי יְהוּדָה וְאָמַר (בראשית כ״ח:כ״ב) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים. דָּא הִיא אֶבֶן שְׁתִיָּה דְּמִתַּמָּן אִשְׁתִּיל עָלְמָא וְעֲלָה אִתְבְּנֵי בֵּי מַקְדְּשָׁא.</p>\n<p>זָקַף רֵישֵׁיהּ הַהוּא יוּדָאי וְאֲמַר לָהּ הַאי מִלָּה אֵיךְ אֶפְשָׁר, וְהָא אֶבֶן שְׁתִיָּה עַד לָא אִתְבְּרֵי עָלְמָא הֲוַת וּמִינָהּ אִשְׁתִּיל עָלְמָא, וְאַתְּ אֲמַרְתְּ וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. דְּמַשְׁמַע דְּיַעֲקֹב שַׁוֵי לָהּ הַשְׁתָּא דִּכְתִיב, (בראשית כ״ח:כ״ב) וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מֵרַאֲשׁוֹתָיו. וְתוּ דְּיַעֲקֹב בְּבֵית אֵל הֲוָה וְהַאי אַבְנָא הֲוַת בִּיְרוּשָׁלַ ם.</p>\n<p>רַבִּי יְהוּדָה לָא אַסְחַר רֵישֵׁיהּ לְגַבֵּיהּ, פָּתַח וְאָמַר (עמוס ד׳:י״ב) הִכּוֹן לִקְרַאת אֱלקֶיךָ יִשְׂרָאֵל. וּכְתִיב, (דברים כ״ז:ט׳) הַסְכֵּת וּשְׁמַע יִשְׂרָאֵל. מִלֵּי דְאוֹרַיְיתָא בָּעְיָין כַּוָּונָה. וּמִלִּין דְּאוֹרַיְיתָא בָּעָאן לְאִתְתַּקָּנָא בְּגוּפָא וּרְעוּתָא כְּחֲדָא. קָם הַהוּא יוּדָאי וְאִתְלַבַּשׁ, וְיָתִיב לְגַבֵּיהּ דְּרַבִּי יְהוּדָה, וְאָמַר זַכָּאִין אַתּוּן צַדִּיקַיָא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יוֹמָא וְלֵילֵי.</p>\n<p>אָמַר לֵיהּ רַבִּי יְהוּדָה הַשְׁתָּא דְּכַוְונַת גַּרְמָךְ, אֵימָא מִילָךְ דְּנִתְחַבֵּר כְּחֲדָא. דְּהָא מִלֵּי דְאוֹרַיְיתָא בָּעְיָין תִּקּוּנָא דְגוּפָא וְתִקּוּנָא דְלִבָּא. וְאִי לָאו בְּעַרְסָאי שְׁכִיבְנָא וּבְלִבָּאי אָמַרְנָא מִלִּין. אֶלָּא הָא תָּנִינָן דְּאָפִילּוּ חַד דְּיָתִיב וְלָעֵי בְּאוֹרַיְיתָא שְׁכִינְתָּא אִתְחַבְּרַת בַּהֲדֵיהּ, וּמַה שְּׁכִינְתָּא הָכָא וְאֲנָא שָׁכִיב בְּעַרְסָאי. וְלָא עוֹד אֶלָּא דְּבַעֲיָין צַחוּתָא.</p>\n<p>וְתוּ דְּכָל בַּר נָשׁ (אחרי מות סז א) דְּקָם לְמִלְעֵי בְּאוֹרַיְיתָא מִפַּלְגוּ לֵילְיָא כַּד אִתְעַר רוּחַ צָפוֹן (בפלגו דליליא) קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא בְּגִנְתָּא דְעֵדֶן. וְהוּא וְכָל צַדִּיקַיָיא דִּבְגִנְתָּא כֻּלְהוּ צַיְיתִין (ליה וצייתין) לְאִלֵּין מִלִּין דְּנָפְקֵי מִפּוּמֵיהּ. וּמַה קוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָּיא מִתְעַדְּנִין לְמִשְׁמַע מִלֵּי דְאוֹרַיְיתָא בְּשַׁעֲתָא דָּא וְאֲנָא אֱהֵא שָׁכִיב בְּעַרְסָאי. אָמַר לֵיהּ הַשְׁתָּא אֵימָא מִילָךְ.</p>\n<p>אָמַר לֵיהּ שְׁאֵילְנָא עַל מַה דְּאֲמַרְתְּ בִּפְסוּקָא דָא (רזא דאבן שתיה דאמרת) וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלהִים דְּדָא אֶבֶן שְׁתִיָה. (השתא דציית למלי) הֵיךְ אֶפְשָׁר, דְּהָא אֶבֶן שְׁתִיָּה עַד לָא אִתְבְּרֵי עָלְמָא הֲוַת וּמִנָּהּ אִשְׁתִּיל עָלְמָא, וְאַתְּ אֲמַרְתְּ אֲשֶׁר שַׂמְתִּי, דְּמַשְׁמַע דְּיַעֲקֹב שַׁוֵּי לָהּ הַשְׁתָּא. וּכְתִיב וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מֵרַאֲשׁוֹתָיו.</p>\n<p>וְתוּ דְּיַעֲקֹב בְּבֵית אֵל הֲוָה וְאַבְנָא דָא הֲוַת בִּיְרוּשָׁלַם. אָמַר לֵיהּ כָּל אַרְעָא דְיִשְׂרָאֵל אִכְפַּל תְּחוֹתוֹי וְהַהוּא אֶבֶן תְּחוֹתֵיהּ הֲוַת. אָמַר לֵיהּ אֲשֶׁר שָׂם כְּתִיב. וּכְתִיב וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. אָמַר לֵיהּ אִי יָדַעְתְּ מִלָּה אֵימָא לָהּ.</p>\n<p>פָּתַח וְאָמַר, (תהילים י״ז:ט״ו) אֲנִי בְצֶדֶק אֶחזֶה פָנֶיךָ אֶשְׂבְּעָה בְהָקִיץ תְּמוּנָתֶךָ. דָּוִד מַלְכָּא חֲבִיבוּתָא וּדְבֵקוּתָא דִילֵיהּ בְּהַאי אֶבֶן הֲוָה. וְעֲלָהּ אָמַר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְכַד בָּעָא לְאִסְתַּכְּלָא בְּחִיזוּ יְקָרָא דְמָרֵיהּ, נְטַל לְהַאי אֶבֶן בִּידֵיהּ בְּקַדְמִיתָא וּלְבָתַר עָיִיל.</p>\n<p>בְּגִין דְּכָל מַאן דְּבָעֵי לְאִתְחֲזָאָה קַמֵּי מָרֵיהּ, לָא אָעִיל אֶלָּא בְּהַאי אֶבֶן. דִּכְתִיב, (ויקרא יג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. וְדָוִד מְשַׁבַּח גַּרְמֵיהּ וְאָמַר אֲנִי בְּצֶדֶק אֶחזֶה פָנֶיךָ. וְכָל אִשְׁתַּדְּלוּתֵיהּ דְּדָוִד לְאִתְחֲזָאָה בְּהַאי אֶבֶן כְּדְקָא יְאוּת לְגַבֵּי דִּלְעֵילָא.</p>\n<p>תָּא חֲזֵי, אַבְרָהָם אַתְקִין צְלוֹתָא דְצַפְרָא וְאוֹדַע טִיבוּ דְמָארֵיהּ בְּעָלְמָא. וְאַתְקִין הַהִיא שַׁעֲתָא בְּתִקּוּנָהָא כְּדְקָא יָאוֹת דִּכְתִיב, (בראשית כ״ב:ג׳) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. יִצְחָק אַתְקִין צְלוֹתָא דְמִנְחָה וְאוֹדַע בְּעָלְמָא דְּאִית דִּין וְאִית דַּיָּין דְּיָכוֹל לְשֵׁזָבָא וּלְמֵידַן עָלְמָא.</p>\n<p>יַעֲקֹב אַתְקִין צְלוֹתָא דְעַרְבִית, וּבְגִין צְלוֹתָא דָא דְּאַתְקִין מַה דְּלָא אַתְקִין בַר נָשׁ מִקַּדְמַת דְּנָא כְּדְקָא יְאוּת. בְגִין כָּךְ שַׁבַּח גַּרְמֵיהּ וְאָמַר <Nonei></i>וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה. דְּעַד הַהִיא שַׁעֲתָא לָא שַׁוִּי לָהּ אָחֳרָא כַּוָּותֵיהּ.</p>\n<p>וּבְגִין כָּךְ וַיִּקַּח אֶת הָאֶבֶן אֲשֶׁר שָׂם מְרַאֲשׁוֹתָיו וַיָּשֶׂם אוֹתָהּ מַצֵּבָה. מַאי מַצֵּבָה דְּהֲוָה נְפִילָה וְאוֹקִים לָהּ. וַיִּצּוֹק שֶׁמֶן עַל רֹאשָׁהּ. דְּהָא בְּיַעֲקֹב תַּלְיָא מִילְתָא לְמֶעְבַּד יַתִּיר מִכָּל בְּנֵי עָלְמָא.</p>\n<p>אֲתָא רַבִּי יְהוּדָה וּנְשָׁקֵיהּ, אָמַר לֵיהּ וְכָל הַאי יְדַעְתְּ (והיך) וְאַתְּ מִשְׁתַּדֵּל בִּסְחוֹרָתָא וּמַנַּח חַיֵּי עָלְמָא. אָמַר לֵיהּ דְּהֲוָה דְחִיקָא לִי שַׁעֲתָא, וְאִית לִי תְּרֵין בְּנִין וְקָיְימִין כָּל יוֹמָא בְּבֵי רַב וְאֲנָא אִשְׁתַּדַּלְנָא עַל מְזוֹנַיְיהוּ וּלְמֵיהַב לוֹן אֲגַר לְמוֹרַיְיהוּ בְּגִין דְּיִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא.</p>\n<p>פָּתַח וְאָמַר, (מלכים א ב׳:י״ב) וּשְׁלֹמֹה יָשַׁב עַל כִּסֵּא דָּוִד אָבִיו וַתִּכּוֹן מַלְכוּתוֹ מְאֹד. מַאי שְׁבָחָא דָא. אֶלָּא דְּאַתְקִין אֶבֶן שְׁתִיָּה וְשַׁוֵּי עֲלָהּ קֹדֶשׁ הַקֳּדָשִׁים וּכְדֵין וַתִּכּוֹן מַלְכוּתוֹ מְאֹד.</p>\n<p>וּכְתִיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא תִּיאוּבְתָּא דִילֵיהּ בָּהּ תָּדִיר, וּמַאן דְּלָא אִתְחֲזֵי בָּהּ לָא אָעִיל קַמֵּי מָארֵיהּ. וְעַל דָּא כְּתִיב וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם.</p>\n<p>וּרְאִיתִיהָ. מַאי וּרְאִיתִיהָ, רָזָא הוּא כְּמָא דְאַתְּ אָמֵר (יחזקאל ט׳:ד׳) וְהִתְוֵיתָ תָּיו עַל מִצְחוֹת וְגו'. לְאִתְחַזָּאָה עֲלַיְיהוּ. וְאִיכָּא דְאָמְרֵי דָּא רְשִׁימוּ דְּאָת קַדִּישָׁא דִּי בְּבִשְׂרָא.</p>\n<p>אָמַר רַבִּי יְהוּדָה וַדַּאי כֹּלָּא הוּא. (ד\"א הכי) אֲבָל הַאי קֶשֶׁת דְּאִתְחֲזֵי בְּעָלְמָא בְּרָזָא עִלָאָה קָיְימָא. וְכַד יִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא זְמִינָא הַאי קֶשֶׁת לְאִתְקַשְׁטָא בְּגַוְונוֹי כְּכַלָּה דָא דְּמִתְקַשְּׁטָא לְבַעֲלָהּ.</p>\n<p>אָמַר לֵיהּ הַהוּא יוּדָאי כָּךְ אָמַר לִי אַבָּא כַּד הֲוָה מִסְתַּלַּק מֵעָלְמָא (אמר לי) לָא תְצַפֵּי לְרַגְלֵי דִמְשִׁיחָא עַד דְּיִתְחֲזֵי הַאי קֶשֶׁת בְּעָלְמָא (ד\"א ל\"ג בעננא) מִתְקַשְׁטָא בְּגַוְונִי נְהִירִין וְיִתְנְהִיר לְעָלְמָא. וּכְדֵין צְפֵי לֵיהּ לְמָשִׁיחַ.</p>\n<p>מְנָלָן, דִּכְתִיב וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְהַשְׁתָּא דְּאִתְחַזְּיָא בִּגְוָונִין חֲשׁוֹכִין מִתְחַזְּיָא לְדוּכְרָנָא (והיא לזכור) דְּלָא יִיִתֵי מַבּוּל. אֲבָל בְּהַהִיא זִמְנָא אִתְחַזְּיָיא בִּגְוָונִין נְהִירִין וּמִתְקַשְּׁטָא בְּתִקּוּנָא כְּכַלָּה דְּמִתְקַשְּׁטָא לְבַעֲלָהּ וּכְדֵין לִזְכֹּר בְּרִית עוֹלָם וְיִדְכַּר קוּדְשָׁא בְּרִיךְ הוּא לְהַאי בְּרִית דְּאִיהוּ בְּגָלוּתָא וְיָקִים לָהּ מֵעַפְרָא הֲדָא הוּא דִכְתִיב, (הושע ג׳:ה׳) וּבִקְּשׁוּ אֶת יְיָ אֱלהֵיהֶם וְאֶת דָּוִד מַלְכָּם. וּכְתִיב, (ירמיהו ל׳:ט׳) וְעָבְדוּ אֶת יְיָ אֱלֹהֵיהֶם וְאֶת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם, אֲשֶׁר אָקִים מֵעָפָר כְּמָא דְאַתְּ אָמֵר, (עמוס ט׳:י״א) אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפָלֶת. וְעַל דָּא וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם וּלְאַקְמָא לָהּ מֵעַפְרָא.</p>\n<p>וְאָמַר הָכִי אַבָּא דִּבְגִין כָּךְ אִדְכַּר בְּאוֹרַיְיתָא פּוּרְקָנָא דְיִשְׂרָאֵל וּדְכוּרָנָא דִּילָהּ. וְדָא הוּא דִכְתִיב, (ישעיהו נ״ד:ט׳) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבוֹר מֵי נֹחַ עוֹד עַל הָאָרֶץ כֵּן נִשְׁבַּעְתִּי מִקְצוֹף עָלַיִךְ וּמִגְּעָר בָּךְ:</p>"],[9520011172,"<p>וַיִּהְיוּ בְּנִי נֹחַ הַיּוֹצְאִים מִן הַתֵּבָה. רַבִּי אֶלְעָזָר אָמַר כֵּיוָן דִּכְתִיב וַיִּהְיוּ בְּנֵי נֹחַ. אַמַּאי אָמַר הַיּוֹצְאִים מִן הַתֵּבָה. וְכִי בְּנִין אָחֳרָנִין הֲווּ לֵיהּ דְּלָא נָפְקֵי מִן תֵּיבוּתָא.</p>\n<p>אָמַר לֵיהּ רַבִּי אַבָּא אִין. דְּהָא לְבָתַר אוֹלִידוּ בְּנוֹי בְּנִין. דִּכְתִיב וְאֵלֶּה תּוֹלְדוֹת שֵׁם וְגו'. וְאִנוּן לָא נָפְקֵי מִגּוֹ תֵּיבוּתָא. וּבְגִין כָּךְ כְּתִיב הַיּוֹצְאִים מִן הַתֵּיבָה שֵׁם חָם וָיָפֶת.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר אִילּוּ הֲוֵינָא שְׁכִיחַ בְּעָלְמָא כַּד יָהִיב קוּדְשָׁא בְּרִיךְ הוּא סִפְרָא דְחֲנוֹךְ בְּעָלְמָא וְסִפְרָא דְאָדָם, אַתְקִיפְנָא דְּלָא יִשְׁתַּכְּחוּן בֵּינֵי אֱנָשָׁא, בְּגִין דְּלָא חַיְישׁוּ כָּל חֲכָמָאן לְאִסְתַּכְּלָא בְּהוּ וְטָעָן בְּמִלִּין אָחֳרָנִין לְאֲפָקָא מֵרְשׁוּ עִלָּאָה לִרְשׁוּ אָחֳרָא. וְהַשְׁתָּא הָא חַכִּימֵי עָלְמָא יָדְעִין מִלִּין וְסָתְמִין לוֹן וּמִתְתַּקְפֵי בְּפוּלְחָנָא דְּמָארֵיהוֹן.</p>\n<p>וְהַאי קְרָא אַשְׁכַּחְנָא בְּרָזָא דְרָזִין. (תוספתא) דְּכַד אִתְעַר חֶדְוָה דְּכָל חֶדְוָון טְמִירָא סְתִימָא סַבְתָּא דְסַבְתִּין אַנְהִיר מִנֵּיהּ נְהִירוּ דַּקִּיק. חֶדְוָה דְּכָל חֶדְוָון נָהִיר לְיָמִינָא בִּמְשַׁח רְבוּת עִלָּאָה. וְנָהִיר לִשְׂמָאלָא בְּחֶדְוָוה דְּחַמְרָא טַב, נָהִיר לְאֶמְצָעִיתָא בְּחֶדְוָוה (ד\"א דארגוונא) דִּתְרֵין סִטְרִין. רוּחַ אִתְעַר וְרוּחַ סָלְקָא וְאִתְיְיהִיב בְּרוּחָא.</p>\n<p>דָּבְקָן דָּא בְּדָא. תְּלַת עָאלִין בִּתְלַת. מִגּוֹ תְּלַת נָפְקָא חַד בְּרִית דְדָבְקָא בִּבְרִית. אִתְעֲבָרַת רוּחַ דְּסָלְקָא, מִתְעֲבָרַת מִנֵּיהּ. כַּד אִתְיְיהִיבַת בִּתְרֵין סִטְרִין אִתְדַּבְּקוּ רוּחָא בְּרוּחָא <Nonei></i>וּמִתְעַבְּרָן מִתְּלַת בְּנִין. וְנֹחַ וְתֵיבָה נָפְקוּ מִנַּיְיהוּ תְּלָתָא, כְּגַוְונָא דִּתְלָתָא (דלתתא) עִלָּאִין, וְאִלֵּין אִנוּן דְּנָפְקוּ מִגּוֹ תֵּיבוּתָא שֵׁם וְחָם וְיָפֶת. שֵׁם דְּבִסְטַר יָמִינָא, חָם דְּבִסְטַר שְׂמָאלָא. יֶפֶת אַרְגְּוָונָא דְּכָלִיל לוֹן.</p>\n<p>וְחָם הוּא אֲבִי כְנָעַן. זוּהֲמָא דְדַהֲבָא תְּחוֹת קַסְטִיפִין. אִתְעֲרוּתָא דְּרוּחָא מְסָאֲבָא דְּנָחָשׁ קַדְמָאָה. וּבְגִין כָּךְ רְשִׁים וְאָמַר, וְחָם הוּא אֲבִי כְנָעַן. דְּאַיְיתֵי לְוָוטִין עַל עָלְמָא. הַהוּא כְנָעַן דְּאִתְלַטְּיָא. הַהוּא כְנָעַן דְּאַחְשִׁיךְ אַנְפֵּי בְּרִיָּין.</p>\n<p>וּבְגִין כָּךְ (כלהו) לָא נָפִיק מִגּוֹ כְּלָלָא דְּכֻלְהוּ אֶלָּא דָא דִּכְתִיב וְחָם הוּא אֲבִי כְנָעַן. הַהוּא דְּאַחְשִׁיךְ עָלְמָא, וְלָא כְּתִיב בִּכְלָלָא דָא וְשֵׁם הוּא אֲבִי כָךְ אוֹ יֶפֶת הוּא אֲבִי כָךְ, אֶלָּא מִיָּד קָפַץ וְאָמַר וְחָם הוּא אֲבִי כְנָעַן. וַדַּאי.</p>\n<p>וְעַל דָּא כַּד אֲתָא אַבְרָהָם מַה כְּתִיב (בראשית י״ב:ו׳) וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. דְּעַד לָא הֲוָה קִיּוּמָא דְּאֲבָהָן וְלָא אָתוּ זַרְעָא דְיִשְׂרָאֵל בְּעָלְמָא, דְּיִפּוּק שְׁמָא דָא וְיֵיעוּל שְׁמָא עִלָּאָה קַדִּישָׁא. כַּד הֲווּ זַכָּאִין יִשְׂרָאֵל אִקְרֵי אַרְעָא עַל שְׁמָא דָא אֶרֶץ יִשְׂרָאֵל. כַּד לָא זָכוּ אִקְרֵי אַרְעָא עַל שְׁמָא אָחֳרָא, אֶרֶץ כְּנָעַן.</p>\n<p>וְעַל דָּא כְּתִיב, (בראשית ט׳:כ״ה) וַיֹּאמֶר אָרוּר כְּנַעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. דְּאִיהוּ אַיְיתֵי לְוָוטִין עַל עָלְמָא. וּבְנָחָשׁ מַה כְּתִיב, (בראשית ג׳:י״ד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה. הַיְינוּ דִכְתִיב עֶבֶד עֲבָדִים. וְעַל דָּא כְּתִיב שֵׁם חָם וְיָפֶת. תְּלַת אִלֵין בְּנֵי נֹחַ הַיּוֹצְאִים מִן הַתֵּיבָה כִּדְקָאַמְרִינָן:</p>"],[9520011173,"<p>שְׁלשָׁה אֵלֶּה בְּנִי נֹחַ. קִיּוּמָא דְּכָל עָלְמָא, קִיּוּמָא דְרָזָא עִלָּאָה. וּמֵאֵלֶּה נָפְצָה כָל הָאָרֶץ. הַיְינוּ רָזָא (דא) דִּתְלַת גְּוָונִין עִלָּאִין. דְּכַד הַהוּא נָהָר דְּנָגִיד וְנָפִיק אַשְׁקֵי לְגִנְתָא בְּחֵילָא דִתְלַת אִלֵּין עִלָּאִין. וּמִתַּמָּן אִתְפָּרְשָׁן גְּוָונִין דִּלְתַתָּא כָּל חַד וְחַד כָּלִיל בְּחַבְרֵיהּ, לְאַחֲזָאָה דִּיקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְפַּשַּׁט לְעֵילָא וְתַתָּא, וְאִיהוּ חַד בְּעִלָּאֵי וְתַתָּאֵי.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר תְּלַת גְּוָונִין אִלֵּין בְּכָל אִנוּן דְּאַתְיָין מִסְּטַר דִּקְדוּשָׁה, וּמֵחֵיזוּ דִּתְלַת גְּוָונִין אִלֵּין מִתְפָּרְשָׁאן לְכָל אִנוּן דְּאַתְיָין מִסִּטְרָא דְרוּחָא אָחֳרָא. וְכַד תִּסְתַּכֵּל בְּרָזָא דְדַרְגִּין תִּשְׁכַּח הֵיךְ מִתְפָּרְשָׁן גְּוָונִין לְכָל אִנוּן סִטְרִין עַד דְּעָיְילִין לְתַתָּא בְּרָזָא דְּאִנוּן שִׁבְעָה וְעֶשְׂרִין צִנּוֹרִין (סטרי) דְּדַשֵּׁי דְּחָפְיָין לִתְהוֹמֵי.</p>\n<p>וְכֹלָּא יְדִיעָא לַחֲכִימִין עֶלְיוֹנִין. זַכָּאָה חוּלַקְהוֹן דְּצַדִּיקַיָיא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בִּיקְרֵיהוֹן וְגָלֵי לוֹן סִתְרִין עִלָּאִין דְּחָכְמְתָא, עֲלַיְיהוּ כְּתִיב, (תהילים כ״ה:י״ד) סוֹד יְיָ לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר (ישעיהו כ״ה:א׳) יְיָ אֱלהַי אַתָּה אֲרוֹמִמְךָ אוֹדֶה שִׁמְךָ כִּי עָשִׂיתָ פֶּלֶא עֵצוֹת מֵרָחוֹק אֱמוּנָה אֹמֶן. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכָּלָא בִּיקְרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּלְשַׁבְּחָא לִיקָרֵיהּ. בְּגִין דְּכָל מַאן דְּיָדַע לְשַׁבְּחָא לְמָארֵיהּ כְּדְקָא יָאוֹת, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ רְעוּתֵיהּ. וְלָא עוֹד אֶלָּא דְאַסְגֵּי בִּרְכָאן לְעֵילָא וְתַתָּא.</p>\n<p>וְעַל דָּא מַאן דְּיָדַע לְשַׁבְּחָא לֵיהּ לְמָארֵיהּ וּלְיַחֲדָא שְׁמֵיהּ, חָבִיב הוּא לְעֵילָא וְחָמִיד לְתַתָּא וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּבֵּחַ בֵּיהּ (נ\"א ביקריה), וְעֲלֵיהּ כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר:</p>"],[9520011174,"<p>וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כֶּרֶם. רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי. חַד אָמַר מִגַּן עֵדֶן (אתרכבת) אִתְתַּרְכַת וּנְצִיב לָהּ הָכָא. וְחַד אָמַר בְּאַרְעָא הֲוַת וְעָקַר לָהּ וְשָׁתַל לָהּ, וּבְהַהוּא יוֹמָא עַבְדַת אִיבִּין וְנִיצַת לַבְלְבִין וְעֲנָבִים וְהֲוָה סָחִיט לָהּ וְשָׁתֵי מִן חַמְרָא וְרָוֵי.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר רָזָא דְּחָכְמְתָא אִיהוּ הָכָא בְּהַאי קְרָא. כַּד בָּעָא נֹחַ לְמִבְדַּק בְּהַהוּא חוֹבָא דְּבָדַק אָדָם הָרִאשׁוֹן. לָאו לְאִתְדַּבְּקָא בֵּיהּ, אֶלָּא לְמִנְדַע וּלְאַתְקָנָא עָלְמָא וְלָא יָכִיל. סָחַט עֲנָבִים לְמִבְדַּק בְּהַהוּא כֶּרֶם. כֵּיוָן דְּמָטָא לְהַאי, (ד\"א כדין) וַיִּשְׁכָּר וַיִּתְגָּל. וְלָא הֲוָה לֵיהּ חֵילָא לְמֵיקַם. וּבְגִין כָּךְ וַיִּתְגָּל גַּלֵּי פִּרְצָה דְעָלְמָא דְּהֲוָה סָתִים. בְּתוֹךְ אָהֳלֹה כְּתִיב בְּה\"א. וְעַל דָּא כְּתִיב וְאַל תִּקְרַב אֶל פֶּתַח בֵּיתָהּ. בְּתוֹךְ <Nonei></i>אָהֳלָהּ דְּהַהוּא כָּרֶם.</p>\n<p>כְּגַוְונָא דָא בְּנֵי אַהֲרֹן דְּתָנִינָן שְׁתוּיֵי יַיִן הֲווּ. וְכִי מַאן יָהִיב לוֹן חַמְרָא בְּהַהוּא אֲתַר לְמִשְׁתֵּי. אִי סַלְקָא דַעְתָּךְ דְּאִנוּן חֲצִיפִין הֲווּ דְּרָווֹ חַמְרָא. לָאו הָכִי, אֶלָּא וַדַּאי מֵהַהוּא חַמְרָא רָווֹ דִּכְתִיב, (ויקרא י׳:א׳) וַיַּקְרִיבוּ לִפְנֵי יְיָ אֵשׁ זָרָה. כְּתִיב הָכָא אֵשׁ זָרָה וּכְתִיב הָתָם (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה וְכֹלָּא חַד מִלָּה.</p>\n<p>וְכֵן כְּגַוְונָא דָא וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל. וְעַל דָּא אִתְעַר חָם אֲבִי כְנָעַן כְּמָה דְּאִתְּמָר וְאִתְיְהִיב אֲתַר לִכְנַעַן לְשַׁלְטָאָה, וּמַאי דְּהֲוָה הָדֵין צַדִּיק בְּרָזָא דִּבְרִית סֵרְסוֹ. וְתַנְיָא דְּאַעֲבַר מִינֵיהּ הַהוּא קִיּוּמָא.</p>\n<p>וּבְגִין כָּךְ אָמַר אָרוּר דְּהָא לְוָוטִין אִתְעָרוּ בְּקַדְמִיתָא עַל יְדֵיהּ בְּעָלְמָא. (ועל דא ויאמר ארור כנען דהא לווטין ייתון על עלמא כקדמיתא). עֶבֶד עֲבָדִים יִהְיֶה כְּמָא דְאַתְּ אָמֵר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו'. כֹּלָּא יִתְתַּקַּן לְזִמְנָא דְּאָתֵי וְהוּא לָא יִתְתַּקַּן. וְכֹלָּא יִפְקוּן לְחֵירוּ וְהוּא לָא יִפּוּק. וְרָזָא אִיהוּ לְאִנוּן דְּיָדְעֵי אָרְחוֹי וּשְׁבִילֵי דְאוֹרַיְיתָא.</p>"],[9520011175,"<p>פָּתַח וְאָמַר (תהילים נ״א:ה׳) כִּי פְשָׁעַי אֲנִי אֵדָע וְחַטָּאתִי נֶגְדִּי תָמִיד. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא מֵחוֹבַיְיהוּ מִקַּמֵי קוּדְשָׁא בְּרִיךְ הוּא. דְּהָא לְבָתַר דְּחָטָא בַּר נָשׁ רָשִׁים הוּא חוֹבֵיהּ לְעֵילָא וְלָא אִתְמְחַק בַּר בְּתוּקְפָא דִּתְיוּבְתָּא סַגְיָא. כְּמָא דְאַתְּ אָמֵר, (ירמיהו ב׳:כ״ב) כִּי אִם תְּכַבְּסִי בַּנֶּתֶר וְתַרְבִּי לָךְ בּוֹרִית נִכְתַּם עֲוֹנֵךְ לְפָנָי.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דְּחָב בַר נָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא זִמְנָא חָדָא עָבִיד רְשִׁימוּ. וְכַד חָב בֵּיהּ זִמְנָא תִּנְיָינָא אִתְתַּקַּף הַהוּא רְשִׁימוּ יַתִּיר. חָב בֵּיהּ זִמְנָא תְּלִיתָאָה אִתְפַּשַּׁט הַהוּא כִּתְמָא מִסִּטְרָא דָא לְסִטְרָא דָא, כְּדֵין כְּתִיב נִכְתַּם עֲוֹנֵךְ לְפָנָי.</p>\n<p>תָּא חֲזֵי, דָּוִד מַלְכָּא כֵּיוָן דְּחָב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל עִסְקָא דְּבַת שֶׁבַע, חָשִׁיב דְּהַהוּא חוֹבָא אִתְרְשִׁים עֲלֵיהּ לְעָלְמִין. מַה כְּתִיב, (שמואל ב י״ב:י״ג) גַּם יְיָ הֶעֱבִיר חַטָּאתְךָ לא תָמוּת. (קודשא בריך הוא) אַעֲבַר הַהוּא רְשִׁימוּ מִקַּמֵּיהּ.</p>\n<p>אָמַר לֵיהּ רַבִּי אַבָּא וְהָא תָּנִינָן דְּבַת שֶׁבַע דִּילֵיהּ דְּדָוִד מַלְכָּא הֲוַת מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, אַמַּאי יָהֲבָהּ קוּדְשָׁא בְּרִיךְ הוּא לְאוּרִיָה הַחִתִּי מִן קַדְמַת דְּנָא.</p>\n<p>אָמַר לֵיהּ הָכִי אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא אַף עַל גַּב דְּאִתְּתָא אַזְמִינָא לֵיהּ לְבַר נָשׁ לְמֶהֱוֵי דִילֵיהּ, אַקְדִים אַחֲרָא וּנְסִיב לָהּ עַד דְּמָטָא זִמְנֵיהּ דְּהַאי. כֵּיוָן דְּמָטָא זִמְנֵיהּ, אִתְדַּחְיָיא הַאי דְּנָסִיב לָהּ מִקַּמֵּי הַאי אָחֳרָא דְּאָתֵי לְבָתַר וְאִסְתַּלַּק מֵעָלְמָא. וְקָשֵׁי קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לֵיהּ מֵעָלְמָא עַד לָא מָטֵי זִמְנֵיהּ מִקַּמֵּי הַאי אָחֳרָא.</p>\n<p>וְרָזָא דְּבַת שֶׁבַע דְּאִתְיְיהִיבַת לְאוּרִיָה הַחִתִּי (כדאמרן) בְּקַדְמִיתָא, פּוּק וְדוּק וְתִשְׁכַּח. אַמַּאי אִתְיְהִיבַת אַרְעָא קַדִּישָׁא לִכְנַעַן עַד לָא יֵיתוּן יִשְׂרָאֵל. וְתִשְׁכַּח מִלָּה דָא. וְכֹלָּא רָזָא חָדָא אִיהוּ וּמִלָּה חָדָא.</p>\n<p>תָּא חֲזֵי, דָּוִד אַף עַל גַּב דְּאוֹדֵי עַל חוֹבֵיהּ וְתָב בִּתְיוּבְתָּא, לָא אַעֲדֵי לִבֵּיהּ וּרְעוּתֵיהּ מֵאִנוּן חוֹבִין דְּחָב, וּמֵהַהוּא חוֹבָא דְּבַת שֶׁבַע, בְּגִין דְּדָחִיל עֲלַיְיהוּ תָּדִיר דִּילְמָא גָּרִים חַד מִנַּיְיהוּ וִיקַטְרֵג עֲלֵיהּ בְּשַׁעֲתָא דְסַכָּנָה. וּבְגִין כָּךְ לָא אַנְשֵׁי לוֹן מִינֵיהּ וּמֵרְעוּתֵיהּ.</p>\n<p>דָבָר אֲחַר כִּי פְשָׁעַי אֲנִי אֵדָע כֻּלְהוּ דַּרְגִּין דְּתַלְיָין בְּהוּ חוֹבֵי בְּנֵי נָשָׁא אֲנִי אֵדָע. וְחַטָּאתִי נֶגְדִּי תָמִיד דָּא פְּגִימוּ דְסִיהֲרָא דְּלָא נָפְקָא מִסְאוּבְתָּא עַד דְּאָתָא שְׁלֹמֹה וְאִתְנְהִירַת בְּאַשְׁלָמוּתָא. וּכְדֵין אִתְבַּסָּם עָלְמָא וִיתִיבוּ יִשְׂרָאֵל לְרָחֲצָן דִּכְתִיב, (מלכים א ה׳:ה׳) וַיֵּשֶׁב יְהוּדָה וְיִשְׂרָאֵל לָבֶטַח אִישׁ תַּחַת גַּפְנוֹ וְתַחַת תְאֵנָתוֹ. וְעִם כָּל דָּא וְחַטָּאתִי נֶגְדִּי תָמִיד. וְלָא אִתְפְּסָק מֵעָלְמָא. עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא לְזִמְנָא דְּאָתֵי כְּמָה דְּאִתְּמָר (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ:</p>"],[9520011176,"<p>הוּא הָיָה גִּבּוֹר צַיִּד לִפְנִי יְיָ עַל כֵּן יֵאָמַר כְּנִמְרוֹד גִּבּוֹר צַיִד לִפְנֵי יְיָ. תָּא חֲזֵי, הוּא הֲוָה גְּבַר תַּקִּיף. לְבוּשׁוֹי דְּאָדָם הָרִאשׁוֹן הֲוָה לָבִישׁ וְהֲוָה יָדַע לְמֵיצַד צֵידָה דִּבְרִיָּיתָא בְּהוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר נִמְרוֹד הֲוָה מְפַתֵּי לִבְרִיָּיתָא לְמֵיהַךְ בָּתַר פּוּלְחַן דְּעַבוֹדָה זָרָה וְהֲוָה שַׁלִּיט בְּאִנוּן לְבוּשִׁין וְנָצַח בְּנֵי עָלְמָא וְהֲוָה אָמַר דְּאִיהוּ שַׁלִּיטָא בְּעָלְמָא וּפָלְחִין לֵיהּ בְּנִי נָשָׁא. וְאַמַּאי אִקְרֵי שְׁמֵיהּ נִמְרוֹד דְּמָרַד בְּמַלְכָּא עִלָּאָה דִּלְעֵילָא דְּמָרַד בְּעִלָּאֵי וּמָרַד בְּתַתָּאֵי.</p>\n<p>בְּאִנוּן <Nonei></i>לְבוּשִׁין שַׁלִּיט עַל כָּל (ד\"א שאר) בְּנִי עָלְמָא וּמָלַךְ בְּהוּ וּמָרַד בְּמָארֵיהּ וְאָמַר דְּאִיהוּ שַׁלִּיטָא דְעָלְמָא וְהֲוָה מְפַתֵּי לִבְרִיָּיתָא אֲבַתְרֵיהּ עַד דְּמָשַׁךְ בְּנֵי נָשָׁא לְמֵיפַק מִבָּתַר פּוּלְחָנָא דְּמָארֵי עָלְמָא. אָמַר רַבִּי שִׁמְעוֹן בְּאִילֵין לְבוּשִׁין יָדְעֵי בְּהוּ חַבְרַיָיא רָזָא עִלָּאָה:</p>"],[9520011177,"<p>מַתְנִיתִין. וַיְהִי כָל הָאָרֶץ שָׂפָה אַחַת וּדְבָרִים אֲחָדִים. רַבִּי שִׁמְעוֹן פָּתַח (מלכים א ו׳:ז׳) וְהַבַּיִת בְּהִבָּנוֹתוֹ אֶבֶן שְׁלֵמָה מַסַּע נִבְנָה וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל לא נִשְׁמַע בַּבַּיִת בְּהִבָּנוֹתוֹ. (האי קרא אית לאסתכלא ביה), וְהַבַּיִת בְּהִבָּנוֹתוֹ. וְכִי לָא הֲוָה בָּנִי לֵיהּ שְׁלמֹה וְכֻלְהוּ אוּמָנִין דְּהֲווּ תַּמָּן, מַהוּ בְּהִבָּנוֹתוֹ.</p>\n<p>אֶלָּא כָּךְ הוּא כְּמָה דִכְתִיב, (שמות כ״ה:ל״א) מִקְשָׁה תֵּיעָשֶׂה הַמְנוֹרָה. אִם הִיא מִקְשָׁה מַהוּ תֵּיעָשֶׂה. אֶלָּא וַדַּאי כֹּלָּא בְּאָת וְנִיסָּא אִתְעֲבִיד אִיהוּ מִגַּרְמֵיהּ. כֵּיוָן דְּשָׁרָאן לְמֶעְבַּד עֲבִידְתָּא אוֹלִיף לְאוּמָנִין לְמֶעְבַּד בָּהּ מַה דְּלֹא הֲווּ יָדְעִין מִקַּדְמַת דְּנָא.</p>\n<p>מַאי טַעְמָא בְּגִין דְּבִרְכְתָא דְּקוּדְשָׁא בְּרִיךְ הוּא שְׁרָא עַל יְדַיְיהוּ, וְעַל דָּא כְּתִיב בְּהִבָּנוֹתוֹ אִיהוּ אִתְבְּנִי מִגַּרְמֵיהּ, דְּהוּא אוּלְפָא אוּלְפַן לְאוּמָנִין הֵיאךְ שָׁרָאן לְמֶעְבַּד, וְלָא אִסְתַּלַּק מֵעֵינַיְיהוּ רְשִׁימוּ דְּהַהוּא עֲבִידְתָּא מַמָּשׁ וּמִסְתַּכְּלָאן בֵּיהּ וְעָבְדֵי עַד דְּאִתְבְּנֵי כָּל בֵּיתָא.</p>\n<p>אֶבֶן שְׁלֵמָה מַסַּע נִבְנֶה. שְׁלֵמָה כְּתִיב חָסֵר יו\"ד אֶבֶן שְׁלֵמָה וַדַּאי. מַסַּע דְּאִתְנְטִיל וְאַתְיָיא וְשָׁרְיָיא עֲלַיְיהוּ וְאִתְעֲבִיד עֲבִידְתָּא (מסע דאתנטיל ועביד עבידתא), מַסַּע דְּאַנְטִיל יָדָן לְמֶעְבַּד דְּלָא מִדַּעְתַּיְיהוּ. כְּתִיב הָכָא מַסַּע וּכְתִיב הָתָם (במדבר י׳:ב׳) וּלְמַסַּע אֶת הַמַּחֲנוֹת.</p>\n<p>וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל לֹא נִשְׁמַע. בְּגִין דְּשָׁמִיר בָּזַע כֹּלָּא וְלָא אִשְׁתְּמַע מִלָּה, דְּלָא אִצְטְרִיכוּ לִשְׁאָר מָאנִין לְמֶעְבַּד. וְכֹלָּא בְּאָת וְנִיסָּא הֲוָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן כַּמָּה חֲבִיבִין אִנוּן מִלֵּי דְאוֹרַיְיתָא. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִתְעַסַּק בְּהוּ וְיָדַע לְמֵיהַךְ (ביה) בְּאֹרַח קְשׁוֹט. וְהַבַּיִת בְּהִבָּנוֹתוֹ. כַּד סָלְקָא בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד יְקָרָא לִיקָרֵיהּ, סָלְקָא מִגּוֹ מַחֲשָׁבָה רְעוּתָא לְאִתְפַּשְׁטָא, וְאִתְפַּשְׁטַת מֵאֲתַר דְּאִיהִי מַחֲשָׁבָה סְתִימָא דְּלָא אִתְיְידַע.</p>\n<p>עַד דְּאִתְפַּשְׁטַת וְשַׁרְיָיא לְבֵי גָרוֹן אֲתַר דְּאִיהוּ נְבִיעַ תָּדִיר בְּרָזָא דְּאִיהוּ רוּחַ חַיִּים. וּכְדֵין כַּד אִתְפַּשְׁטַת הַהִיא מַחֲשָׁבָה וְשָׁרְיָא בְּאֲתַר דָּא, אִקְרֵי הַהִיא מַחֲשָׁבָה אֱלֹהִים חַיִּים. דִּכְתִיב, (ירמיהו י׳:י׳) הוּא אֱלהִים חַיִּים.</p>\n<p>עוֹד בָּעָא לְאִתְפַּשְׁטָא וּלְאִתְגַּלְּיָא מִתַּמָּן נָפְקוּ אֶשָׁ\"א וְרוּחָ\"א וּמַיָ\"א כְּלִילָן כְּחֲדָא, וְנָפַק יַעֲקֹב גְּבַר שְׁלִים וְאִיהוּ קוֹל חַד דְּנָפִיק וְאִשְׁתְּמַע. מֵהָכָא מַחֲשָׁבָה דְּהֲוָה סְתִימָא בַּחֲשַׁאי אִשְׁתְּמַע לְאִתְגַּלְיָא.</p>\n<p>עוֹד אִתְפַּשְׁטַת הַאי מַחֲשָׁבָה לְאִתְגַּלְיָא. וּבָטַשׁ הַאי קוֹל וְאַקִּישׁ בְּשִׂפְוָון, וּכְדֵין נַפְקָא דִּבּוּר, דְּאַשְׁלִים כֹּלָּא, וְגָלֵי כֹּלָּא. אִשְׁתְּמַע דְּכֹלָּא אִיהוּ הַהִיא מַחֲשָׁבָה סְתִימָא דְּהֲוַת לְגוֹ וְכֹלָּא חַד.</p>\n<p>כֵּיוָן דְּמָטָא אִתְפַּשְׁטוּתָא דָא וְאִתְעֲבִיד דִּבּוּר בִּתְקִיפָא דְּהַהוּא קָלָא, כְּדֵין וְהַבַּיִת בְּהִבָּנוֹתוֹ. כַּאֲשֶׁר נִבְנָה לא כְּתִיב אֶלָּא בְּהִבָּנוֹתוֹ בְּכָל זִמְנָא וְזִמְנָא. אֶבֶן שְׁלֵמָה כְּמָה דְּאִתְּמָר. וּכְתִיב, (שיר השירים ג׳:י״א) בָּעֲטָרָה שֶׁעִטְרָה לוֹ אִמּוֹ.</p>\n<p>מַסַּע דְּנַפְקָא מִלְּגוֹ וְשַׁרְיָא וְנָטִיל לְבַר, נַפְקָא מִלְּעֵילָא וְשַׁרְיָא וְנָטִיל לְתַתָּא. וּמַקָּבוֹת וְהַגַּרְזֶן כָּל כְּלֵי בַּרְזֶל. אִלֵּין שְׁאָר דַּרְגִּין תַּתָּאִין דְּכֻלְהוּ תַּלְיָין בֵּיהּ וְלָא אִשְׁתְּמָעוּ וְלָא אִתְקַבְּלָן לְגוֹ כַּד אִיהִי סַלְקָא לְאִתְאַחֲדָא לְעֵילָא וּלְיָנְקָא מִתַּמָּן. וְדָא הוּא בְּהִבָּנוֹתוֹ.</p>\n<p>וּכְדֵין כַּד אִיהִי יָנְקָא, כֻּלְהוּ קָיְימֵי בְּחֶדְוָותָא וְיָנְקִין וְאִתְמַלְיָין בִּרְכָאן. וּכְדֵין קָיְימִין עָלְמִין כֻּלְהוּ בְּרָזָא חָדָא בְּיִחוּדָא חַד, וְלָא הֲוֵי בְּהוּ בְּכֻלְהוּ עָלְמִין פִּירוּדָא. לְבָתַר דְּנָטְלֵי חוּלַקְהוֹן כָּל חַד וְחַד כֻּלְהוּ מִתְפַּשְׁטָן וּמִתְפָּרְשָׁן לְסִטְרַיְיהוּ לְמָה דְאִתְמַנָּן.</p>"],[9520011178,"<p>תָּא חֲזֵי, וַיְהִי כָל הָאָרֶץ שָׂפָה אַחַת וְגו' <Nonei></i>לְבָתַר מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מֵהַהוּא קַדְמָאָה דְעָלְמָא. וַיִּמְצְאוּ בִּקְעָה בְּאֶרֶץ שִׁנְעָר. דְּהָא מִתַּמָּן מִתְפָּרְשָׁן לְכָל אִנוּן סִטְרִין, וְאִיהוּ רִישׁ מַלְכוּ לְאִתְבְּדָרָא.</p>\n<p>וְאִי תֵימָא הָא כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד. וַדַּאי הָכִי הוּא דְּכֵיוָן דְּנָטְלֵי מִתַּמָּן הֲוֵי פִּירוּדָא, וְכַד אִנוּן כְּנִישִׁין תַּמָּן לְיַנְקָאָה לָא הֲוִי פִּירוּדָא. וְכַד נָטְלִין הֲוֵי פִּירוּדָא, דִּכְתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם וַיִּמְצְאוּ בִּקְעָה כְּמָה דְּאִתְּמָר.</p>\n<p>וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים דְּהָא כְּדֵין עָלְמָא בִּיסוֹדָא וְעִקָּרָא וְשָׁרְשָׁא חָדָא וּמְהֵימְנוּתָא חָדָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם מִקַּדְמָאָה עִקָּרָא דְּעָלְמָא מְהֵימְנוּתָא דְּכֹלָּא. וַיִּמְצְאוּ בִּקְעָה. מְצִיאָה אַשְׁכָּחוּ וְנָפְקוּ בָּהּ מִתְּחוֹת מְהֵימְנוּתָא עִלָּאָה (וימצאו).</p>\n<p>תָּא חֲזֵי, נִמְרוֹד מַה כְּתִיב בֵּיהּ וַתְּהִי רֵאשִׁית מַמְלַכְתּוֹ בָּבֶל. דְּהָא מִתַּמָּן נְטַל לְאִתְאַחֲדָא בִּרְשׁוּ אָחֳרָא. וְהָכָא וַיִּמְצְאוּ בִּקְעָה בְּאֶרֶץ שִׁנְעָר מִתַּמָּן נְטָלוּ בְּלִבַּיְיהוּ לְאֲפָקָא מֵרְשׁוּתָא עִלָּאָה לִרְשׁוּ אָחֳרָא:</p>\n<p>וַיֹּאמְרוּ הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם וְנַעֲשֶׂה לָנוּ שֵׁם. רַבִּי חִיָּיא פָּתַח (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגו'. וְכִי אִית יָם נִגְרָשׁ. אִין, דְּכַד יַמָּא נַפְקָא מִתִּקּוּנֵיהּ וְאָזִיל (בלא הבלא) בְּלָא חַבָּלָא, כְּדֵין נִגְרַשׁ וְאִתְתְּרַךְ מֵאַתְרֵיהּ, כְּמַאן דְּרָוֵי חַמְרָא וְלָא יָתִיב עַל בּוּרְיֵיהּ וְסָלְקָא וְנָחֲתָא. מַאי טַעְמָא בְּגִין כִּי הַשְׁקֵט לא יוּכַל, וְיִגְרְשׁוּ מֵימָיו רֶפֶשׁ וְטִיט. דְּמַפְקוּ מֵימוֹי כָּל הַהוּא טִינָא דְיַמָּא וְכָל טִנּוּפָא לְשִׂפְוָותֵיהּ.</p>\n<p>כְּגַוְונָא דָא אִנוּן רְשָׁעִים דְּנַפְקָא מֵאָרְחָא דְּתָקְנָא וְאָזְלֵי כְּרָוִי חַמְרָא בְּלָא תִּקּוּנָא, דְּנָפְקֵי מֵאוֹרַח מֵישָׁר לְאוֹרַח עָקִים. מַאי טַעְמָא, בְּגִין כִּי הַשְׁקֵט לא יוּכָל. דְּהָא עֲקִימוּ דְּאָרְחַיְיהוּ גָּרִים לוֹן לְמֵהַךְ בְּלָא תִקּוּנָא וּבְלָא שְׁכִיכוּ.</p>\n<p>וְלָא עוֹד אֶלָּא דְּכָל רוּגְזָא דִידְהוּ בְּשַׁעֲתָא דְּאָמְרִי מִלָּה מִפּוּמַיְיהוּ הַהוּא מִלָּה רֶפֶשׁ וְטִיט כֻּלְהוּ מַפְקֵי טִנּוּפָא וְגִיעוּלָא מִפּוּמַיְיהוּ לְבַר עַד דְּמִסְתָּאֲבֵי <Nonei></i>וּמְסָאֲבֵי לוֹן.</p>\n<p>תָּא חֲזֵי, וַיֹּאמְרוּ הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם. לֵית הָבָה אֶלָּא הַזְמָנָה בְּעָלְמָא. נִבְנֶה לָנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַּשָּׁמַיִם. כֻּלְהוּ בְּעֵיטָא בִּישָׁא אָתוּ לְסַרְבָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. בִּשְׁטוּתָא אָתוּ (איהו) בְּטִפְּשׁוּ דְּלִבָּא.</p>\n<p>אָמַר רַבִּי אַבָּא שְׁטוּתָא נְסִיבוּ בְּלִבַּיְיהוּ. אֲבָל בְּחָכְמָה דִּרְשִׁיעוּ אָתוּ בְּגִין לְנָפְקָא מֵרְשׁוּ עִלָּאָה לִרְשׁוּ אָחֳרָא וּלְאַחְלָפָא יְקָרֵיהּ לִיקָרָא נוּכְרָאָה. וּבְכֹלָּא אִית רָזָא דְּחָכְמְתָא עִלָּאָה.</p>\n<p>הָבָה נִבְנָה לָנוּ עִיר וּמִגְדָּל. תָּא חֲזֵי, כַּד מָטוּ לְהַאי בִּקְעָה דְּאִיהוּ רְשׁוּ נוּכְרָאָה וְאִתְגְּלִי לְהוּ אֲתַר דְּשָׁלְטְנוּתָא דָּא תְּקִיעַ בְּגוֹ נוּנֵי יַמָּא. אָמְרוּ הָא אֲתַר לְמֵיתַב וּלְאִתְתַּקְפָא לִבָּא לְאִתְהַנָּאָה בֵּיהּ תַּתָּאֵי. מִיָּד הָבָה נִבְנָה לָנוּ עִיר. נַתְקִין בְּאֲתַר דָּא עִיר וּמִגְדָּל.</p>\n<p>וְנַעֲשֶׂה לָנוּ שֵׁם. אֲתַר דָּא (יהיב לון) יְהֵא לָן לְדַחֲלָא וְלָא אָחֳרָא, וְנִבְנֶה לְאֲתַר דָּא עִיר וּמִגְדָּל. לָמָּה לָן לְסָלְקָא לְעֵילָא דְּלָא נֵיכוֹל לְאִתְהַנָּאָה מִנָּהּ. הָא הָכָא אֲתַר מְתַקְנָא. וְנַעֲשֶׂה לָנוּ שֵׁם דַּחֲלָא לְמִפְלַח תַּמָּן. פֶּן נָפוּץ לְדַרְגִּין אָחֳרָנִין וְנִתְבַּדַּר לְסִטְרֵי עָלְמָא:</p>\n<p><Noneb>סִתְרֵי תּוֹרָה</b> <Nonei></i>קוּמְטוּרָא דְּהֻרְמָנָא מְמַלְּלָן בְּלָשׁוֹן הַקֹּדֶשׁ דְּמַלְאֲכֵי הַשָׁרֵתּ אִשְׁתְּמוֹדְעָן בֵּיהּ וְלָא הֲווּ מְמַלְלִין בְּלִישָׁן אָחֳרָא. בְּגִין כָּךָ כְּתִּיב וְעַתָּה לֹא יִבָּצֵּר מֵהֶם וְגו'. דְּאִלְמָלֵי מִשְׁתָּעָאן בְּלִישָׁן אָחֳרָא דְּמַלְאֲכֵי עִלָּאֵי לָא הֲווּ אִשְׁתְּמוֹדְעָן בֵּיהּ, גָּרַע חֲשִׁיבוּ דְּאִנוּן חָשְׁבִין לְמֶעְבַּד. בְּגִין דְּעוֹבָדָא דְּשֵׁדִין לָאו אִיהוּ אֶלָּא בְּרִגְעָא חָדָא לְחֵזוּ בְּנֵי אֱנָשָׁא ולא יַתִּיר.</p>\n<p>וּדְבָרִים אֲחָדִים. דְּהֲווּ יָדְעִין דַּרְגִּין עִלָּאִין כָּל חַד וְחַד על בּוּרְיֵיהּ ולא אִתְּחְלַף לְהוּ דַּרְגָּא וּבְגִין כָּךָ כְּתִּיב וּדְבָרִים אֲחָדִים. וּבְגִין כָּךָ אִתְּיָעֲטוּ בְּעִיטָא בִּישָׁא עִיטָא דְּחָכְמְתָּא דִּכְתִּיב הָבָה נִבְנֶה לָנוּ עִיר וּמִגְדָּל.</p>\n<p>כּלָּא בְּרָזָא דְּחָכְמְתָּא הוּא, וּבָעוּ לְאִתַּקְפָּא בְּאַרְעָא סִטְרָא אָחֳרָא וּלְמִפְּלַח פּוּלְחָנָא דִּילֵיהּ. בְּגִין דְּהֲווּ יָדְעִין דְּהָא כָּל דִּינִין בִּישִׁין מִתַּמָּן נַחֲתִּין לְעָלְמִין. וּבָעְיָין לִדְחוּיֵי דַּרְגָּא דְּקֻדְּשָׁא.</p>\n<p>עִי\"ר וּמִגְדָּ\"ל, דָּא חָכְמְתָּא עִלָּאָה. (ד\"א דהא) הֲווּ יָדְעֵי דּשמָא קַדִּישָׁא לָא אִתְּתַּקַּף בְּאַרְעָא, אֶלָּא בְּעִיר וּמִגְדָּל. עִי\"ר דִּכְתִּיב, (שמואל ב ה׳:ז׳) (מ\"א ח) עִיר דָּוד הִיא צִּיּוֹן וְגו'. מִגְדָּ\"ל דִּכְתִּיב (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַּוָּארֵךָ. וּבְחָכְמְתָּא עֲבָדוּ לְמֶהֱוֵי שָׁלְטָנָא דְּסִטְרָא אָחֳרָא בִּאַרְעָא דְּדַחְיָיא (ד\"א לדחייא) ֹ אֲדוֹן כָּל הָאָרֶץ מֵאַתְּרֵיהּ. וּלְמֶהֱוִי דִיוּרָא לְסִטְרָא אָחֳרָא בְּאַרְעָא.</p>\n<p>וְנַעֲשֶׂה לָנוּ שֵׁם. כְּמָה דַּאֲחִידָא (ד\"א דאחרא) אִיהוּ שֵׁם לְעֵילָא, נַתְּקִיף לָהּ בֵּיננא לְמֶהֱוֵי שֵׁם בְּאַרְעָא. פֶּן נָפּוֹץ. יְדִיעָה הֲווּ יָדְעִין דְּיִתְּבַּדְּרוּן מֵעַל אַפֵּי אַרְעָא. וּבְגִין כָּךָ הֲווּ מִתְּיַחֲדִין לְמֶעְבַּד עֲבִידְתָּא דָא בְּחָכְמָה.</p>\n<p>סִטְרָא אָחֳרָא אִיהוּ דְּכַר וְנוּקְבָא תּוּקְפָּא דְזוּהֲמָא דְדִינָא קַשְׁיָא. וּכְמָה דְאָדָם חָב (ביה) בְּהוּ וְאִתְּקָפּוּ בְּגִינֵיהּ על עָלְמָא. אוּף הָכִי אִנּוּן עָבְדִין דְּאִתְּתַּקַּף יַתִּיר. דִּכְתִּיב אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. בְּנוֹי דְּאָדָם קַדְמָאָה דְּאַיְיתֵּי וְאַשְׁלִיט סִטְרָא אָחֳרָא עַל עָלְמָא סִטְרָא בִישָׁא. כְּמָה דְסִטְרָא דִקְדוּשָׁה לָאו שָׁלְטָנֵיהּ בְּהַאי עָלְמָא אֶלָּא בְּעִיר וּמִגְדָּל. אוּף הָכִי חֲשִׁיבֵי אִנּוּן לְמִבְנֵי עִיר וּמִגְדָּל לְמִשְׁלַט הַאי סְטַר בִּישָׁא בְּעָלְמָא:</p>\n<p>וִיִּרֶד יְיָ לִרְאוֹתּ. <Nonei></i>נָחַתּ הַאי שְׁמָא דְּקַדִּישָׁא לְמֶחֱזִי (על) עוֹבָדֵיהוֹן דְּבִנְיָינא דְּבָנוּ. וְאִנּוּן הֲווּ מְמַלְּלָן בִּלְשׁוֹן קֹדֶשׁ לְגַבֵּי כָּל אִנּוּן דַּרְגִּין קַדִּישִׁין וְהֲווּ מַצְּלִיחִין. כֵּיוָן דְּנַחֲתַּתּ קְדֻשָׁה אִתְּבַּלְבְּלוּ כָּל אִנּוּן דַּרְגִּין. עִלָּאִין נָחֲתּוּ וְתַּתָּאִין סְלִיקוּ. וְלָא הֲווּ קָיְימִין בְּאֹרַח מֵישָׁר כְּמָה דְּהֲווּ. וּלְבָתַּר בִּלְבֵּל לִישַׁנְהוֹן בְּע' לִישָׁן וְאִתְּבַּדָּרוּ לְכָל סִטְרֵי עָלְמָא.</p>\n<p>חַד מְמַנָּא הוּא בִּרְקִיעָא וּבֵיהּ קָיְימִין כָּל (ד\"א ל\"ג אנון) מַפְּתְּחָן דְּעוֹבָדֵי עָלְמָא. ואִיהוּ קָיְימָא זַמִּין בְּשַׁעֲתֵּי וְרִגְעֵי דְיוֹמָא. וְאִנּוּן הֲווּ יָדְעִין בְּרָזָא דְחָכְמְתָּא גִּנְזָא דְּהַאי מְמַנָּא. וְהֲווּ פָּתְּחֵי וְסָגְרֵי וּמַצְּלְחֵי בְּעוֹבָדֵיהוֹן בְּמֵימְרָא דְפּוּמְהוֹן. כֵּיוָן (דאסתכלא) דְּאִתְּבַּלְבָּל מֵימְרָא דִלְהוֹן, כֹּלָּא אִתְּמְנָע מִנַּיְיהוּ.</p>\n<p>וַאֲתַּר מְתֻּקָּן אַשְׁכָּחוּ בְּהַהוּא בִּקְעָה. סִטְרָא דְּסִטְרִין: וַיִּמְצְּאוּ בִּקְעָה. אֲתַּר מְתֻּקָּן לְהַאי (ד\"א ל\"ג ההוא) סִטְרָא בִּישָׁא דְּבָעוּ אִנּוּן לְאַתְּקָפָּא וְאִתְּמְנָעוּ. תּוּקְפָּא (דיליה) דְּהַהוּא סִטְרָא הֲוָה תַּלְיָא לְאִתְּפְּרָעָא בְּהַהִיא בִּקְעָה עַד דְּנָטְלָא תַּמָּן חֵילִין וּמַשִׁירְיָין כְּגַוְונָא דְּאִנּוּן דְּבָנוּ קַרְתָּא וּמִגְדְּלָא וְאִתְּיְהִיבוּ (כלא) כֻּלְהוּ בִּידָהָא. וְאִתְּקַטָלוּ תַּמָּן</p>\n<p>אִנּוּן דּלא בָּעוּ לְמֵיפַּק בְּקֵ\"ץ הַיָּמִי\"ן. אִתְּבְּהִילוּ וְנָפְּלוּ בְּקֵץ הַיָּמִי\"ם. בְּהַהוּא אֲתַּר דְּאִתְּחַלַּשׁ תֻּקְפָּא בְּקַדְמִיתָּא בְּהַאי בִּקְעָה. ועל דָּא כְּתִּיב, (יחזקאל לו) וְהִיא מְלֵאָה עֲצָּמוֹתּ.</p>\n<p>וְאִתְּתַּקְפַּתּ בְּהַהוּא צּוּלְמָא דְאָקִים נְבוּכַדְנֶצַּר. וְאִתְּבַּר תּוּקְפָּא לְבָתַּר בְּאִנּוּן גַּרְמִין וּבְהַהוּא צּוּלְמָא. דְּאִנּוּן קַדְמָאֵי קָיְימוּ וקָמוּ עַל רַגְלֵיהוֹן. וְהַהוּא צּוּלְמָא אִתְּבָּר.</p>\n<p>וּכְדֵין יָדְעוּ כָּל עַמִּין דְּעָלְמָא דְּלֵיתּ אֱלוֹהַּ בַּר קוּדְשָׁא בְּרִיךָ הוּא בִּלְחוֹדוֹי. ותּוּ דְּאִתְּקַדַּשׁ שְׁמֵיהּ עַל יְדָא דְּחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה וְכלָּא בְּחַד יוֹמָא. וְעַל דָּא כְּתִּיב, (ישעיהו כ״ט:כ״ג) וְהִקְדִּישׁוּ אֶתּ קְדוֹשׁ יַעֲקֹב וגו', (עד כאן סתרי תורה)</p>\n<p>וַיֵּרֶד יְיָ לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל דָּא הוּא חַד מֵאִנּוּן עֶשֶׂר זִמְנִין דְּנָחֲתָא שְׁכִינְתָּא לְאַרְעָא. וְכִי מַה הוּא לִרְאוֹת וְלָא הֲוָה יָדַע מִקַּדְמַת דְּנָא. אֶלָּא לִרְאוֹת לְאַשְׁגָּחָא בְּדִינָא כְּמָא דְאַתְּ אָמֵר, (שמות ה׳:כ״א) יֵרֶא יְיָ עֲלֵיכֶם וְיִשְׁפֹּט.</p>\n<p>אֶת הָעִיר וְאֶת הַמִּגְדָּל. הָכָא אִית לְאִסְתַּכָּלָא. דְּהָא לָא כְּתִיב לִרְאוֹת אֶת בְּנֵי הָאָדָם. אֶלָּא לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל. אַמַּאי. אֶלָּא בְּשַׁעֲתָא דְּאַשְׁגַּח קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא, בְּקַדְמִיתָא יַשְׁגַּח בְּדַרְגָּא דִלְעֵילָא, וּלְבָתַר בְּדַרְגָּא דִלְתַתָּא. בְּקַדְמִיתָא בְּעִלָּאֵי וּלְבָתַר בְּתַתָּאֵי. וּבְגִין דְּהַאי מִלָּה מָטָא לְעֵילָא, אַשְׁגָּחוּתָא דִלְעֵילָא הֲוָה בֵּיהּ בְּקַדְמִיתָא דִּכְתִיב לִרְאוֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל.</p>\n<p>אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם. מַאי בְּנֵי הָאָדָם בְּנוֹי דְאָדָם קַדְמָאָה דְּמָרַד בְּמָרֵיהּ וְגָרַם מוֹתָא לְעָלְמָא. אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם בִּנְיָינָא וַדַּאי אָמְרוּ (גרמו) וּבָעוּ לְמִבְנִי לְעֵילָא.</p>"],[9520011179,"<p>רַבִּי שִׁמְעוֹן פָּתַח (ואמר) (יחזקאל מ״ו:א׳) כֹּה אָמַר יְיָ אֱלֹהִים שַׁעַר <Nonei></i>הֶחָצֵר הַפְּנִימִית הַפּוֹנֶה קָדִים יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. וְאִיהוּ רָזָא כְּמָה דְאִתְּמָר. יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה. אַמַּאי (וביום השבת יפתח וביום החדש יפתח וגו'. אמאי יהיה סגור כל אנון יומין דששת ימי המעשה).</p>\n<p>אֶלָּא אִלֵין יְמֵי חוֹל. דְּתַרְעָא דָא יִהְיֶה סָגוּר דְּלָא לְאִשְׁתַּמָּשָׁא חוֹל בְּקוּדְשָׁא. וּבְיוֹם הַשַּׁבָּת יִפָּתֵחַ וּבְיוֹם הַחֹדֶשׁ יִפָּתֵחַ. דְּהָא כְּדֵין שִׁמּוּשָׁא (דקודשא בריך הוא) דְּקוּדְשָׁא בְּקוּדְשָׁא. וּכְדֵין אִתְנְהִיר סִיהֲרָא לְאִתְחַבְּרָא בְּשִׁמְשָׁא.</p>\n<p>תָּא חֲזֵי, תַּרְעָא דָא לָא אִתְפַּתַּח בְּאִנּוּן שִׁתָּא יוֹמֵי דְּחוֹל. בְּגִין דְּהָא בְּאִנּוּן יוֹמֵי דְּחוֹל עָלְמָא תַּתָּאָה אִתְּזָן וְשָׁלְטִין כָּל אִנּוּן שִׁית יוֹמִין דְּחוֹל עַל עָלְמָא בַּר בְּאַרְעָא דְיִשְׂרָאֵל.</p>\n<p>וְאִנּוּן דְּשָׁלְטֵי לָא שָׁלְטֵי בְּאַרְעָא קַדִּישָׁא בְּגִין דְּהַשַּׁעַר הַזֶּה אִיהוּ סָגוּר. אֲבָל בְּיוֹם הַשַּׁבָּת וּבְיוֹם הַחֹדֶשׁ כֻּלְהוּ מִתְעַבְּרָן וְלָא שָׁלְטִין בְּגִין דְּהַשַּׁעַר הַזֶּה אִיהוּ פָּתוּחַ וְעָלְמָא אִיהוּ בְּחֶדְוָה וְאִתְּזָן מִתַּמָּן וְלָא אִתְיְיהִיב עָלְמָא לִרְשׁוּ אָחֳרָא.</p>\n<p>וְאִי תֵימָא דְּכָל אִנּוּן שִׁית יוֹמִין אִנּוּן שָׁלְטִין בִּלְחוֹדַיְיהוּ. תָּא חֲזֵי, הַפּוֹנֶה קָדִים. עַד לָא יְקוּמוּן לְשַׁלְטָאָה אִיהוּ אִסְתַּכַּל תָּדִיר בְּעָלְמָא. אֲבָל לָא אִתְפַּתַּח לְאִתְזְנָא עָלְמָא מִקּוּדְשָׁא בַּר בְּיוֹמָא דְשַׁבַּתָּא וּבְיוֹמָא דְחָדְשָׁא. וְכֻלְהוּ יוֹמִין כֻּלְהוּ אִתְדַּבְּקָן בְּיוֹמָא דְשַׁבַּתָּא וְאִתְזְנוּ מִתַּמָּן. דְּהָא (ד\"א ל\"ג כדין) בְּיוֹמָא דְּשַׁבַּתָּא כֻּלְהוּ תַּרְעִין פְּתִיחָן וְנַיְיחָא אִשְׁתְּכַח לְכֹלָּא לְעִלָּאֵי וְתַתָּאֵי. תָּא חֲזֵי, וַיֵּרֶד יְיָ לִרְאוֹת. נָחַת מִקּוּדְשָׁא לְחוֹל (ורדיד פרישא) לְאַשְׁגָּחָא בַּמֶּה דְּבָּנוּ וְקָיְימוּ קִיּוּמָא לְאַתְעָרָא עַל עָלְמָא לְדָחֲלָא לוֹן.</p>\n<p>רַבִּי יִצְחָק הֲוָה יָתִיב קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. אָמַר לֵיהּ מָה חָמוּ אִלֵּין דְּעֲבָדוּ שְׁטוּתָא דָא לְמָרְדָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וְכֻלְהוּ בְּעֵיטָא חָדָא אִתְקָיְימוּ בְּדָא. אָמַר לֵיהּ הָא אִתְּמָר דִּכְתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם אִתְנְטִילוּ מֵעֵילָא לְתַתָּא. אִתְנְטִילוּ מֵאַרְעָא דְיִשְׂרָאֵל וְנָחֲתוּ לְבָבָל. אָמְרוּ הָא הָכָא אֲתַר לְמִדְבַּק.</p>\n<p>וְנַעֲשֶׂה לָנוּ שֵׁם וְגו' וְיִתְדַּבַּק סִיּוּעָא דִלְתַתָּא בְּאֲתַר דָּא. בְּגִין דְּכַד דִּינָא אָתֵי לְאַשְׁרָאָה בְּעָלְמָא, הָא אֲתַר דָּא לְקֳבְלֵיהּ. וּמֵהָכָא אִתְהַנֵּי עָלְמָא וְיִתְּזָן. דְּהָא לְעֵילָא דְּחִיקוּ אִיהוּ לְאִתְזְנָא עָלְמָא מִנֵּיהּ. וְלָא עוֹד אֶלָּא אֲנַן נִסַּק לִרְקִיעָא וְנַגַּח בֵּיהּ קְרָבָא דְּלָא יֵחוֹת (ביה) טוֹפָנָא בְּעָלְמָא כְּדִבְקַדְמִיתָא:</p>"],[9520011180,"<p>וַיֹּאמֶר יְיָ הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. בְּגִין דְּכֻלְהוּ כְּחֲדָא, בְּיִיחוּדָא דְּכֻלְהוֹן יַעַבְדוּן וְיִצְלְחוּן בְּעוֹבָדַיְיהוּ. יִתְבַּדְּרוּן דַּרְגִּין כָּל חַד לְסִטְרֵיהּ. וּבְגִין כָּךְ יִתְבַּדְּרוּן כָּל הַנֵּי דִלְתַתָּא. מַה כְּתִיב וַיָּפֶץ יְיָ אוֹתָם מִשָּׁם.</p>\n<p>וְאִי תֵימָא לִישַׁנְהוֹן אַמַּאי אִתְבַּלְבֵּל (אתבדר ובלבל לון קודשא בריך הוא). אֶלָּא בְּגִין דְּכֻלְהוֹן מְמַלְּלִין בִּלְשׁוֹן הַקֹּדֶשׁ. הַהוּא לִישְׁנָא קָא עָבִיד לוֹן סִיּוּעָא. בְּגִין דִּבְעוֹבָדָא וּבְמִלּוּלָא דְפוּמָא תַּלְיָין מִלִּין אִלֵּין לְאַדְבְּקָא כַּוָּנָה דְלִבָּא. וּבְדָא עָבְדֵי סִיּוּעָא לְהַהוּא אֲתַר דְּבָעֵי לְאַקָמָא.</p>\n<p>וְעַל דָּא אִתְבַּלְבָּל לִישַׁנְהוֹן דְּלָא יָכִילוּ לְאִתְתַּקָּפָא רְעוּתְהוֹן בִּלְשׁוֹן הַקֹּדֶשׁ. כֵּיוָן דְּאִתְחַלַּף לִישַׁנְהוֹן לָא אַצְלָחוּ בְּעוֹבָדָא (כט א בס\"ת) בְּגִין דְּחֵילָא דִּלְעֵילָא לָא יָדְעֵי וְלָא אִשְׁתְּמוֹדְעֵי בַּר בִּלְשׁוֹן הַקֹּדֶשׁ. וְכַד אִתְבַּלְבָּל לִישְׁנָא דִלְהוֹן אִתְחַלַּשׁ חֵילֵיהוֹן וְאִתְבַּר תּוּקְפָא דִלְהוֹן.</p>\n<p>תָּא חֲזֵי, דְּהָא מִלָּה (דא) דְּאָמְרֵי תַּתָּאֵי בִּלְשׁוֹן הַקֹּדֶשׁ, כֻּלְהוּ חֵילֵי שְׁמַיָא יָדְעֵי בֵּיהּ וְאִתְתַּקְפֵי בֵּיהּ. וְלִישַׁן אָחֳרָא לָא יָדְעִין וְלָא אִשְׁתְּמוֹדְעֵי בֵּיהּ. וְעַל דָּא אִלֵּין כֵּיוָן דְּאִתְבַּלְבָּל לִישָׁנָא דִלְהוֹן, מִיָּד וַיַּחְדְּלוּ לִבְנוֹת הָעִיר. דְּהָא אִתְבַּר חֵילַיְיהוּ וְלָא יָכִילוּ לְמֶעְבַּד מִדֵּי בִּרְעוּתָא דִלְהוֹן.</p>\n<p>(דניאל ב׳:כ׳) לֶהֱוֵי שְׁמֵיהּ (די אלהא) (דקודשא בריך הוא) מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא, דִי חָכְמְתָא וּגְבוּרָתָא דִי לֵהּהִיא. דְּהָא בְּגִין (דא) דְּאַנְחִית קוּדְשָׁא בְּרִיךְ הוּא רָזֵי דְּחָכְמְתָא לְעָלְמָא, אִתְקַּלְקָלוּ בֵּיהּ בְּנֵי נָשָׁא וּבָעוּ לְאִתְגָּרָא בֵּיהּ.</p>\n<p>יָהַב חָכְמְתָא עִלָּאָה לְאָדָם הָרִאשׁוֹן, וּבְהַהִיא חָכְמָה <Nonei></i>דְּאִתְגְּלֵי לֵיהּ יָדַע דַּרְגִּין, וְאִתְדְּבַק בְּיֵצֶר הָרָע, עַד דְּאִסְתַּלְּקוּ מִנֵּיהּ מַבּוּעֵי דְחָכְמְתָא. וּלְבָתַר תָּב קַמֵּי מָארֵיהּ, וְאִתְגַּלְּיָין לֵיהּ מִנַּיְיהוּ וְלָא כְּקַדְמִיתָא. לְבָתַר בְּהַהוּא סִפְרָא דִילֵיהּ יָדַע חָכְמָאן. וּלְבָתַר אָתוּ בְּנֵי נָשָׁא וְאַרְגִּיזוּ קַמֵּיהּ.</p>\n<p>יָהַב חָכְמְתָא לְנֹחַ וּפְלַח בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לְבָתַר מַה כְּתִיב וַיֵּשְׁתְּ מִן הַיַּיִּן וַיִּשְׁכָּר וַיִּתְגַּל כְּמָה דְּאִתְּמָר. יָהַב חָכְמְתָא לְאַבְרָהָם וּפְלַח בָּהּ לְקוּדְשָׁא בְּרִיךְ הוּא. לְבָתַר נָפַק מִנֵּיהּ יִשְׁמָעֵאל דְּאַרְגִּיז קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְכֵן יִצְחָק נָפַק מִנֵּיהּ עֵשָׂו. יַעֲקֹב נְסַב תְּרֵין אֲחָתָן.</p>\n<p>יָהַב חָכְמְתָא לְמשֶׁה מַה כְּתִיב בֵּיהּ (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נְאֱמָן הוּא. וְלָא הֲוָה כְּמשֶׁה שַׁמָּשׁ מְהֵימָן בְּכֻלְהוּ דַּרְגִּין וְלָא סָטָא לִבֵּיהּ בְּתִיאוּבְתָּא דְּחַד מִנַּיְיהוּ. אֶלָּא קָאִים בִּמְהֵימְנוּתָא עִלָּאָה כְּדְקָא יְאוּת.</p>\n<p>יָהַב חָכְמְתָא עִלָּאָה לִשְׁלֹמֹה מַלְכָּא. לְבָתַר מַה כְּתִיב בֵּיהּ (משלי א׳:א׳) מִשְׁלֵי שְׁלֹמֹה (משלי ל׳:א׳) הַמַּשָּׂא נְאֻם הַגֶּבֶר לְאִיתִיאֵל לְאִיתִיאֵל וְאֻכָל. אָמַר שְׁלֹמֹה אִתִּי אֵל וְחָכְמְתָא דִילֵיהּ הוּא. וְאוּכָל וְאֵיכוּל לְמֶעְבַּד רְעוּתִי. לְבָתַר (מלכים א יח) וַיָּקֶם יְיָ שָׂטָן לִשְׁלֹמֹה וְגו'.</p>\n<p>תָּא חֲזֵי, בְּגִין זְעִירוּ דְּחָכְמְתָא דְּאַשְׁכָּחוּ אִלֵּין מֵהַהוּא חָכְמָה דְּקַדְמָאֵי, אִתְגָּרוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבָנוּ מִגְדָּל וְעֲבָדוּ כָּל מַה דְּעֲבָדוּ. עַד דְּאִתְבַּדָּרוּ מֵאַנְפֵּי אַרְעָא וְלָא אִשְׁתָּאַר בְּהוּ חָכְמָה לְמֶעְבַּד מִידֵּי.</p>\n<p>אֲבָל לְזִמְנָא דְּאָתֵי קוּדְשָׁא בְּרִיךְ הוּא יִתְעַר חָכְמְתָא בְּעָלְמָא וְיִפְלְחוּן לֵיהּ בָּהּ הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ו:כ״ז) וְאֶת רוּחִי אֶתֵּן בְּקִרְבְּכֶם וְעָשִׂיתִי. לָאו כְּקַדְמָאֵי דְּחֲבִילוּ בֵּיהּ עָלְמָא. אֶלָּא וְעָשִׂיתִי אֶת אֲשֶׁר בְּחֻקַּי תֵּלֵכוּ וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ וַעֲשִׂיתֶם.</p>\n<p>רַבִּי יוֹסֵי וְרַבִּי חִיָּיא הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר לֵיהּ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא נִפְתַּח בְּאוֹרַיְיתָא וְנֵימָא מִלָּה. פָּתַח רַבִּי יוֹסֵי וְאָמַר (דברים כ״ג:ט״ו) כִּי יְיָ אֱלֹהֶיךָ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנְךָ לְהַצִּילְךָ וְלָתֵת אֹיְבֶיךָ לְפָנֶיךָ וְהָיָה מַחְנְיךָ קָדוֹשׁ וְלֹא יִרְאֶה בְךָ עֶרְוַת דָּבָר וְשָׁב מֵאַחֲרֶיךָ. כִּי יְיָ אֱלֹהֶיךָ מִתְהַלֵּךְ, מְהַלֵּךְ מִבָּעֵי לֵיהּ. אֶלָּא כְּמָא דְאַתְּ אָמֵר (בראשית ג׳:ח׳) מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם. וְדָא הוּא אִילָנָא דְּאָכַל מִנֵּיהּ אָדָם הָרִאשׁוֹן. מִתְהַלֵּךְ נוּקְבָא מְהַלֵּךְ דְּכַר.</p>\n<p>וְדָא הוּא דְּאָזִיל קַמַּיְיהוּ דְיִשְׂרָאֵל כַּד הֲווּ אָזְלֵי בְּמַדְבְּרָא דִּכְתִיב (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגו'. הוּא דְּאָזִיל קַמֵּיהּ דְבַּר נָשׁ כַּד אָזִיל בְּאָרְחָא. דִּכְתִיב, (תהילים פ״ה:י״ד) צֶדֶק לְפָנָיו יְהַלֵּךְ וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו. וְדָא הוּא דְּאָזִיל קַמֵּיהּ דְּבַּר נָשׁ בְּשַׁעֲתָא דְּאִיהוּ זָכֵי. וְלָמָּה. לְהַצִּילְךָ וְלָתֵת אוֹיְבֶיךָ לְפָנֶיךָ. לְאִשְׁתְּזָבָא בַּר נָשׁ בְּאָרְחָא וְלָא יִשְׁלוֹט בֵּיהּ אָחֳרָא.</p>\n<p>וּבְגִין כָּךְ לִבָּעֵי לֵיהּ לְבַּר נָשׁ לְאִסְתַּמְּרָא מֵחוֹבוֹי וּלְדַכָּאָה לְגַרְמֵיהּ. מַאי דַּכְיוּ דָּא. דִּכְתִיב, (דברים כ״ג:ט״ו) וְהָיָה מַחֲנֶיךָ קָדוֹשׁ. מַאי קָדוֹשׁ, קְדוֹשִׁים מִבָּעֵי לֵיהּ. אֶלָּא מַחֲנֶיךָ קָדוֹשׁ אִלֵּין שַׁיְיפֵי גוּפָא דְּגוּפָא אִתְחַבַּר וְאִתְתַּקַּן בְּהוּ. וּבְגִין כָּךְ וְהָיָה מַחֲנְיךָ קָדוֹשׁ. וְלא יִרְאֶה בְךָ עֶרְוַת דָּבָר.</p>\n<p>מַאי עֶרְוַת דָּבָר. דָּא מִלְּתָא (ערייתא) דְעֶרְיָין. דְּדָא הוּא מִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא מָאִיס בָּהּ יַתִּיר מִכֹּלָּא. כֵּיוָן דְּאָמַר וְלא יִרְאֶה בְךָ עֶרְוַת, אַמַּאי דָּבָר. אֶלָּא הַנִּי חַיָּיבֵי עָלְמָא דְּגָעֲלֵי וּמְסָאֲבֵי גַרְמַיְיהוּ בְּמִלָּה דִּלְהוֹן דְּנָפְקֵי מִפּוּמַיְיהוּ וְהָא אִיהוּ עֶרְוַת דָּבָר.</p>\n<p>וְכָל כָּךְ לָמָּה. בְּגִין דְּאִיהוּ אָזִיל קַמָּךְ. וְאִי אַתְּ עָבִיד כְּדֵין, מִיָּד וְשָׁב מֵאַחֲרֶיךָ, דְּלָא יֵזִיל בַּהֲדָךְ וְיֵיתוּב מֵאַחֲרֶיךָ. וְאֲנַן הָא אַזְלִינָן קַמֵּיהּ בְּאָרְחָא נִתְעַסֵּק בְּמִלֵּי דְאוֹרַיְיתָא. דְּהָא אוֹרַיְיתָא אִתְעַטְּרָא עַל רֵישֵׁיהּ דְּבַר נָשׁ וּשְׁכִינְתָּא לָא אַעֲדִיאַת מִינֵּיהּ.</p>\n<p>פָּתַח רַבִּי חִיָּיא וְאָמַר וַיֹּאמֶר ה' הֶן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם וְגו' תָּא חֲזֵי, מַה כְּתִיב וַיְהִי בְּנָסְעָם מִקֶּדֶם. מַאי מִקֶּדֶם. מִקַּדְמוֹנוֹ שֶׁל עוֹלָם. וַיִּמְצְאוּ. וַיִּרְאוּ מִבָּעֵי לֵיהּ מַאי וַיִּמְצְאוּ. אֶלָּא מְצִיאָה אַשְׁכָּחוּ תַּמָּן מֵרָזֵי דְחָכְמְתָא מִקַּדְמָאֵי דְּאִתְנְעַר תַּמָּן מִן בְּנֵי טוֹפָנָא, וּבָהּ אִשְׁתַּדְלוּ לְמֶעְבַּד בְּהַהִיא עֲבִידְתָּא דְּעֲבָדוּ לְסַרְבָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְהֲווּ אָמְרֵי בְּפוּמָא וְעַבְדֵי <Nonei></i>עֲבִידְתָּא.</p>\n<p>חָמֵי מַה כְּתִיב הֶן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם. בְּגִין דְּאִנּוּן בְּלִבָּא חַד וּרְעוּתָא חַד וּמְמַלְּלֵי בִּלְשׁוֹן הַקֹּדֶשׁ. וְעַתָּה לא יִבָּצֵר מֵהֶם כָּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת. וְלֵית מַאן דְּיִמְנַע עוֹבָדָא דִלְהוֹן. אֲבָל מַאי אַעֲבִיד, אֲבַלְבֵּל לוֹן דַּרְגִּין דִלְעֵילָא, וְלִישַׁן דִּלְהוֹן לְתַתָּא. וּכְדֵין אִתְמְנַע עוֹבָדָא דִלְהוֹן.</p>\n<p>וּמַה בְּגִין דְּהֲווּ בִּרְעוּתָא וְלִבָּא חַד וּמְמַלְּלֵי בִּלְשׁוֹן הַקֹּדֶשׁ כְּתִיב לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, וְדִינָא דִלְעֵילָא לָא יָכִיל לְשַׁלְטָאָה בְּהוּ. אֲנַן אוֹ חַבְרַיָיא דְּמִתְעַסְּקִין בְּאוֹרַיְיתָא, וְאֲנַן בְּלִבָּא חַד וּרְעוּתָא חַד, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>אָמַר רַבִּי יוֹסֵי מִכָּאן לְאִנּוּן מָארֵי דְמַחְלוֹקֶת לֵית לוֹן קִיּוּמָא. דְּהָא כָּל זִמְנָא (דאלין) דִּבְנֵי עָלְמָא אִלֵּין עִם אִלֵּין בִּרְעוּתָא חָדָא וְלִבָּא חָד, אַף עַל גַּב דְּמָרְדֵּי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, לָא שָׁלְטָא בְּהוּ דִינָא דִּלְעֵילָא. כֵּיוָן דְּאִתְפַּלְּגוּ מִיָּד וַיָּפֶץ יְיָ אוֹתָם מִשָּׁם וְגו'.</p>\n<p>אָמַר רַבִּי חִיָּיא אִשְׁתְּמַע דְּכֹלָּא בְּמִלָּה דְפוּמָא תַּלְיָיא. דְּהָא כֵּיוָן דְּאִתְבַּלְבֵּל מִיָּד וַיָּפֶץ יְיָ אֹתָם מִשָּׁם. אֲבָל בְּזִמְנָא דְאָתֵי מַה כְּתִיב, (צפניה ג׳:ט׳) כִּי אָז אֶהֱפֹךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻּלָּם בְּשֵׁם יְיָ וּלְעָבְדוֹ שְׁכֶם אֶחָד וּכְתִיב, (זכריה י״ד:ט׳) וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן:</p>"],[9520011181,"<p>לֶךָ לְךָ מֵאַרְצְךָ וגו'. רַבִּי אַבָּא פָּתַח וְאָמַר, (ישעיהו מ״ו:י״ב) שִׁמְעוּ אֵלַי אַבִּיִרִי לֵב הָרְחוֹקִים מִצְדָקָה. שִׁמְעוּ אֵלַי אַבִּירֵי לֵב, כַּמָּה תַּקִּיפִין לִבַּיְיהוּ דְּחַיָיבַיָא, דְּחָמָאן שְׁבִילֵי ואָרְחֵי דְאוֹרַיְיתָא ולָא מִסְתַּכְּלָן בְּהוּ, ולִבַּיְיהוּ תַּקִּיפִין דְּלָא מְהַדְּרִין בִּתְיוּבְתָּא לְגַבֵּי מָרֵיהוֹן, וְאִקְרוּן אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה דְּמִתְרַחֲקֵי מֵאוֹרַיְיתָא.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר דְּמִתְרַחֲקֵי מִקוּדְשָׁא בְּרִיךְ הוּא וְאִנּוּן רְחִיקִין מִנֵּיהּ, וּבְגִין כָּךְ אִקְרוּן אַבִּירֵי לֵב. הָרְחוֹקִים מִצְּדָקָה דְּלָא בָּעָאן לְקָרְבָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כָּךְ אִנּוּן רְחוֹקִים מִצְּדָקָה, כֵּיוָן דְּאִנּוּן רְחוֹקִים מִצְּדָקָה רְחוֹקִים אִנּוּן מִשָּׁלוֹם דְּלֵית לוֹן שָׁלוֹם. דִּכְתִיב, (ישעיהו מ״ח:כ״ב) אֵין שָׁלוֹם אָמַר יְיָ לָרְשָׁעִים. מַאי טַעְמָא בְּגִין דְּאִנּוּן רְחוֹקִים מִצְּדָקָה.</p>\n<p>תָּא חֲזֵי, אַבְרָהָם בָּעֵי לְקָרְבָא לְקוּדְשָׁא בְּרִיךְ הוּא וְאִתְקָרַב. הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:ח׳) אָהַבְתָּ צֶדֶק וַתִּשְׂנָא רֶשַׁע. בְּגִין דְאָהַב צֶדֶק וְשָׂנָא רֶשַׁע אִתְקָרַב לִצְדָקָה, וְעַל דָּא כְּתִיב, (ישעיהו מ״א:ח׳) אַבְרָהָם אוֹהֲבִי. מַאי טַעְמָא אוֹהֲבִי, בְּגִין דִּכְתִיב אָהַבְתָּ צֶדֶק. רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּרָחִים <Nonei></i>לֵיהּ אַבְרָהָם מִכָּל בְּנֵי דָרִיהּ דְּהֲווּ אַבִּירֵי לֵב וְאִנּוּן רְחוֹקִים מִצְּדָקָה כְּמָה דְּאִתְּמָר.</p>"],[9520011182,"<p>רַבִּי יוֹסֵי פָּתַח (תהילים פ״ד:ב׳) מַה יְּדִידוֹת מִשְׁכְּנוֹתֶיךָ יְיָ צְבָאוֹת. כַּמָּה אִית לוֹן לִבְנִי נָשָׁא לְאִסְתַּכָּלָא בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא כָּל בְּנֵי נָשָׁא לָא יָדְעֵי וְלָא מִסְתַּכְּלֵי עַל מַה קָּאִים עָלְמָא. וְאִנּוּן עַל מַה קָּיְימִין. דְּכַד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא עֲבַד שְׁמַיָא מֵאֵשׁ וּמִמַּיִם מִתְעָרְבִין כְּחֲדָא וְלָא הֲווּ גַּלְדֵי. וּלְבָתַר אַגְלִידוּ וְקָיְימוּ בְּרוּחָא עִלָּאָה וּמִתַּמָּן שָׁתִיל עָלְמָא, לְקָיְימָא עַל סָמְכִין, וְאִנּוּן סָמְכִין לָא קָיְימִין אֶלָּא בְּהַהוּא רוּחָא, וּבְשַׁעֲתָא דְּהַהוּא רוּחָא אִסְתַּלַּק כֻּלְהוּ מְרַפְפִין וְזָעִין וְעָלְמָא אִרְתַּת הֲדָא הוּא דִכְתִיב, (איוב ט׳:ו׳) הַמַּרְגִּיז אֶרֶץ מִמְקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן. וְכֹלָּא קָאִים עַל אוֹרַיְיתָא, דְּכַד יִשְׂרָאֵל מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא מִתְקַיֵּים עָלְמָא וְאִנּוּן קָיְימִין וְסָמְכִין קָיְימִין בְּאַתְרַיְיהוּ בְּקִיּוּמָא שְׁלִים.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְאִתְעַר פַּלְגוּת לֵילְיָא וְקוּדְשָׁא בְּרִיךְ הוּא עָאל לְגִנְתָא דְעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָא, כֻּלְהוּ אִילָנִין דִּבְגִנְתָא דְעֵדֶן מְזַמְּרָן וּמְשַׁבְּחָן קַמֵּיהּ. דִּכְתִיב, (דברי הימים א ט״ז:ל״ג) אָז יְרַנְּנוּ עֲצֵי הַיָּעַר מִלִּפְנֵי יְיָ וְגו'.</p>\n<p>וְכָרוֹזָא קָרֵי בְחָיִל וְאָמַר לְכוֹן אָמְרִין קַדִּישִׁין עֶלְיוֹנִין, מָאן מִנְכוֹן דְּעָיִיל רוּחָא בְּאוּדְנוֹי לְמִשְׁמָע, וְעֵינוֹי פְּקִחִין לְמֶחֱמֵי. וְלִבֵּיהּ פָּתוּחַ לְמִנְדַע, בְּשַׁעֲתָא דְּרוּחָא דְכָל רוּחִין אָרִים בְּסִימוּ דְנִשְׁמָתָא, וּמִתַּמָּן נָפִיק קָלָא דְּקָלַיָא, חֵיְלִין אִתְבַּדַּר לְאַרְבַּע סִטְרֵי עָלְמָא.</p>\n<p>א חַד סָלִיק לִסְטַר חָד. ב חַד נָחִית לְהַהוּא סְטַר. ג (תיקונים עג, לעיל לב ב) חַד עָיִיל בֵּין תְּרֵין. ד תְּרֵין מִתְעָרִין מִתְעַטְּרָן בִּתְלַת. ה תְּלַת עָיְילֵי בְּחַד. ו חַד אַפִּיק גְּוָונִין. ז שִׁית מִנְהוֹן לִסְטַר חָד, וְשִׁית מִנְהוֹן נָחֲתֵי לְהַהוּא סְטַר. ח שִׁית עָיְילֵי בִּתְרֵיסַר. ט תְּרֵיסַר מִתְעָרִין בְּעֶשְׂרִין וּתְרֵין. י שִׁית כְּלִילָן בַּעֲשָׂרָה. יא עֲשָׂרָה קָאִים בְּחַד.</p>\n<p>וַוי לְאִנּוּן דְּנַיְימֵי שֵׁנְתָא בְּחוֹרֵיהוֹן, לָא יָדְעֵי וְלָא מִסְתַּכְּלָאן אֵיךְ יְקוּמוּן בְּדִינָא דְּחוּשְׁבַּן אִתְפַּקַד, <Nonei></i>כַּד אִסְתָּאַב גּוּפָא, וְנִשְׁמָתָא שַׁטְיָא עַל אַנְפֵּי דְּאֲוִירָא דְּטִיהֲרָא, וְסָלְקָא וְנַחֲתָא, וְתַרְעִין לָא מִתְפַּתְּחָן, מִתְגַּלְגְּלָן כְּאַבְנִין בְּגוֹ קוּסְפִיתָא. וַוי לוֹן מַאן יִתְבַּע לוֹן, דְּלָא יְקוּמוּן בְּעִדּוּנָא דָא בְּגוֹ דוּכְתֵּי דְּעִנּוּגֵי דְצַדִּיקַיָא, אִתְפַּקְדּוּן דּוּכְתַּיְיהוּ. אִתְמַסְּרוּן בִּידָא דְדוּמָה, נַחֲתֵי וְלָא סַלְקֵי. עֲלַיְיהוּ כְּתִיב, (איוב ז׳:ט׳) כָּלָה עָנָן וַיֵּלַךְ כֵּן יוֹרֵד שְׁאוֹל לא יַעֲלֶה.</p>\n<p>בְּהַהִיא שַׁעֲתָא אִתְעַר שַׁלְהוֹבָא חַד מִסְּטַר צָפוֹן וּבָטַשׁ בְּאַרְבַּע סִטְרֵי עָלְמָא וְנָחִית וּמָטֵי בֵּין גַּדְפֵי דְתַרְנְגוֹלָא וְאִתְעַר הַהוּא שַׁלְהוֹבָא בֵּיהּ וְקָרֵי, וְלֵית מַאן דְּאִתְעַר בַּר אִנּוּן זַכָּאֵי קְשׁוֹט דְּקָיְימֵי וְאִתְעָרוּ בְּאוֹרַיְיתָא. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא וְכָל אִנּוּן צַדִּיקַיָיא דִּבְגוֹ גִנְתָא דְעֵדֶן צַיְיתֵי לְקָלֵיהוֹן. כְּמָא דְאַתְּ אָמֵר, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְּׁמִיעִנִי:</p>"],[9520011183,"<p><Nonei></i><Noneb>סִתְרֵי תוֹרָה</b> תּאנָא בְּתּוּקְפָּא דְּהֻרְמָנוּ דְמַלְכָּא, אַנְצִּיב חַד אִילָנָא רַבָּא וְתַּקִּיף גּוֹ נְטִיעָן עִלָאִין, נְטִיעַ אִילָנָא דָּא, בִּתְּרֵיסַר תְּחוּמִין אִסְתַּחַר, בְּאַרְבַּע סִטְרִין דְעָלְמָא פְּרִישָׂא רַגְלֵיהּ.</p>\n<p>תּ\"ק פַּרְסֵי מַטְלָנוֹי, כָּל רְעוּתִּין דְּאִנּוּן פָּרְסִין בֵּיהּ תָּלְיָין, כַּד אִתְּעַר הַאי, כֻּלְהוּ מִתְּעָרִין בַּהֲדֵיהּ לֵיתּ מַאן דְּנָפִּיק מֵרְעוּתֵּיהּ לְבָתַּר, כֻּלְהוּ בִּרְעוּתָּא חָדָא בַּהֲדֵיהּ,</p>\n<p>קָם מִלְּעֵילָא (ס\"א נחית) אִתְּנָחִיתּ בְּמַטְלָנוֹי לְגוֹ יַמָּא. מִנֵּיהּ יַמָּא (אתגלי) אִתְּמַלְיָיא. אִיהוּ מְקוֹרָא (דכל ד\"א לכל) מַיִין דְּנָבְעִין. תְּחוֹתֵּיהּ מִתְּפַּלְּגִין כָּל מֵימוֹי דִּבְרֵאשִׁיתּ, שַׁקְיוּ דְּגִנְתָּא בֵּיהּ תַּלְיָין.</p>\n<p>כָּל נִשְׁמְתִּין דְּעָלְמָא מִנִּיהּ פָּרְחִין. נִשְׁמְתִּין אִלֵּין עָאלִין בְּגִנְתָּא לְנָחֲתָּא לְהַאי עָלְמָא. נִשְׁמָתָּא כַּד נָפְּקָא אִתְּבָּרְכָא בְּשֶׁבע בִּרְכָאן לְמֶהֱוֵי אַבָּא (ד\"א ל\"ג לרוחא ודם) לְגוּפָּא (ולמהוי) בִּסְלִיקוּ (דדיוקנא עלאה הדא הוא דכתיב ויאמר יי אל אברם הא נשמתא עלאה אבא (ד\"א ל\"ג לרוחא ודם) לגופא בסליקו) דְּדִיוּקְנא עִלָּאָה.</p>\n<p>כַּד בַּעְיָא (נפשא) לְנָחֲתָּא לְהַאי עָלְמָא, אוֹמֵי לָהּ קוּדְשָׁא בְּרִיךָ הוּא לְמִיטַר פִּקּוּדֵי אוֹרַיְיתָּא וּלְמֶעְבַּד רְעוּתֵּיהּ. וּמָסַר לָהּ מְאָה מַפְּתְּחָאן <Nonei></i>דְּבִרְכָאן.</p>\n<p>(ומולדתך דא גופא דאתקרי אילנא דחיי דאיהו תריסר שבטין עלאין. ומבית אביך דא שכינתא. אביך דא קודשא בריך הוא. שנאמר (משלי כ״ח:כ״ד) גוזל אביו ואמו ואומר אין פשע וגו'. ואין אביו אלא קודשא בריך הוא ואין אמו אלא כנסת ישראל. אל הארץ אשר אראך דא איהו האי עלמא), (נ\"א ומולדתך דא אילנא דחיי, ומבית אביך תריסר תחומין שבטין עלאין. אל הארץ אשר אראך דא איהו האי עלמא), (עד כאן סתרי תורה)</p>"],[9520011184,"<p><Nonei></i>וַיֹּאמֶר יְיָ אֶל אַבְרָם, מַה כְּתִיב לְעֵילָא (בראשית י״א:כ״ח) וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו וְגו'. מַאי אִירְיָא הָכָא, אֶלָּא עַד הַהוּא יוֹמָא לָא הֲוָה בַּר נָשׁ דְּמִית בְּחַיֵּי אֲבוֹי בַּר דָּא, וְכַד אִתְרְמֵי אַבְרָם לְנוּרָא אִתְקְטִיל הָרָן, וּבְגִין דָּא נָפְקוּ מִתַּמָּן מַאן קָטִיל לוֹן לְהָרָן, אֶלָּא כֵּיוָן דְּרָמוּ אַבְרָהָם לְנוּרָא דְכַּשְּׂדָאֵי, אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּשֵׁזָבֵיהּ, וְהֲוָה הָרָן אֲחוּי קָאֵי תַּמָּן. אָמְרוּ כַּשְּׂדָאֵי בְגִין זְכוּתֵיהּ דְהָרָן אִשְׁתְּזִיב, מִיָּד נָפַק שַׁלְהוֹבָא דְּאֶשָׁא וְאוֹקְדֵיהּ לְהָרָן, הֲדָא הוּא דִכְתִיב וַיָּמָת הָרָן עַל פְּנִי תֶּרַח אָבִיו. וְאִית דְּאָמְרֵי זַרְעָא דְתֶּרַח לֵית אֶשָׁא שָׁלְטָא בֵּיהּ, אֲבָל נְּרָמֵי לְהָרָן לְנוּרָא, וְאִי לָא אִיתּוֹקַד נֵדַע בְּוַדַּאי דְּלָא שָׁלְטָא נוּרָא בְּזַרְעֵיה, מִיָּד רָמִי לֵיהּ לְהָרָן לְנוּרָא וְאִתּוֹקְד וְהֲוָה תֶּרַח אֲבוֹי קָאִים תַּמָּן הֲדָא הוּא דִכְתִיב וַיָּמָת הָרָן עַל פְּנֵי תֶּרַח אָבִיו. בְּהַהוּא יוֹמָא יָדְעוּ כָּל אוּמַיָא וְלִישְׁנַיָא דְלָא שֵׁיזְבֵיהּ לְאַבְרָהָם אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ יְחִידָאִי דְעָלְמָא, וְהֲווּ מַיְיתֵין בְּנַיְיהוּ לְמִשְׁכְּנֵיהּ דְאַבְרָהָם וְאָמְרִין לֵיהּ חָמִינָן לָךְ, דְּאַתְּ רָחִיץ בְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ רִבּוֹנֵיהּ דְעָלְמָא, אוֹלִיף לְּבָנָנָא מֵאוֹרְחָךְ דְּאַתְּ יֵדַע, וְעֲלַיְיהוּ אָמַר קְרָא (תהילים מ״ז:י׳) נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם).</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וַיִּקַּח תֶּרַח אֶת אַבְרָם בְּנוֹ וְאֶת לוֹט בֶּן הָרָן וְגו'. וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים. וַיֵּצְאוּ אִתָּם, אִתּוֹ מִבָּעֵי לֵיהּ. דְּהָא כְּתִיב וַיִּקַּח תֶּרַח וְגו' מַאי וַיֵּצְאוּ אִתָּם. אֶלָּא תֶּרַח וְלוֹט עִם אַבְרָהָם וְשָׂרָה נַפְקוּ דְּאִנּוּן הֲווּ עִקְּרָא לְמֵיפַּק מִגּוֹ אִנּוּן חַיָּיבַיָּא, דְּכֵיוָן דְּחָמָא תֶּרַח דְּאַבְרָהָם בְּרֵיהּ אִשְׁתְּזִיב מִגּוֹ נוּרָא, אִתְהַדַּר לְמֶעְבַּד רְעוּתֵיהּ דְּאַבְרָהָם, וּבְגִין כָּךְ וַיֵּצְאוּ אִתָּם תֶּרַח וְלוֹט.</p>\n<p>וּבְשַׁעֲתָא דְּנַפְקוּ מַה כְּתִיב לָלֶכֶת אַרְצָה כְּנַעַן. דִּרְעוּתָא דִלְהוֹן הֲוָה לְמֵיהַךְ תַּמָּן. מִכָּאן אוֹלִיפְנָא כָּל מַאן דְּאִתְעַר לְאִתְדַּכָּאָה מְסַיְיעִין לֵיהּ. תָּא חֲזֵי, דְּהָכִי הוּא דְּכֵיוָן דִּכְתִיב לָלֶכֶת אַרְצָה כְּנַעַן מִיָּד וַיֹּאמֶר יְיָ אֶל אַבְרָם לֶךְ לְךָ, וְעַד דְּאִיהוּ אִתְעַר בְּקַדְמִיתָא לָא כְּתִיב לֶךְ לְךָ.</p>\n<p>תָּא חֲזֵי, מִלָה דִלְעֵילָא לָא אִתְעַר עַד דְּאִתְעַר לְתַתָּא בְּקַדְמִיתָא עַל מַה דְּתִשְׁרֵי הַהִיא דִלְעֵילָא, וְרָזָא דְמִלָּה, נְהוֹרָא אוּכְמָא לָא אִתְאַחִיד בִּנְהוֹרָא חִוָּורָא עַד דְּאִיהִי אִתְעָרִית בְּקַדְמִיתָא, כֵּיוָן דְּאִיהִי אִתְעָרִית בְּקַדְמִיתָא, מִיָּד נְהוֹרָא חִוְורָא שַׁרְיָיא עֲלָהּ.</p>\n<p>וְעַל דָּא כְּתִיב (תהילים פ״ג:ב׳) אֱלֹהִים אַל דָּמִי לָךְ אַל תֶּחֱרָשׁ וְאַל תִּשְׁקֹט אֵל. בְּגִין דְּלָא יִתְפְּסַק נְהוֹרָא חִוָּורָא מֵעָלְמָא לְעָלְמִין. וְכֵן (ישעיהו ס״ב:ו׳) הַמַּזְכִּירִים אֶת יְיָ אַל דֳּמִי לָכֶם. בְּגִין לְאַתְעָרָא לְתַתָּא בְּמָּה דְיִשְׁרֵי אִתְעֲרוּתָא דִלְעֵילָא. וְכֵן כֵּיוָן דְּאִתְעַר בַּר נָשׁ אִתְעֲרוּתָא בְּקַדְמִיתָא כְּדֵין אִתְעַר אִתְעֲרוּתָא דִלְעֵילָא. תָּא חֲזֵי, כֵּיוָן דִּכְתִיב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים וְגו' מִיָּד וַיֹּאמֶר יְיָ אֶל אַבְרָם וְגו'.</p>"],[9520011185,"<p>וַיֹּאמֶר יְיָ אֶל אַבְרָם לֶךְ לְךָ, אָמַר רַבִּי אֶלְעָזָר לֶךְ לְךָ, לְגַרְמָךְ לְאַתְקָנָא גַּרְמָךְ, (לאתתקפא) לְאַתְקָנָא דַּרְגָּא דִילָךְ. לֶךְ לְךָ, לֵית אַנְתְּ (ס\"א כדאי) לְמֵיקַם הָכָא בֵּין חַיָּיבִין אִלֵּין.</p>\n<p>וְרָזָא דְמִלָּה לֶךְ לְךָ <Nonei></i>דְּהָא קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֵיהּ לְאַבְרָהָם רוּחָא דְחָכְמְתָא, וְהֲוָה יָדַע וּמְצָרֵף (צנורי) סִטְרֵי דְּיִישׁוּבֵי עָלְמָא, וְאִסְתַּכַּל בְּהוּ וְאַתְקַל בְּתִיקְלָא וְיָדַע חֵילִין דִּי מְמַנָּן עַל סִטְרֵי יִישׁוּבָא.</p>\n<p>כַּד מָטָא לְגוֹ נְקוּדָה דְּאֶמְצָעִיתָא דְיִישׁוּבָא תָּקִיל בְּתִיקְלָא וְלָא הֲוָה סָלִיק בְּיָדֵיהּ. אַשְׁגַּח לְמִנְדַע חֵילָא דִי מְמַנָּא עֲלָהּ וְלָא יָכִיל לְאִתְדַּבְּקָא בִּרְעוּתֵיהּ,</p>\n<p>תָּקִיל כַּמָּה זִמְנִין וְחָמָא דְּהָא מִתַּמָּן אִשְׁתִּיל כָּל עָלְמָא, אַשְׁגַּח וְצָרַף וְתָקַל לְמִנְדַע וְחָמָא דְּהָא חֵילָא עִלָּאָה דְּעֲלָהּ לֵית לֵיהּ שִׁעוּרָא עָמִיק וְסָתִים וְלָאו אִיהוּ כְּגַוְונֵי דְּסִטְרֵי דַּרְגֵּי דְיִשּׁוּבָא.</p>\n<p>אַשְׁגַח וְתָקִיל וְיָדַע דְּהָא כְּמָּה דְּמֵהַהִיא נְקוּדָה אֶמְצָעִיתָא דְּיִשּׁוּבָא מִנֵּיהּ אִשְׁתִּיל כָּל עָלְמָא לְכָל סִטְרוֹי. הָכִי נָמֵי יָדַע דְּהָא חֵילָא דְּשָׁרֵי עֲלָהּ מִתַּמָּן נָפְקוּ כָּל שְׁאָר חֵילִין דִּמְמַנָן עַל כָּל סִטְרֵי עָלְמָא, וְכֻלְהוּ בֵּיהּ אֲחִידָן. כְּדֵין (בראשית י״א:ל״א) וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִים לָלֶכֶת אַרְצָה כְּנַעַן.</p>\n<p>עוֹד אַשְׁגַּח וְתָקִיל וְצָרִיף לְמֵיקַם עַל בְּרִירָא דְמִלָּה דְּהַהוּא אֲתַר וְלָא הֲוָה יָדַע וְלָא יָכִיל לְמֵיקַם עֲלָהּ לְאִתְדַּבְּקָא, כֵּיוָן דְּחָמָא תּוּקְפָא דְּהַאי אֲתַר וְלָא יָכִיל לְמֵיקַם עֲלֵיהּ מִיָּד וַיָּבֹאוּ עַד חָרָן וַיֵּשְׁבוּ שָׁם.</p>\n<p>מַאי טַעְמָא דְאַבְרָהָם. אֶלָּא דְּאִיהוּ הֲוָה יָדַע וְצָרִיף בְּכָל אִנּוּן שָׁלְטָנִין מְדַבְּרֵי עָלְמָא בְּכָל סִטְרוֹ דְיִשּׁוּבָא, וְהֲוָה תָּקִיל וְצָרִיף אִנּוּן דְּשָׁלְטִין בְּסִטְרֵי דְיִשּׁוּבָא מְדַבְּרֵי כֹּכְבַיָא וּמַזָּלֵיהוֹן, מַאן אִנּוּן תַּקִּיפִין אִלֵּין עַל אִלֵּין, וְהֲוָה תָּקִיל כָּל יִשּׁוּבֵי דְעָלְמָא (ולא) וְהֲוָה סָלִיק בִּידוֹי. כַּד מָטָא לְהַאי אֲתַר חָמָא תַּקִּיפוּ דְּעֲמִיקִין וְלָא יָכִיל לְמֵיקַם בֵּיהּ.</p>\n<p>כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא אִתְעֲרוּתָא דִילֵיהּ וְתִיאוּבְתָּא דִילֵיהּ. מִיָּד אִתְגְּלִי עֲלֵיהּ וְאָמַר לֵיהּ לֶךְ לְךָ. לְמִנְדַע לָךְ וּלְאַתְקָנָא גַּרְמָךְ.</p>\n<p>מֵאַרְצְךָ, מֵהַהוּא סִטְרָא דְיִשּׁוּבָא דְּהֲוִית מִתְדַּבַּק בֵּיהּ. וּמִמּוֹלַדְתְּךָ, מֵהַהוּא חָכְמָה דְּאַתְּ מַשְׁגַּח וְתָקִיל תּוֹלְדָתָא דִילָךְ וְרִגְעָא וְשַׁעֲתָא וְזִמְנָא דְּאִתְיְילִידַת בֵּיהּ וּבְהַהוּא כּוֹכָבָא וּבְהַהוּא מַזָּלָא.</p>\n<p>וּמִבֵּית אָבִיךָ, דְּלָא תַשְׁגַּח בְּבֵיתָא דְּאֲבוּךְ. וְאִי אִית לָךְ שָׁרְשָׁא לְאַצְלָחָא בְּעָלְמָא מִבֵּיתָא דְּאֲבוּךְ, בְּגִין כָּךְ לֶךְ לְךָ מֵחָכְמָה דָּא וּמֵאַשְׁגָּחוּתָא דָּא.</p>\n<p>תָּא חֲזֵי, דְּהָכִי הוּא, דְּהָא נָפְקוּ מֵאוּר כַּשְׂדִּים וְהֲווּ בְּחָרָן, אַמַּאי יֵימָא לֵיהּ לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ. אֶלָּא עִקְּרָא דְמִלְּתָא כְּמָה דְּאִתְּמָר. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ. אַרְאֶךָּ מַה דְּלָא יְכִילַת לְמֵיקַם עֲלֵיהּ וְלָא יְכִילַת לְמִנְדַע חֵילָא דְּהַהִיא אַרְעָא דְּאִיהוּ עָמִיק וְסָתִים:</p>"],[9520011186,"<p>וְאֶעֶשְׂךָ לְגוֹי גָדוֹל וְגו' וְאֶעֶשְׂךָ, בְּגִין דִּכְתִיב לֶךְ לְךָ. וַאֲבָרַכֶךָּ, בְּגִין דִּכְתִיב מֵאַרְצְךָ. וַאֲגַדְּלָה שְׁמֶךָ, בְּגִין דִּכְתִיב וּמִמּוֹלַדְתְּךָ. וְהְיֵה בְּרָכָה, בְּגִין דִּכְתִיב וּמִבֵּית אָבִיךָ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר וְאֶעֶשְׂךָ לְגוֹי גָדוֹל מִסִּטְרָא דְּיָמִינָא. וַאֲבָרַכֶךָּ מִסִּטְרָא דִּשְׂמָאלָא וַאֲגַדְּלָה שְׁמֶךָ מִסִּטְרָא דְאֶמְצָעִיתָא. וְהְיֵה בְּרָכָה מִסִּטְרָא דְאַרְעָא דְיִשְׂרָאֵל. הָא הָכָא כֻּרְסְיָיא דְּאַרְבַּע סָמְכִין דְּכֻלְהוּ כְּלִילָן בֵּיהּ בְּאַבְרָהָם, מִכָּאן וּלְהָלְאָה בִּרְכָאן לְאַחֲרִינֵי דְּמִתְּזְנֵי מֵהָכָא דִּכְתִיב וַאֲבָרְכָה מְבָרַכֶיךָ <Nonei></i>וּמְקַלֶּלְךָ אָאוֹר וְנִבְרְכוּ בְךָ כֹּל מִשְׁפְּחוֹת הָאֲדָמָה.</p>"],[9520011187,"<p>רַבִּי אֶלְעָזָר הֲוָה יָתִיב קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן אֲבוֹי, וְהֲוֵי עִמֵיהּ רַבִּי יְהוּדָה וְרַבִּי יִצְחָק וְרַבִּי חִזְקִיָּה. אָמַר לֵיהּ רַבִּי אֶלְעָזָר לְרַבִּי שִׁמְעוֹן אֲבוֹי, הַאי דִכְתִיב לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ, כֵּיוָן דְּכֻלְהוּ נָפְקוּ לְמֵהַךְ, אַמַּאי לָא אִתְּמָר לֵיהּ דְּכֻלְהוּ יִפְקוּן.</p>\n<p>דְּהָא אַף עַל גַּב דְּתֶרַח הֲוָה פְּלַח לְעֲבוֹדָה זָרָה. כֵּיוָן דְּאִתְעַר בְּאִתְעֲרוּתָא טַב לְמֵיפַק בַּהֲדֵיהּ דְּאַבְרָהָם, וְחָמִינָן דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בִּתְיוּבְתָּא דְּחַיָּיבַיָא וּשְׁרָא לְמֵיפַק אַמַּאי לָא כְּתִיב לְכוּ לָכֶם, אַמַּאי לְאַבְרָהָם בִּלְחוֹדוֹי לֶךְ לְךָ.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, אִי תֵימָא דְּתֶרַח כַּד נָפַק מֵאוּר כַּשְׂדִּים בְּגִין לְאַהֲדָרָא בִּתְשׁוּבָה הֲוָה, לָאו הָכִי. אֶלָּא כַּד נָפַק לְאִשְׁתְּזָבָא נָפַק, דְּהֲווּ כֻּלְהוּ בְּנֵי אַרְעֵיהּ בָּעָאן לְמִקְטְלֵיהּ. כֵּיוָן דְּחָזוּ דְּאִשְׁתְּזִיב אַבְרָהָם הֲווּ אָמְרֵי לֵיהּ לְתֶרַח, אַנְתְּ הוּא דְּהֲוִית מַטְעֵי לָן בְּאִלֵּין פְּסִילִין, וּמִגּוֹ דַּחֲלָא דִּלְהוֹן נָפַק תֶּרַח, כֵּיוָן דְּמָטָא לְחָרָן לָא נָפַק מִתַּמָּן לְבָתַר, דִּכְתִיב וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ וַיֵּלֶךְ אִתּוֹ לוֹט, וְאִילוּ תֶּרַח לָא כְּתִיב (ביה וילך, אלא ויצא).</p>\n<p>פָּתַח וְאָמַר (איוב ל״ח:ט״ו) וַיִּמְנַע מֵרְשָׁעִים אוֹרָם וּזְרוֹעַ רָמָּה תְּשַׁבֵּר. הַאי קְרָא אוּקְמוּהָ, אֲבָל וַיִּמְנַע מֵרְשָׁעִים אוֹרָם, דָּא נִמְרוֹד וּבְנֵי דָּרֵיהּ דְּנָפַק אַבְרָהָם מִנַּיְיהוּ דְּהֲוָה אוֹרָם. וּזְרוֹעַ רָמָּה תְּשַׁבֵּר, דָּא נִמְרוֹד.</p>\n<p>דָּבָר אַחֵר וַיִּמְנַע מֵרְשָׁעִים אוֹרָם, דָּא תֶּרַח וּבְנֵי בֵיתֵיהּ. אוֹרָם, דָּא אַבְרָהָם. הָאוֹר לָא כְּתִיב אֶלָּא אוֹרָם דְּהֲוָה עִמְּהוֹן. וּזְרוֹעַ רָמָּה תְּשַׁבֵּר, דָּא נִמְרוֹד דְּהֲוָה מַטְעֵי אֲבַתְרֵיהּ כָּל בְּנֵי עָלְמָא, וּבְגִין כָּךְ כְּתִיב לֶךְ לְךָ. בְּגִין לְאַנְהָרָא לָךְ וּלְכָל אִנּוּן דְּיִפְקוּן מִינָךְ מִכָּאן וּלְהָלְאָה.</p>\n<p>תּוּ פָּתַח וְאָמַר, (איוב ל״ז:כ״א) וְעַתָּה לֹא רָאוּ אוֹר בָּהִיר הוּא בַּשְּׁחָקִים וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. וְעַתָּה לא רָאוּ אוֹר, אֵימָתַי, בְּשַׁעֲתָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ. בָּהִיר הוּא בַּשְּׁחָקִים. דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַדְבָּקָא לֵיהּ לְאַבְרָהָם בְּהַהוּא אוֹר דִּלְעֵילָא וּלְאַנְהָרָא תַּמָּן.</p>\n<p>וְרוּחַ עָבְרָה וַתְּטַהֲרֵם. דְּהָא לְבָתַר תָּבוּ בִּתְיוּבְתָּא תֶּרַח וְכָל בְּנֵי בֵיתֵיהּ (נ\"א וכל בני מאתיה). בְּנֵי בֵיתֵיהּ (נ\"א בני מאתיה) דִּכְתִיב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. תֶּרַח, דִּכְתִיב וְאַתָּה תָבֹא אֶל אֲבוֹתֶיךָ בְּשָׁלוֹם וְגו'.</p>\n<p><Nonei></i><Noneb>סִתְרֵי תּוֹרָה</b> וְאֶעֶשְׂךָ לְגוֹי גָדוֹל הַאי בִּרְכְּתָּא חָדָא, וַאֲבָרֶכְךָ תְּרֵין, וַאֲגַדְּלָה שְׁמֶךָ תְּלַתּ, וְהְיֵה בְּרָכָה אַרְבַּע. וַאֲבָרְכָה מְבָרֲכֶיךָ חָמֵשׁ, וּמְקַלֶּלְךָ אָאוֹר שִׁיתּ. וְנִבְרְכוּ בְךָ כָּל מִשְׁפְּחוֹתּ הָאֲדָמָה הא שֶׁבַע. כֵּיוָן דְּאִתְּבָּרְכוּ בְּאִלֵּין שֶׁבַע בִּרְכָאן, מַה כְּתִּיב וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ לְנָחֲתָּא לְהַאי עָלְמָא כְּמָה דְּאִתְּפָּקְדָא.</p>\n<p>מִיָּד וַיֵּלֶךָ אִתּוֹ לוֹט. דָּא אִיהוּ נָחָשׁ דְּאִתְּלַטְיָא וְאִתְּלַטְיָא עָלְמָא בְּגִינֵיהּ דְּאִיהוּ קָאִים לְפִּתְּחָא לְאַסְטָאָה לְגוּפָּא, ולא תִּפְּעוֹל נִשְׁמָתָּא פּוּלְחָנָא דְאִתְּפַּקְדַתּ עַד דְּיַעַבְרוּן עֲלָהּ בְּהַאי עָלְמָא י\"ג שְׁנִין, דְּהָא מִתְּרֵיסַר שְׁנִין וּלְעֵילָא נִשְׁמָתָּא אִתְּעָרַתּ לְמִפְּלַח פּוּלְחָנא דְאִתְּפַּקְדַתּ הֲדָא הוּא דִכְתִּיב. <Nonei></i>וְאַבְרָם בֶּן חָמֵשׁ שָׁנִים וְשִׁבְעִים שָׁנָה. שֶׁבַע וְחָמֵשׁ תְּרֵיסַר אִנּוּן (ותרין עלאין עלייהו ארבע סרי אנון).</p>\n<p>וּכְדֵין אִתְּחֲזִיאַתּ נִשְׁמָתָּא בְּהַאי עָלְמָא. דְּאִיהִי אַתְּיָא מֵחָמש שָׁנִים דְּאִנּוּן תּ\"ק פַּרְסֵי דְּאִילָנָא דְחַיֵּי. וְשִׁבְעִים שָׁנָה דָּא אִיהוּ הַהוּא אִילָנָא מַמָּשׁ דְּאִיהוּ שְׁבִיעָאָה לְדַרְגִּין וְשִׁבְעִין שָׁנָה אִתְּקְרֵי.</p>\n<p>כְּדֵין נָפְּקַתּ מֵהַהוּא זוּהֲמָא דְנָחָשׁ וְעָאלַתּ בְּפּוּלְחָנָא קַדִּישָׁא הֲדָא הוּא דִכְתִּיב בְּצֵּאתּוֹ מֵחָרָן (ימי ע' שנה לא ספורות חיים מההוא ארבע סרי) מֵהַהוּא רוּגְזָא וְתּוּקְפָּא דְּהַהוּא (שטן) נָחָשׁ דְּהֲוָה אַסְטֵי לֵיהּ עַד הַשְׁתָּא לְגוּפָּא וְשָׁלְטָא עֲלוֹי.</p>\n<p>בְּאִילָנָא שָׁלְטָא עָרְלָה תְּלַתּ שְׁנִין. בְּבַר נָשׁ תְּלַתּ סָרֵי שְׁנִין דְּאִקְרוּן שְׁנֵי עָרְלָה, כֵּיוָן דְּאַעֲבָרוּ עַל גּוּפָּא אִנּוּן שְׁנִין וְאִתְּעַבְרַתּ (ד\"א ואתערת) נִשְׁמָתָּא לְמִפְּלַח פּוּלְחָנָא קַדִּישָׁא, פְּקִידַתּ לְגוּפָּא לִרְעוּתָּא טָבָא, לִכְפּוֹף לְהַהוּא נָחָשׁ דְּהָא לָא יָכִיל <Nonei></i>לְשַׁלְטָאָה כְּמָה דְהַוִּי,</p>\n<p>דִּכְתִּיב וַיִּקַּח אַבְרָם אֶתּ שָׂרַי אִשְׁתּוֹ וְגו' (אברם דא י' את שרי דא ה'. י' דא נשמתא לנשמתא והוא זכר. ה' דא נשמתא דנוקבא). דָּא גּוּפָּא, דְּאִיהִי לְגַבֵּי נִשְׁמָתָּא כְּנוּקְבָא לְגַבֵּי דְכוּרָא. וְאֶתּ לוֹט בֶּן אָחִיו דָּא (יצר הרע) נָחָשׁ דּלא אַעֲדֵי כָּל כָּךָ מִן גּוּפָּא, בְּגִין דְּבֵקוּתָּא דְּגוּפָּא לָא אַעֲדִיוּ כָּל כָּךָ (זמנא ההוא) מִנֵּיהּ, אֲבָל אִתְּעֲרוּתָּא דְנִשְׁמָתָּא אַלְקֵי לֵיהּ תָּדִיר וְאַתְּרֵי בֵּיהּ וְאוֹכַח לֵיהּ וְכָפִּיף לֵיהּ על כָּרְחֵיהּ וְלָא יָכִיל לְשַׁלְטָאָה.</p>\n<p>וְאֶתּ כָּל רְכוּשָׁם אֲשֶׁר רָכָשׁוּ אִלֵּין עוֹבָדִין טָבִין דְּעָבִיד בַּר נָשׁ בְּהַאי עָלְמָא בְּאִתְּעֲרוּתָּא דְנִשְׁמָתָּא. וְאֶתּ הַנְּפֶּשׁ אֲשֶׁר עשוּ בְחָרָן, הַהוּא נְפֶּשׁ דְּהֲוַתּ בִּדְבֵקוּתָּא בְּקַדְמִיתָּא בְּחַבְרוּתָּא דְהַהִיא עָרְלָה בַּהֲדֵי גוּפָּא וְאַתְּקִין לָהּ לְבָתַּר, דְּהָא לְבָתַּר דִּתְּלֵיסַר שְׁנִין וּלְעֵילָא דְּנִשְׁמָתָּא אִתְּעָרַתּ לְאַתְּקָנָא לְגוּפָּא, תַּרְוַוייהוּ מְתַּקְּנִין לְהַהוּא נְפֶּשׁ דְּמִשְׁתַּתְּפָּא בְּתּוּקְפָּא דְנָחָשׁ וּתְּאוּבְתֵּיהּ בִּישָׁא הֲדָא הוּא דִכְתִּיב וְאֶתּ הַנְּפּשׁ אֲשֶׁר עָשׂוּ בְחָרָן.</p>\n<p>וְעִם כָּל דָּא נִשְׁמְתָּא אַתְּקֵיפַּתּ בֵּיהּ בְּהַהוּא נָחָשׁ לְתַּבְּרָא לֵיהּ בְּתּוּקְפָּא בְּשִׁעְבּוּדא דִּתְּשׁוּבָה (נ\"א בשעבודא דאורייתא, ואמשיך ליה לגבי בתי כנסיות ובתי מדרשות בגין דלא יתגבר על רוחא כדבקדמיתא) הֲדָא הוּא דִכְתִּיב ויַּעֲבוֹר (הכתוב בדף פ' אחר הגליון שורה ט\"ו) (עד כאן סתרי תורה)</p>"],[9520011188,"<p><Nonei></i>וַיֵּלֶךָ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ. אָמַר רַבִּי אֶלְעָזָר תָּא חֲזֵי, דְּהָא לָא כְּתִיב וַיֵּצֵא אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ. אֶלָּא וַיֵּלֶךְ. כְּמָא דְאַתְּ אָמֵר לֶךְ לְךָ, דְּהָא יְצִיאָה בְּקַדְמִיתָא עֲבְדוּ דִּכְתִיב וַיֵּצְאוּ אִתָּם מֵאוּר כַּשְׂדִּים לָלֶכֶת אַרְצָה כְּנָעַן, וְהַשְׁתָּא כְּתִיב וַיֵּלֶךְ וְלָא כְּתִיב וַיֵּצֵא.</p>\n<p>כַּאֲשֶׁר דִּבֶּר אֵלָיו יְיָ, דְּאַבְטַח לֵיהּ בְּכֻלְהוּ הַבְטָחוֹת. וַיֵּלֶךְ אִתּוֹ לוֹט, דְּאִתְחַבַּר עִמֵּיהּ בְּגִין לְמֵילַף מֵעוֹבָדוֹי, וְעִם כָּל דָּא לָא אוֹלִיף כּוּלֵי הַאי. אָמַר רַבִּי אֶלְעָזָר זַכָּאִין אִנּוּן צַדִּיקַיָּיא דְּאוֹלְפֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְמֵיהַךְ בְּהוּ וּלְדָחֲלָא מִנֵּיהּ מֵהַהוּא יוֹמָא דְדִינָא דְּזַמִּין בַּר נָשׁ לְמֵיהַב דִּינָא וְחוּשְׁבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>פָּתַח וְאָמַר, (איוב ל״ז:ז׳) בְּיַד כָּל אָדָם יַחְתּוֹם לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ הַאי קְרָא אוּקְמוּהָ. אֲבָל <Nonei></i>תָּא חֲזֵי בְּהַהוּא יוֹמָא דְּאַשְׁלִימוּ יוֹמוֹי דְּבַר נָשׁ לְאֲפָקָא מֵעָלְמָא, הַהוּא יוֹמָא דְּגוּפָא אִתְבַּר וְנַפְשָׁא בָּעְיָא לְאִתְפָּרְשָׁא מִנֵּיהּ, כְּדֵין אִתְיְיהִיב רְשׁוּ לְבַר נָשׁ לְמֶחֱמֵי מַה דְּלָא הֲוָה לֵיהּ רְשׁוּ לְמֶחֱמֵי בְּזִמְנָא דְּגוּפָא שָׁלְטָא וְקָאִים עַל בּוּרְיֵיהּ.</p>\n<p>וּכְדֵין קָיְימֵי עֲלֵיהּ תְּלַת שְׁלִיחָן וְחָשְׁבֵי יוֹמוֹי וְחוֹבוֹי וְכָל מַה דְּעֲבַד בְּהַאי עָלְמָא, וְהוּא אוֹדֵי עַל כֹּלָּא בְּפוּמֵיהּ, וּלְבָתַר הוּא חָתִים עֲלֵיהּ בִּידֵיהּ, הֲדָא הוּא דִכְתִיב בְּיַד כָּל אָדָם יַחְתּוֹם,</p>\n<p>וּבִידֵיהּ כֻּלְהוּ חֲתִימִין לְמֵידַן לֵיהּ (בההוא ד\"א בהאי) עָלְמָא עַל קַדְמָאֵי וְעַל בַּתְרָאֵי עַל חַדְתֵּי וְעַל עַתִּיקֵי לָא אִתְנְשֵׁי חַד מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב לָדַעַת כָּל אַנְשֵׁי מַעֲשֵׂהוּ. וְכָל אִנּוּן עוֹבָדִין דְּעֲבַד בְּהַאי עָלְמָא בְּגוּפָא וְרוּחָא הָכִי נָמֵי יָהִיב חוּשְׁבְּנָא בְּגוּפָּא וְרוּחָא עַד לָא יִפּוּק מֵעָלְמָא.</p>\n<p>תָּא חֲזֵי, כַּמָה דְחַיָּיבַיָא אַקְשֵׁי קְדַל בְּהַאי עָלְמָא הָכִי נָמֵי אֲפִלּוּ בְּשַׁעְתָּא דְּבָעֵי לְנַפְקָא מֵהַאי עָלְמָא אַקְשֵׁי קְדַל. בְגִין כָּךְ זַכָּאָה הוּא בַּר נָשׁ דְּיָלִיף בְּהַאי עָלְמָא אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְמֵיהַךְ בְּהוּ. וְחַיָּיבָא אַף עַל גַּב דְּאִסְתַּכַּל בְּהַנֵּי (נ\"א דאשתדל בהדי) צַדִּיקַיָיא אַקְשֵׁי קְדַל וְלָא בָּעֵי לְמֵילַף.</p>\n<p>וּבְגִין כָּךְ אִית לֵיהּ לְצַדִּיקָא לְמִתְקַף בֵּיהּ וְאַף עַל גַּב דְּחַיָּיבָא אַקְשֵׁי קְדַל הוּא לָא יִשְׁבּוֹק לֵיהּ וְאִית לֵיהּ לְאַתְקָפָא בִּידֵיהּ וְלָא יִשְׁבּוֹק לֵיהּ, דְּאִי יִשְׁבּוֹק לֵיהּ יְהַךְ וְיַחֲרִיב עָלְמָא.</p>\n<p>תָּא חֲזֵי, מִן אֱלִישָׁע דְּדָחָה לְגֵחֲזִי. וְכֵן בְּאַבְרָהָם כָּל זִמְנָא דְּהֲוָה לוֹט בַּהֲדֵיהּ לָא אִתְחַבַּר בַּהֲדֵי רַשִּׁיעַיָּא, כֵּיוָן דְּאִתְפְּרַשׁ מִנֵּיהּ מַה כְּתִיב וַיִּבְחַר לוֹ לוֹט אֶת כָּל כִּכַּר הַיַּרְדֵּן, וּכְתִיב וַיֶאֱהַל עַד סְדוֹם. מַה כְּתִיב בַּתְרֵיהּ וְאַנְשֵׁי סְדוֹם רָעִים וְחַטָּאִים לַיְיָ מְאֹד.</p>\n<p>אָמַר רַבִּי אַבָּא הַאי דְּאֲמַרְתְּ וַיֵּלֶךְ אַבְרָם וְלָא כְּתִיב וַיֵּצֵא אַבְרָם שַׁפִּיר הוּא. אֲבָל סוֹפָא דִקְרָא מַה כְּתִיב בְּצֵאתוֹ מֵחָרָן. אָמַר רַבִּי אֶלְעָזָר מֵחָרָן כְּתִיב וְהַהִיא יְצִיאָה מֵאֶרֶץ מוֹלַדְתּוֹ הֲוַת בְּקַדְמִיתָא:</p>"],[9520011189,"<p>וַיִּקַּח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ. מַהוּ וַיִּקַּח, אֶלָּא אַמְשִׁיךְ לָהּ בְּמִלֵּי מַעַלְיָיתָא, בְּגִין דְּלֵית לֵיהּ רְשׁוּ לְבַּר נָשׁ לְאֲפָקָא אִתְּתֵיהּ לְמֵיהַךְ בְּאַרְעָא אָחֳרָא בְּלָא רְעוּתָא דִילָהּ. וְכֵן הוּא אוֹמֵר (במדבר כ׳:כ״ה) קַח אֶת אַהֲרֹן (במדבר ג׳:מ״ה) קַח אֶת הַלְוִיִם. וּבְגִין כָּךְ וַיִּקַּח אַבְרָם מָשִׁיךְ לָהּ בְּמִלִּין וְאוֹדַע לָהּ אָרְחֵיהוֹן דְּאִנּוּן בְּנִי דָרָא כַּמָּה בִּישִׁין. וּבְגִין כָּךְ וַיִּקַח אַבְרָם אֶת שָׂרַי אִשְׁתּוֹ.</p>\n<p>וְאֶת לוֹט בֶּן אָחִיו. מָה חָמָא אַבְרָהָם לְדָבְקָא עִמֵּיהּ לוֹט, אֶלָּא בְּגִין דְּצָפָה בְּרוּחַ הַקֹּדֶשׁ דְּזַמִּין לְמֵיפַּק מִנֵּיהּ דָּוִד. וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן. אִלֵּין גֵּרִים וְגִיּוֹרוֹת דְּאַתְקִינוּ נַפְשַׁיְיהוּ, אַבְרָהָם מְגַיֵּיר גּוּבְרִין וְשָׂרָה מְגַיֶּירֶת נָשִׁין וּמַעֲלֶה עֲלֵיהוֹן כְּאִלּוּ עֲבְדוּ לְהוֹן.</p>\n<p>אָמַר רַבִּי אַבָּא אִי הָכִי כַּמָּה בְּנֵי נָשָׁא הֲווּ, אִי תֵימָא דְּכֻלְהוּ אֲזְלוּ עִמֵּיהּ. אָמַר רַבִּי אֶלְעָזָר אִין. (ובגין כלהו ד\"א ובגין כך כלהו) בְּנֵי נָשָׁא דְּהֲווּ אָזְלִין עִמֵּיהּ כֻּלְהוּ אִקְרוּן <Nonei></i>עַם אֱלֹהֵי אַבְרָהָם. וְהֲוָה מַעֲבַר בְּאַרְעָא וְלָא הֲוָה דָּחִיל דִּכְתִיב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ.</p>\n<p>אָמַר לֵיהּ רַבִּי אַבָּא אִי הֲוָה כְּתִיב וְהַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן הֲוָה אֲמִינָא הָכִי, אֶלָּא וְאֶת הַנֶּפֶשׁ כְּתִיב, אֶת לְאַסְגָּאָה זְכוּתָא דְּכֻלְהוּ נַפְשָׁאן דְּהֲווּ אָזְלֵי עִמֵּיהּ, דְּכָל מַאן דִּמְזַכֶּה לְאָחֳרָא הַהוּא זְכוּתָא תַּלְיָא בֵּיהּ וְלָא אַעֲדֵי מִנֵּיהּ, מְנָלָן דִּכְתִיב וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן, זְכוּתָא דְּאִנּוּן נַפְשָׁן הֲוָה אָזִיל עִמֵּיהּ דְּאַבְרָהָם. לֶךְ לְךָ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן מַאי טַעְמָא דְּגִלּוּיָא קַדְמָאָה דְּאִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עֲלֵיהּ דְּאַבְרָהָם פָּתַח בְּלֶךְ לְךָ, דְּהָא עַד הָכָא לָא מַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, מַאי טַעְמָא פָּתַח לֶךְ לְךָ. אֶלָּא הָא קָאֲמְרוּ דְּרָמַז בְּחוּשְׁבְּנִיהּ מְאָה דְּהָא לְמֵאָה שְׁנִין אִתְיְילִיד לֵיהּ בַּר.</p>\n<p>אֲבָל תָּא חֲזֵי, כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, בְּגִין דְּאַבְרָהָם לָא הֲוָה דָּבִיק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין כְּדְקָא חָזֵי, אָמַר לֵיהּ לֶךְ לְךָ, וְדָא רֶמֶז לְהַהוּא אֲתַר דְּבָעֵי לְאִתְקְרָבָא בַּהֲדֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִיהוּ דַּרְגָּא קַדְמָאָה לְאָעֳלָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כָּךְ לֶךְ לְךָ.</p>\n<p>וְהַאי דַרְגָא לָא יָכִיל אַבְרָהָם לְאִתְאַחֲדָא בֵּיהּ עַד דְּיֵיעוּל לְאַרְעָא דְּתַמָּן יְקַבֵל לֵיהּ לְהַהוּא דַרְגָא, כְּגַוְונָא דָא כְּתִיב, (שמואל ב ב׳:א׳) וַיִּשְׁאַל דָּוִד בַּיְיָ לֵאמֹר הַאֶעֱלֶה בְּאַחַת מֵעָרֵי יְהוּדָה וַיֹּאמֶר יְיָ עֲלֵה וַיֹּאמֶר אָנָה אֶעֱלֶה וַיֹּאמֶר חֶבְרוֹנָה. וְכִי כֵּיוָן דְּמִית שָׁאוּל וּמַלְכוּתָא אִתְחֲזֵי לְדָוִד אַמַּאי לָא קַבִּיל מַלְכוּתָא מִיָּד עַל כָּל יִשְׂרָאֵל.</p>\n<p>אֶלָּא כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, בְּגִין דְּדָוִד לֵית לֵיהּ לְקַבְּלָא מַלְכוּתָא אֶלָּא עַד דְּיִתְחַבַּר בַּאֲבָהָן דְּאִנּוּן בְּחֶבְרוֹן וּכְדֵין בְּהוּ יְקַבֵּל מַלְכוּתָא. וְעַל דָּא אִתְעַכַּב תַּמָּן שְׁבַע שְׁנִין בְּגִין דִּיקַבֵּל מַלְכוּתָא כְּדְקָא יְאוּת וְכֹלָּא בְּרָזָא דְּחָכְמְתָא וּבְגִין דִּיתַקֵּן מַלְכוּתֵיהּ. כְּגַוְונָא דָא אַבְרָהָם לָא עָאל בְּקִיּוּמָא דְּקוּדְשָׁא בְּרִיךְ הוּא עַד דְּעָאל לְאַרְעָא.</p>\n<p>חָמֵי מַה כְּתִיב וַיַּעֲבֹר אַבְרָם בָּאָרֶץ. וַיַּעֲבֹר וַיֵּלֶךְ מִבָּעֵי לֵיהּ, אֶלָא הָכָא הוּא רֶמֶז שְׁמָא קַדִּישָׁא דְּאִתְחַתִּים בֵּיהּ עָלְמָא בְּע\"ב אַתְוָון גְּלִיפָן דְּכֻלְהוּ בִּשְׁמָא דָא. כְּתִיב הָכָא וַיַּעֲבֹר וּכְתִיב הָתָם (שמות לה) וַיַּעֲבֹר יְיָ עַל פָּנָיו וַיִּקְרָא:</p>"],[9520011190,"<p>בְּסִפְרָא דְּרַבִּי יֵיסָא סָבָא כְּתִיב הָכָא וַיַּעֲבֹר אַבְרָם בָּאָרֶץ וּכְתִיב הָתָם (שמות ל״ג:י״ט) אֲנִי אַעֲבִיר כָּל טוּבִי. וְהוּא רֶמֶז לִקְדוּשָׁה דְאַרְעָא דְּאָתֵי מֵאֲתַר עִלָּאָה כְּדְקָא חָזֵי.</p>\n<p>עַד מְקוֹם שְׁכֶם עַד אֵלוֹן מוֹרֶה. מִסִּטְרָא דָא (ד\"א ל\"ג דלתתא). לְסִטְרָא דָא כְּדְקָא חָזֵי. וְהַכְּנַעֲנִי אָז בָּאָרֶץ. הָא אִתְּמָר דְּעַד כְּדֵין שָׁלְטָא חִוְיָא בִּישָׁא דְּאִתְלַטְיָא וְאַיְיתֵי לְוָוטִין עַל עָלְמָא דִּכְתִיב, (בראשית ט׳:כ״ה) אָרוּר כְּנַעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו וּכְתִיב, (בראשית נ) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו'. וְתַמָּן אִתְקְרִיב אַבְרָהָם לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם הָכָא אִתְגְּלִי לֵיהּ מַה דְּלָא הֲוָה יָדַע הַהוּא חֵילָא עֲמִיקָא לְשָׁלְטָא עַל אַרְעָא. וּבְגִין כָּךְ וַיֵּרָא מַה <Nonei></i>דְּהֲוָה מִתְכַּסֵּי מִנֵּיהּ.</p>\n<p>וּכְדֵין וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ הַנִּרְאֶה אֵלָיו, כֵּיוָן דְּאָמַר לַיְיָ מַהוּ הַנִּרְאֶה אֵלָיו. אֶלָּא הָכָא אִתְגְּלִי לֵיהּ הַהוּא דַרְגָא דְּשָׁלְטָא עַל אַרְעָא וְעָאל בֵּיהּ וְאִתְקְיַּים בֵּיהּ:</p>\n<p>וַיַּעְתֵּק מִשָּׁם הָהָרָה. מִתַּמָּן יָדַע הַר יְיָ. וְכֻלְהוּ דַּרְגִּין דִּנְטִיעִין בְּהַאי אֲתַר. וַיֵּט אָהֳלה בְּהֵ\"א כְּתִיב. פָּרִישׂ פְּרִישׂוּ וְקַבִּיל מַלְכוּ שְׁמַיָא בְּכֻלְהוּ דַּרְגִּין דְּאֲחִידָן בֵּיהּ. וּכְדֵין יָדַע דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עַל כֹּלָּא. וּכְדֵין בָּנָה מִזְבֵּחַ.</p>\n<p>וּתְרֵין מַדְבְּחָן הֲווּ, בְּגִין דְּהָכָא אִתְגְּלִי לֵיהּ דְּהָא קוּדְשָׁא בְּרִיךְ הוּא שַׁלִּיט עַל כֹּלָּא וְיָדַע חָכְמָה עִלָּאָה, מַה דְּלָא הֲוָה יָדַע מִקַּדְמַת דְּנָא. וּבָנָה תְּרִין מַדְּבְּחָן חַד לְדַרְגָּא דְּאִתְגַּלְיָא וְחַד לְדַרְגָּא דְּאִתְכַּסְיָא. תָּא חֲזֵי, דְּהָכִי הֲוָה בְּקַדְמִיתָא כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ הַנִּרְאֶה אֵלָיו וְגו'. וּלְבָתַר כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ לַיְיָ סְתָם וְלָא כְּתִיב הַנִּרְאֶה אֵלָיו. וְכֹלָּא רָזָא דְחָכְמְתָא אִיהוּ.</p>\n<p>וּכְדֵין אִתְעַטַּר אַבְרָהָם מִדַּרְגָּא לְדַרְגָּא עַד דְּסָלִיק לְדַרְגֵּיהּ הֲדָא הוּא דִכְתִיב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. דָּא דָרוֹם דְּהוּא חוּלָקֵיהּ דְּאַבְרָהָם. הָלוֹךְ וְנָסוֹעַ דַּרְגָּא בָּתַר דַּרְגָּא עַד דְּסָלִיק לְדָרוֹם וְתַמָּן אִתְקַשַּׁר כְּדְקָא יְאוּת וְסָלִיק לְדַרְגֵּיהּ דְדָרוֹם.</p>\n<p>כֵּיוָן דְּאִתְעַטַּר אַבְרָהָם בְּדַרְגּוֹי בְּאַרְעָא קַדִּישָׁא וְעָאל (בארעא) בְּדַרְגָּא קַדִּישָׁא, כְּדֵין מַה כְּתִיב וַיְהִי רָעָב בָּאָרֶץ. דְּלָא הֲווּ יָדְעֵי יְדִיעָה לְקָרְבָא לְגַבֵּי דְקוּדְשָׁא בְּרִיךְ הוּא:</p>\n<p>וַיְהִי רָעָב בָּאָרְץ, דְּעַד כְּעָן לָא הֲוָה חֵילָא דְּעַל אַרְעָא יָהִיב תּוּקְפָא וּמְזוֹנָא עַל אַרְעָא, בְּגִין דְּעַד לָא אִתְקַדְּשַׁת (נ\"א אתתקנת) וְלָא קָיְימָא בְּקִיּוּמָא. כֵּיוָן דְּחָמָא אַבְרָהָם דְּהָא הַהוּא חֵילָא דִּמְמַנָּא עַל אַרְעָא לָא יָהִיב תּוּקְפָא וְחֵילָא קַדִּישָׁא כִּדְקָחָזֵי, כְּדֵין וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם.</p>\n<p>מְנָא יָדַע אַבְרָהָם, דִּכְתִיב לְזַרְעֲךָ נָתַתִּי אֶת הָאָרֶץ הַזֹּאת. כְּדֵין יָדַע אַבְרָהָם דְּהָא אַרְעָא לָא אִתְתַּקְנָא בְּתִקּוּנָא קַדִּישָׁא אֶלָּא בְּדַרְגִּין (ידיען) קַדִּישִׁין דְּיִפְקוּן מִנֵּיהּ, וּכְדֵין יָדַע אַבְרָהָם רָזָא דְחָכְמְתָא דְּאַרְעָא לָא תִתַּקַּן בִּקְדוּשָׁה אֶלָּא כִּדְאֲמָרָן:</p>\n<p><Nonei></i><Noneb>סִתְרֵי תּוֹרָה</b> (מקב\"ה עד ויעבור הוא גליון) קוּדְשָׁא בְּרִיךָ הוּא רָמִיז חָכְמְתָּא עִלָּאָה בְּאַבְרָהָם וּבְיִצְּחָק, אַבְרָהָם דָּא נִשְׁמָתָּא לְנִשְׁמָתָּא וְאִיהִי (ס\"א אב ורם), נְשָׁמָ\"ה דא הִיא שָׂרָה. לוֹט דָּא הוּא נָחָ\"שׁ וּבַתּ זוּגֵיהּ דְּהַהוּא סמאל. רוּ\"חַ קַדִּישָׁא דָּא יִצְּחָק. נְפֶּ\"שׁ קַדִּישָׁא דָּא רִבְקָה. יֵצֶּ\"ר הָרָע דָּא רוּחַ הַבְּהֵמָה, ועל דָּא אָמַר שְׁלֹמֹה בְּחָכְמָתֵּיהּ (קהלת ג׳:כ״א) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא וְגו' נְפֶּשׁ הַבַּהֲמִיתּ דָּא נְפֶּשׁ מִסִּטְרָא דְּיֵצֶּר הָרָע.</p>\n<p>וְעַל דָּא אָמְרוּ (נ\"א דההוא) דְּאִיהִי נִשְׁמָתָּא לְנִשְׁמָתָּא אִתְּעֲרָא לְגַבְרָא בְּיִרְאָ\"ה וּבְחָכְמְ\"תָּא, נִשְׁמָתָּא אִתְּעֲרָא לְאִינִישׁ בְּבִינָה, הֲדָא הוּא דִכְתִּיב, (איוב כ״ח:כ״ח) וַיֹּאמֶר לָאָדָם הֵן יִרְאַתּ יְיָ הִיא חָכְמָה וְגו'. נִשְׁמָ\"תָּא אִתְּעֳרֵי בִּתְּשׁוּבָ\"ה דְּאִתְּקְרֵי בִּינָה וְאִקְרֵי שָׂרָ\"ה. וְרוּ\"חַ הוּא הַקּוֹ\"ל וְאִתְּקְרֵי דַעַתּ וְאִתְּעֳרֵי לְאִינִישׁ דִּי סָלִיק קָלֵיהּ בְּאוֹרַיְיתָּא, וְאִתְּקְרֵי תּוֹרָה שֶׁבִּכְתָּב, וְנְפֶּשׁ הַשִׂכְלִיתּ אִתְּעָר מִנֵּיהּ עוֹבָדִין טָבִין.</p>\n<p><Nonei></i>וּבְדוּגְמָא דָא בָּרָא גוּפָּא מֵאַרְבַּע יְסוֹדוֹתּ אֵשׁ וְרוּחַ וְעָפָּר וּמַיִם כְּגַוְונָא דְהוּא נִשְׁמָתָּא לְנִשְׁמָתָּא נְשָׁמָה וְרוּחַ וְנֶפֶּשׁ. מַיִם דָּא דְּכַר ודא הוּא מַיִם מְתִּיקֵי דִקְדוּשָׁה, וְאִיתּ מַיִם הַמְאָרְרִים דְּאִנּוּן יֵצֶּר הָרָע. אִיתּ אֶשָׁא קַדִּישָׁא נוּקְבָא וְאִיתּ אֶשָׁא נוּכְרָאָה אש זָרָה, וְעַל דָּא כְּתִּיב וְאַל יָבֹא בְּכָל עֵתּ אֶל הַקֹּדֶשׁ, דְּאִיהִי נוּקְבְתָּא מִן יֵצֶּר הָרָע. רוּחַ קַדִּישָׁא אִיהוּ דְּכַר. אִיתּ רוּחַ מְסָאֳבָא דָּא יֵצֶּר הָרָע שֶׁנֶּאֱמַר (ישעיהו י״ד:כ״ט) כִּי מִשֹׁרֶשׁ נָחָשׁ יִצֻּא צֶּפַּע. אִיתּ עָפָּר קַדִּישָׁא ואִיתּ עָפָּר מְסָאֳבָא.</p>\n<p>וְעַל דּא נִשְׁמָתָּא דְּאִיהִי תְּשׁוּבָ\"ה אַתְּקִיפַּתּ בֵּיהּ בְּהַהוּא נָחָשׁ לְתַּבְרָא לֵיהּ בְּשִׁעְבּוּדָא דִּתְּשׁוּבָה ואַמְשִׁיךָ לֵיהּ לְבָתֵּי כְנֵסִיּוֹתּ וּלְבָתֵּי מִדְרָשׁוֹתּ, וְאִנּוּן אַרְבַּע יְסוֹדֵי מִתְּפַּשְׁטִין לְכ\"ב אַתְּוָון אחה\"ע בומ\"ף גיכ\"ק דטלנ\"תּ זסשר\"ץ. (עד כאן גליון):</p>\n<p>וַיַּעֲבֹר אַבְרָם בָּאָרֶץ עַד מְקוֹם שְׁכֶם. דָּא בֵּי כְּנִישְׁתָּא אֲתַּר דְּדִיּוּרָא דִּשְׁכִינְתָּא תַּמָּן כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ח:כ״ב) ואֲנִ\"י נָתַּתִּי לְךָ שְׁ'כֶ'ם' אֶחָד, דָּא שְׁכִינְתָּא דְּאִתְּחֲזֵי לֵיהּ הוֹאִיל וְאִתְּקְרֵי צַּדִּיק, דְּהָא צֶּדֶק לָאו דִּיּוּרָהּ אֶלָּא בַּהֲדֵי צַּדִּיק, וְדָא הוּא עַד מְקוֹם שְׁכֶם. עַד אֵלוֹן מוֹרֶה אֵלּוּ בָּתֵּי מִדְרָשׁוֹתּ דְּאוֹלְפִּין וּמוֹרִים תַּמָּן תּוֹרָה בָּרַבִּים.</p>\n<p>וְהַכְּנַעֲנִי אָז בָּאָרֶץ. כְּדֵין אִתְּבַּסַּם וְאִתְּתַּקַּן יֵצֶּר הָרָע בְּגוּפָּא בְּעַל כָּרְחֵיהּ. דְּסַגִּיאִין שְׁמָהָן אִיתּ לֵיהּ, וּבְגִינֵי כָךָ (אתהדר) אִדְכַּר בִּשְׁמָהָן סַגִּיאִין. אָז בָּאָרֶץ ודּאי וְאִתְּכַּפְּיָא בְּהַאי, בְּגִין דִּכְדֵין אִיהוּ גוּפָּא בְּזִמְנָא דְּלָא אִתְּעֲבַר מִנִּיהּ הַהוּא נָחָשׁ כָּל כָּךָ, בְּגִין דְּבֵקוּתָּא דְּגוּפָּא כְּדֵין הַכְּנַעֲנִי אָז בָּאָרֶץ, אַמַּאי אִקְרֵי כְּנַעֲנִי, דְּאַסְחַר גּוּפָּא לְדִינִין בִּישִׁין.</p>\n<p>וְנִשְׁמָתָּא קָיְימָא בְּהַאי עָלְמָא (לאתתקנא אורחוי דגופא) כְּדְקָא יְאוּתּ בְּגִין לְמִזְכֵּי בָּהּ, לְבָתַּר כַּד נָפְּקַתּ מֵהַאי עָלְמָא אִי זָכָאתּ סָלְקָא לְאַתְּרָהּ דְּנָפְּקַתּ מִתַּמָּן דִּכְתִּיב אֶל מְקוֹם הַמִּזְבֵּחַ אשר עָשָׂה שָׁם בָּרִאשׁוֹנָה וּכְתִּיב אֶל הַמָּקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלה בַּתְּחִלָּה. אָהֳלה בְּהֵ\"א.</p>\n<p>וְהַשְׁתָּא אִיהִי קָיְימָא בֵּין לְסָלְקָא לְעֵילָא וּבֵין לְנָחֲתָּא לְתַּתָּא. (דכתיב) בֵּין בֵּיתּ אל וּבֵין הָעָי. אִי זָכָאתּ סָלְקָא אל מְקוֹם הַמִּזְבֵּחַ, אֲשֶׁר עָשָׂה שָׁם וְגו'. מַאן עשה וּמַאן מִזְבֵּחַ. אֶלָּא אֲשֶׁר עָשָׂה שָׁם, דָא קוּדְשָׁא בְּרִיךָ הוּא. דְּאִיהוּ עָבַד תַּמָּן הַאי מִזְבֵּחַ וְאַתְּקִין לָהּ על תְּרֵיסַר אַבְנִין לְמִסְפַּר שִׁבְטֵי בְּנֵי יַעֲקֹב אשר הָיָה דְּבַר יְיָ אֵלָיו לֵאמֹר יִשְׂרָאֵל יִהְיְה שְׁמֶךָ ודַּאי.</p>\n<p>וּמִזְבֵּחַ דָּא עָשָׂה שָׁם בָּרִאשׁוֹנָה כַּד אִתְּבְּרֵי עָלְמָא עִלָּאָה (עלאה) טְמִירָא לְכָל עָלְמִין, וּמִיכָאֵ\"ל כַּהֲנָא רַבָּא קָאִים וּמַקְרִיב עֲלָהּ קָרְבָּנִין דְּנִשְׁמָתִּין, כֵּיוָן <Nonei></i>דְּנִשְׁמָתָּא סָלְקָא תַּמָּן מַה כְּתִּיב וַיִּקְרָא שָׁם אַבְרָם בּשם יְיָ, נִשְׁמָתָּא קָארֵי תַּמָּן וְאִצְּרִירָא בִּצְּרוֹרָא דְחַיֵּי.</p>\n<p>וְכָל דָּא, אִי זַכָּאָה בְּהַאי עָלְמָא לְאַתְּקָנָא גּוּפָּא כְּדְקָא יָאוֹתּ וּלְאִכַּפְּיָא (ולאספיא) תּוּקְפָּא דְּהַהוּא לָטְיָיא, עַד דְּאִתְּפָּרְשָׁא מִנֵּיהּ מַה כְּתִּיב, וַיְהִי רִיב בֵּין רוֹעֵי מִקְנֵה אַבְרָם וּבֵין רוֹעֵי מִקְנֵה לוֹט (דא יצר הרע), דְּבְּכָל יוֹמָא וְיוֹמָא בְּהַאי עָלְמָא, אִנּוּן סִיעָן וּמַנְהִיגִי דְּנִשְׁמָתָּא, וְאִנּוּן סִיעָן וּמַנְהִיגִין דְּיֵצֶּר הָרָע, אִנּוּן בְּקִטְרוּגָא מְקַטְרְגִין אִלֵּין בְּאִלֵּין, וְכָל שָׁיְיפִּין דְּגוּפָּא בְּצַּעֲרָא בֵּינַיְיהוּ בֵּין נִשְׁמָתָּא וְהַהוּא נָחָשׁ דְּקָא מַגִּיחִין קְרָבָא בְּכָל יוֹמָא.</p>\n<p>מַה כְּתִּיב וַיֹּאמֶר אַבְרָם אל לוֹט. נִשְׁמָתָּא אֲהַדְּרָא לְגַבֵּי יֵצֶּר הָרָע וְאָמַר לֵיהּ, אַל נא תְּהִי מְרִיבָה בֵּינִי וּבֵינְיךָ וּבֵין רוֹעַי וּבֵין רוֹעֶיךָ, סִטְרִין דִּילִי וְסִטְרִין דִּילָךָ. כִּי אֲנָשִׁים אַחִים אֲנַחְנוּ, יִצֶּר טוֹב וְיֵצֶּר הָרָע קְרֵיבִין דָּא בְּדָא, דָּא לִימִינָא וְדָא לִשְׂמָאלָא.</p>\n<p>הֲלא כָל הָאָרֶץ לְפָּנְיךָ הִפָּרֶד נָא מֵעָלַי. סַגִּיאִין חַיָּיבַיָא אִנּוּן בְּעָלְמָא, זִיל וְשׁוּט אֲבַּתְּרַיְיהוּ וְאִתְּפְּרַשׁ מֵעִמִּי. אִם הַשְׂמֹאל וְאֵימִינָה וְגו'. וְאוֹכַח לֵיהּ וְאָעִיק לֵיהּ בְּכַמָּה קְרָבִין דְּעָבִיד בַּהֲדֵיהּ בְּכָל יוֹמָא, עד דִּכְתִּיב וַיִּפָּרְדוּ אִישׁ מֵעַל אָחִיו.</p>\n<p>כֵּיוָן דְּמִתְּפָּרְשִׁין דָּא מִן דָּא מַה כְּתִּיב, אַבְרָם ישב בְּאֶרֶץ כְּנָעַן. אִתְּיַשְׁבַתּ נִשׁמתָּא בְּאִנּוּן צַּדִּיקַיָא בְּיִשׁוּבָא טַב בִּשְׁלָם. וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר, הַהוּא לָטְיָא מְקַטְרְגָא אָזִיל לְקַטְרְגָא וּלְאִתְּחַבְּרָא בְּאֲתַּר דְּחַיָּיבַיָא תַּמָּן דִּכְתִּיב וַיֶּאֱהַל עַד סְדוֹם. מַה כְּתִּיב בַּתְּרֵיהּ וְאַנְשֵׁי סְדוֹם רָעִים וְחַטָאִים לַיְיָ מְאֹד. תַּמָּן שַׁרְיָא וְשָׁוִי דִּיּוּרֵיהּ בֵּינַיְיהוּ לְאִתְּחַבְּרָא בְּהוּ לְאַסְטָאָה לוֹן וּלְאוֹבָדָא לוֹן. (ואברהם בעובדין טבין בתשובה באורייתא) (חסר) (ס\"א) בְּעוֹבָדִין בִּישִׁין.</p>\n<p>כֵּיוָן דְּאִשְׁתְּאָרַתּ נִשְׁמָתָּא בְּלָא מְקַטְרְגָא וְאִתְּדְּכֵי גוּפָּא מֵהַהוּא זוּהֲמָא, מִיָּד קוּדְשָׁא בְּרִיךָ הוּא אַשְׁרֵי דִיּוּרֵיהּ בַּהֲדֵיהּ וְיָרִיתּ אַחְסַנְתָּא עִלָּאָה וְתַּתָּאָה, וְאִיתּ לֵיהּ נַיְיחָא בֵּין צַּדִּיקַיָא, והַהוּא לָטְיָא בֵּין אִנּוּן רַשִׁיעַיָיא חָטָאן בַּהֲדֵיהּ, עַד דְּלָא הֲוָה פּוּרְקָנָא לְחוֹבַיְיהוּ.</p>\n<p>מַה כְּתִּיב וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו. וַיִּשְׁמַע אַבְרָם דָּא נִשְׁמָתָּא דְּאִשְׁתְּאָרַתּ בְּדַכְיוּ בְּגוּפָּא. כִּי נִשְׁבָּה אָחִיו, דָּא יֵצֶּר הָרָע דְּנִשְׁבָּה בֵּין אִנּוּן חַיָּיבַיָא בְּחוֹבִין סַגִּיאִין. וַיָּרֶק אֶתּ חֲנִיכָיו יְלִידֵי בֵיתּוֹ, אִלֵּין אִנּוּן צַּדִּיקַיָיא דְּלָעָאן בְּאוֹרַיְיתָּא דְּאִנּוּן שַׁיְיפֵּי דְגוּפָּא זְרִיזִין לְמֵיהַךָ בַּהֲדֵיהּ י\"ח וּשֹלשׁ מֵאוֹתּ, אִלֵּין רמ\"ח שַׁיְיפִּין דְּגוּפָּא, ושִׁבְעִין, דְּרָזָא דְּנִשְׁמָתָּא דְּנָפְּקָא מִתַּמָּן (ע\"כ). בְּכלָּא אִזְדְּרָז לְמֵהַךָ תַּמָּן לְגַבֵּי אִנּוּן חַיָּיבַיָא לְאֲתָּבָא לוֹן (מחובוי) מֵחוֹבֵיהוֹן.</p>\n<p>מַה כְּתִּיב ויִּרְדֹּף עַד דָּן. רָדִיף אֲבַּתְּרַיְיהוּ וְאוֹדַע לוֹן דִּינא דְּהַהוּא עָלְמָא וְעוֹנְשָׁא דְּגֵיהִנֹּם, וְלָא יָהִיב דְּמִיכוּ לְעֵינֵיהּ בִּימָמָא וּבְלֵילְיָא עד דְּאוֹכַח לוֹן לְאִנּוּן חַיָּיבִין וְאָתִּיב לוֹן בִּתְּיוּבְתָּא לְגַבֵּי קוּדְשָׁא בְּרִיךָ הוּא. מַה כְּתִּיב וַיָּשֶׁב אֶתּ כָּל הָרְכוּשׁ, אָתִּיב לוֹן בִּתְּיוּבְתָּא שְׁלֵימָא כְּדְקָא יְאוּתּ.</p>\n<p>וְגַם אֶתּ לוֹט אָחִיו וְגו'. אֲפִּלּוּ לְהַהוּא יֵצֶּר הָרָע אַתְּקִיף בַּהֲדֵיהּ עַד דְּאַכְפְּיֵיה בְּעַל כָּרְחֵיהּ (ולא) וְאַמְתִּיק לֵיהּ כְּדְקָא חָזֵי. כּלָּא אָתִּיב בִּתְּיוּבְתָּא שְׁלֵימָתָּא כְּדְקָא יְאוּתּ, בְּגִין דְּלָא אִשְׁתְּכַח יְמָמָא וְלֵילְיָא עַד דְּאוֹכַח לוֹן וּרְדַף לוֹן עַל הַהוּא חוֹבָא דְּחָאבוּ עַד דְּתָּאבוּ בִּתְּיוּבְתָּא שְׁלֵימָתָּא כִּדְקָחָזוּ.</p>\n<p>אַהֲדַרְנָא לְמִילֵּי קַדְמָאֵי דְּפָּרְשָׁתָּא. כְּתִיב (שיר השירים ג׳:ג׳) מְצָּאוּנִי הַשׁוֹמְרִים הַסּוֹבְבִים בָּעִיר וגו'. (תנן כדוגמת דרמיז באברהם ויצחק ושרה ורבקה ידו\"ד, כדוגמא דא רמיז בהאי קרא (רות א׳:ב׳) ושם האיש אלימלך ושם אשתו נעמי ושם שני בניו מחלון וכליון אפרתים. אלימל\"ך דא נשמתא לנשמתא.) נָעְמִ\"י דָּא נְשָׁמָה, וְאַמַּאי אִתְּקְרֵי נָעְמִי, מִשׁוּם (תהילים צ׳:י״ז) וִיהִי נֹעַם יְיָ אֱלֹהֵינוּ. מַחְלוֹן דָּא רוּחָא קַדִּישָׁא, וְלָמָּה אִתְקְרֵי מַחְלוֹן דְּמָחַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. רוּ\"ת דָּא נֶפֶשׁ קַדִּישָׁא, וְלָמָּה אִתְקְרֵי רוּ\"ת עַל שֵׁם תּוֹ\"ר. כִלְיוֹ\"ן דָּא רוּחָ\"א דְבְּעִירָ\"א, ועַל דָּא אָמַר שְלמֹה עָלָיו הַשָׁלוֹם (קהלת ג׳:כ״א) רוּחַ הַבּהמה דָּא יֵצֶ\"ר הָרָ\"ע. עָרְפָּ\"ה דָּא נַפְשָׁא דִּשְׂמָאלָא בַת זוּגֵיהּ שֶׁל יֵצֶר הָרָע. וְלָמָּה אִתְקְרֵי עָרְפָּה מִשׁוּם כִּי עַם קשה עֹרֶף הוּא. אִי זָכָה בַּר נָשׁ סָלְקָא נִשְׁמָתָּא עִלָּאָה, וְאִי לָאו מִסְתַּלְּקֵי אִנּוּן דוֹבְרֵי נִשְׁמָתָּא וְרוּחָא וְאִשְׁתָּאַר נִשְׁמָתָּא עִלָּאָה וְנְפֶּשׁ הַשִׂכְלִיתּ, מַה כְּתִּיב, (רות א׳:ז׳) וַתֵּצֵּא מִן הַמָּקוֹם אֲשֶׁר הָיתָּה שָׁמָּה וּשְׁתֵּי כַלוֹתֶּיהָ עִמָּהּ וַתֹּאמֶר נָעֳמִי לִכַלוֹתֶּיהָ שֹׁבְנָה בְנֹתַּי וְגו'. וַתֹּאמֶר רוּתּ אַל תִּפְּגְּעִי בִי וְגו' וְעָרְפָּה שָׁבָה לְעַמָּהּ וּלְאֱלהֶיהָ. תְּנַן עָבַד קוּדְשָׁא בְּרִיךָ הוּא יְרוּשְׁלֵם לְעֵילָא כְּגַוְונָא דִּיְרוּשָׁלַםִ דִּלְתַּתָּא, בְּשׁוּרִין וּמִגְדָּלִין וּפִּתְּחִין פְּתִּיחִין, וְאִנּוּן חוֹמוֹתּ דְּתַּמָּן אִיתּ עֲלַיְיהוּ נָטְרִין <Nonei></i>דְּנָטְרֵי תַּרְעֵי דְּאִנּוּן חוֹמוֹתּ דִּכְתִּיב, (ישעיהו ס״ב:ו׳) עַל חוֹמוֹתַּיִךָ יְרוּשָׁלַיִם הִפְּקַדְתִּי שׁוֹמְרִים וְגו'. וּמִיכָאֵל כַּהֲנָא רַבָּא עִלָּאָה מִכֻּלְהוּ נָטְרֵי תַּרְעֵי דְּאִנּוּן חוֹמוֹתּ.</p>\n<p>נְשָׁמָ\"ה (דאתקרי נעמ\"י) כַּד נָפְּקַתּ מֵהַאי עָלְמָא, אִי זָכָאתּ עָאלַתּ בְּגִנְתָּא דְעֵדֶן דְּאַרְעָא דְּנָטַע קוּדְשָׁא בְּרִיךָ הוּא לְרוּחֵיהוֹן דְּצַּדִּיקַיָיא כְּגַוְונָא דְהַהוּא גִּנְתָּא דְּעֵדֶן דִּלְעֵילָא. וְתַּמָּן כָּל צַּדִּיקַיָיא דְּעָלְמָא.</p>\n<p>וְכַד נִשְׁמָתָּא נָפְּקַתּ מֵהַאי עָלְמָא, עָאלַתּ בִּמְעַרְתָּא דְּכָפֶּלְתָּא דְּתַּמָּן אִיהִי פִּתְּחָא דְּגַּן עֵדֶן. פָּגְעַתּ בְּאָדָם הָרִאשׁוֹן וּבְאִנּוּן אֲבָהָן דְּתַּמָּן, אִי זָכָאתּ אִיהִי, חָדָאן בָּהּ וּפָּתְּחִין לָהּ פִּתְּחִין וְעָאלַתּ. ואִי לָא דַּחְיָין לָהּ לְבַר. (ומה היא אמרה כד דחיין לה לבר (שיר השירים ג׳:ג׳) מצאוני השומרים וגו' אזלת. לבתר דאזלת תמן מקמי דאתיא לעלמא דא ויהיבת נר על רישיה שנאמר (איוב כ״ט:ג׳) בהלו נרו עלי ראשי כל מאן דחזון לה מזדעזעין ואמרי הזאת נעמי. אתיבת היא ואמרה (רות א׳:כ׳) אל תקראנה לי נזעמי קראן לי מרה וגו'. אני מלאה הלכתי בההוא אתר וריקם השיבני יי בלא תורה ובלא מעשים טובים דאעיל לי בגופא בישא למה תקראנה לי נעמי ויי ענה בי). ואִי ז זָכָאתּ עָיְילַתּ לְגִנְתָּא דְעֵדֶן, כֵּיוָן דְּעָיְילַתּ יָתְּבָא תַּמָּן בְּגִנְתָּא (אזדווגת באלימלך דא מחלון דדא רוח אזדווג ברות דדא נפש השכלית) וְאִתְּלַבְּשׁוּ (ד\"א ואתלבשת) תַּמָּן בִּלְבוּשָׁא דְּדִיוּקְנָא דְּהַאי עָלְמָא וְאִתְּעַדְּנַתּ תַּמָּן.</p>"],[9520011191,"<p>סִתְּרָא דְסִתְּרִין לַחֲכִימֵי לִבָּא אִתְּמָסַר. (ארבע) תְּלַתּ דַּרְגִּין אִנּוּן דְּאֲחִידָן דָּא בְּדָא, ואִלֵּין אִנּוּן נֶפֶּשׁ (נשמתא לנשמתא נשמתא עלאה דאתקרי יו\"ד) רוּ\"חַ וּנְשָׁמָה. (נפ\"ש) נְפֶּשׁ אִיהוּ חֵילָא דְּגוּפָּא אִתְּבְּנֵי מִנֵּיהּ. דְּכַד בַּר נָשׁ אִתְּעַר בְּהַאי עָלְמָא לְאִזְדַּוְוגָא בְּנוּקְבֵיהּ כָּל שַׁיִיפֵּי מִסְתַּכְּמֵי (נ\"א מתכנשי) ֹ וּמִתְּתַּקְנֵי לְאִתְּהַנָּאָה (לנשמה) תַּמָּן, וְהַהוּא נְפֶּשׁ וּרְעוּתָּא דִילֵיהּ אִסְתַּכַּם בֵּיהּ בְּהַהוּא עוֹבָדָא (ממש) וּמָשִׁיךָ לֵיהּ לְהַהוּא נְפֶּשׁ וְאָעִיל לֵיהּ תַּמָּן בְּהַהוּא זַרְעָא דְּאוֹשִׁיד.</p>\n<p>וּמִגּוֹ רְעוּתָּא וּמְשִׁיכוּ דְנַפְּשָׁא דְּמָשִׁיךָ תַּמָּן, אִתְּמְשַׁךָ חֵילָא אוֹחֲרָא תַּמָּן מֵאִנּוּן דַּרְגִּין דְּאִתְּקְרוּן אִישִׁי\"ם, וְעָאל כּלָּא בִּמְשִׁיכוּ דְּהַהוּא זַרְעָא, וְאִתְּבְּנֵי מִנֵּיהּ גּוּפָּא. וְדָא אִיהוּ חֵילָא קַדְמָאָה תַּתָּאָה דְּאִנּוּן (ארבע) תְּלַתּ.</p>\n<p>וּבְגִין דְּהַאי (נשמתא לנשמתא) נְפֶּשׁ אַקְרִיב בִּדְבֵקוּתָּא וִיסוֹדָא דְגוּפָּא, קָרְבָּנָא דְּאִתְּקְרִיב לְכַפָּרָא עַל נִשְׁמָתָּא אִתְּיְהִיבַתּ חוּלָקָא לְאִנּוּן דַּרְגִּין דְּאִישִׁי\"ם (דאתקרון רוח ונפש השכלית) בְגִין דִּמְשִׁיכוּ דְּחוּלְקָא דְּהַהוּא (נשמה) נְפֶּשׁ אָתֵּי מִנַּיְיהוּ. וְהַיְינוּ דִכְתִּיב אֶתּ קָרְבָּנִי לַחְמִי לְאִשַׁי (מהו לחמי לאשי דיהיב מזונא לאשי ודא הוא שפע מאור דאנון מתהנן מזיו השכינה) בְּגִין דְּהוּא כַּפָּרָה דְּנְפֶּשׁ נָטְלֵי חוּלָקֵיהוֹן. וְכַד מִיתּ בַּר נָשׁ בְּהַאי עָלְמָא, הַהִיא נְפֶּשׁ לָא אִתְּעֲדֵי מִן קִבְרָא לְעָלְמִין, וּבְחֵילָא דָא יָדְעֵי מֵתַּיָיא וּמִשְׁתָּעוּ דָּא עִם דָּא.</p>\n<p>רוּחַ אִיהוּ דִּמְקַיֵּים לַנְּפֶּשׁ בְּהַאי עָלְמָא. וְאִיהוּ מְשִׁיכוּ דְאִתְּעֲרוּתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא כַּד אִנּוּן בְּתִּיאוּבְתָּא חָדָא. וּכְדֵין אִתְּעָרַתּ לְגַבֵּי דְכוּרָא בְּתִּיאוּבְתָּא דִילָהּ, לְהַאי רוּחַ כְּגַוְונָא דְּנוּקְבָא לְגַבֵּי דִּלְתַּתָּא אַשְׁדִיאַתּ זַרְעָא בְּתִּיאוּבְתָּא לְגַבֵּי דְכוּרָא. וְסִתְּרָא דָא (כד אשדיאת שפע בתיאובתא לגבי נוקבא והכא רזא) (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אל הָאֱלהִים אֲשֶׁר נְתָּנָהּ.</p>\n<p>וְהַאי רוּ\"חַ (ונפ\"ש ונשמ\"ה ונשמת\"א לנשמתא כד) נָפְּקָא מֵהַאי עָלְמָא (ואתפרשת מנפש) (אתפרשן י\"ה אסתלק לגנתא דעדן בשמיא עלאה ומתלבש בדיוקנא עלאה מרקמא בכל גוונין) עָאל לְגִנְתָּא דְעֵדֶן דִּבְהַאי עָלְמָא (תתאה), וְאִתְּלַבַּשׁ תַּמָּן גּוֹ אֲוירָא דְגִנְתָּא כְּמָה דְּמִתְּלַבְּשֵׁי מַלְאֲכֵי עִלָּאֵי כַּד נָחֲתִּין לְהַאי עָלְמָא. בְּגִין דְּאִנּוּן מֵהַהוּא רוּחַ הֲווּ דִּכְתִּיב, (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹתּ וגו'.</p>\n<p>אוּף הָכִי רוּחא מִתְּלַבָּשׁ בְּגַּן עֵדֶן דְאַרְעָא בְּדִיוּקְנָא דְהַאי עָלְמָא וְתַּמָּן אִתְּעַדְּנַתּ בְּכָל עִדּוּנִין, בְּגַּן עֵדֶן דָּא אִיתּ צִּיּוּרִין וְדִּיוּקְנִין דְהַאי עָלְמָא. וְאִיתּ צִּיּוּרִין וְדִּיוּקְנִין דְעָלְמָא עִלָּאָה, וְתַּמָּן כָּל אִנּוּן צַּדִּיקַיָּיא אָזְלִין וּמִתְּעַדְּנִין תַּמָּן, וּבְרֵישׁ יַרְחֵי וְשַׁבַּתֵּי אִנּוּן בָּעָאָן לְסָלְקָא לְעֵילָא. (דיוקנא דא מרו\"ח וא\"ש דבהאי עלמא ובדיוקנא דא אתעדנו בכל עדונין ובכל זמנ\"י וירח\"י ושבת\"י אסתלקו רו\"ח ונפ\"ש ומתפשטי מהאי גופא ומתלבשי בדיוקנא עלאה בגן עדן דלעילא מרקמא בכל גוונין. באן אתר הוא י\"ה בלבושא דיליה ואזדווגו כחדא ידו\"ד ואנון נהנין מאור השכינה) וּבִמְצִּיעוּתּ גִּנְתָּא אִיתּ עַמּוּדָא חָדָא מֵרֻקָּמָא בְּכָל גְּוָונִין. וְהַהוּא רוּחַ כַּד בָּעָא לְסָלְקָא, אִתְּפַּשַׁט תַּמָּן מֵהַהוּא לְבוּשָׁא (ונפשא אשתארת תמן בגופא) וְעָאל גּוֹ הַהוּא עַמּוּדָא (וסלקת) וְסָלִיק לְעֵילָא גּוֹ הַהוּא אֲתַּר דְּנָפְּקַתּ מִנֵּיהּ, כְּדִכְתִּיב וְהָרוּחַ תָּשׁוּב וְגו'.</p>\n<p>וְנָטִיל לָהּ מִיכָאֵל כַּהֲנָא רַבָּא וּמַקְרִיב לָהּ קָרְבַּן בּוּסְמִין קַמֵּי קוּדְשָׁא בְּרִיךָ הוּא, (ואתת) וְיָתְּבָא תַּמָּן וּמִתְּעַדְּנָא בְּהַהוּא צְּרוֹרָא דְחַיֵּי (ישעיהו ס״ד:ג׳) דְּעַיִן לֹא רָאָתָּה אֱלהִים זוּלָתְּךָ וְגו'. לְבָתַּר <Nonei></i>נָחֲתָּא לְגוֹ גִנְתָּא דְאַרְעָא וּמִתְּעַדְּנָא בְּכָל עִדּוּנִין, וְאִתְּלַבְּשַׁתּ בְּהַהוּא לְבוּשָׁא (ואזדווגא בנפש דידיה) וְיָתְּבָא תַּמָּן בְּטוּרָא עַל חַד תְּרֵין מִכַּמָּה דְּהֲוַתּ בְּקַדְמִיתָּא. (ודא הוא בחול ואסתלקא בישיבות דגן עדן ומתעסק באורייתא ובכל רישי ירחי וזמני ושבתי נחתא אזדווגת בנפש).</p>\n<p>נְשָׁמָה הִיא חֵילָא עִלָּאָה על כָּל אִלֵּין, וְאִיהִי מֵחֵילָא דִדְכוּרָא רָזָא דְאִילָנָא דְחַיֵּי. וְדָא סָלְקָא לְעֵילָא מִיָּד. וְכָל הַנֵּי (ד\"א אנון) תְּלַתּ דַּרְגִּין מִתְּקַשְׁרִין כְּחֲדָא דָּא בְּדָא. וְכַד מִתְּפָּרְשָׁן כֻּלְהוּ סָלְקִין ותָּבִין לְהַהוּא אֲתַּר דְּנַפְּקוּ מִנֵּיהּ.</p>\n<p>כַּד הַאי רוּחָא נָפְּקַתּ מֵהַאי עָלְמָא וְעָאלַתּ בְּגוֹ מְעַרְתָּא דְּאָדָם וְאֲבָהָן תַּמָּן, אִנּוּן יָהֲבִין לָהּ פִּנְקָס סִימָנָא וְעָאלַתּ לְגַבֵּי גִנְתָּא דְעֵדֶן, קְרִיבַתּ תַּמָּן וְאַשְׁכָּחַתּ כְּרוּבִים וְהַהוּא לַהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ. אִי זָכָאתּ חָמָאן פִּנְקָס סִימָנָא וּפָּתְּחִין לָהּ פִּתְּחָא וְעָאלַתּ. וְאִי לָא דַּחְיָין לָהּ לְבַר.</p>\n<p>וְיָתְּבָא תַּמָּן, כָּל הַהוּא זִמְנָא דְּיָתְּבָא מִתְּלַבְּשָׁא תַּמָּן בְּדִיוּקְנָא דְהַאי עָלְמָא. וּבְרֵישׁ יַרְחֵי וְשַׁבַּתֵּי כַּד בָּעָאתּ לְסַלְקָא. צַּדִּיקַיָּיא דִּבְגִנְתָּא דְעֵדֶן יַהֲבִין לָהּ פִּנְקָס סִימָנָא, וְסָלְקַתּ בְּהַהוּא עַמּוּדָא וּפָּגְעַתּ בְּאִנּוּן נָטְרֵי חוֹמוֹתּ יְרוּשְׁלֵם, אִי זָכְאָה פָּתְּחִין לָהּ פִּתְּחָא וְעָאלַתּ. וְאִי לָא נָטְלִין מִינָהּ הַהוּא פִּנְקָס וְדַחְיָין לָהּ לְבַר. תָּבַתּ לְגִנְתָּא ואָמְרָה (שיר השירים ג׳:ג׳) מְצָּאוּנִי הַשׁוֹמְרִים הַסּוֹבְבִים בָּעִיר וְגו' נָשְׂאוּ אֶתּ רְדִידַי מֵעָלַי, דָּא אִיהוּ פִּנְקָס סִימָנָא דְּנָטְלֵי מִנֵּיהּ (ד\"א מינה). שׁוֹמְרֵי הַחוֹמוֹתּ אִלֵּין אִנּוּן נָטְרֵי חוֹמוֹתּ יְרוּשָׁלַיִם. (כדוגמא דא נשמתא לנשמתא אתפשט מההוא לבושא דלעילא ומסתלק לעילא לעילא ואתהני מאור השכינה. ונשמה (ס\"א ונפשא) אשתארת בגופא (שמות קמא ב) ובכל רישי ירחי וזמני ושבתי נחתא נשמה לנשמה ומזדווגא לנשמה דאשתארת בגופא ומזדווגא בנשמה ודיוקנא דגנתא דעדן דלתתא הוא אש ומים שנאמר שמים. עד הכא רוחא דשמאלא היורדת למטה אזלת לדרגא דיליה ונפש דיליה אשתארא בגופא דארעא דכתיב, (איוב י״ד:כ״ב) אך בשרו עליו יכאב וגו'. ועל דא אמרו דמתיא ידעי בעלמא דאתי מיקרא דצדיקייא ומעלמא תתאה ומשתעיין דא עם דא) (עד כאן סתרי תורה):</p>"],[9520011192,"<p>וַיֵּרֶד אַבְרָם מִצְרַיְמָה לָגוּר שָׁם. מַאי טַעְמָא לְמִצְרַיִם. אֶלָּא בְּגִין דְּשָׁקִיל לְגַן יְיָ. דִּכְתִיב כְּגַן יְיָ כְּאֶרֶץ מִצְרַיִם. דְּתַמָּן שָׁקִיל וְנָחִית חַד נַהֲרָא דְּאִיהוּ לְיָמִינָא דִּכְתִיב, (בראשית ב׳:י״א) שֵׁם הָאֶחָד פִּישׁוֹן הוּא הַסּוֹבֵב אֶת כָּל אֶרֶץ הַחֲוִילָה אֲשֶׁר שָׁם הַזָּהָב.</p>\n<p>וְאַבְרָהָם כֵּיוָן דְּיָדַע וְעָאל בְּהֵימְנוּתָא שְׁלֵימָתָא. בָּעָא לְמִנְדַע כָּל אִנּוּן דַּרְגִּין דְּאִתְאַחֲדָן לְתַתָּא. וּמִצְרַיִם הֲוָה נָטִיל מִיָּמִינָא (ד\"א לימינא) וּבְגִין כָּךְ נָחַת לְמִצְרַיִם. וְתָּא חֲזֵי, כַּפְנָא לָא אִשְׁתְּכַח בְּאַרְעָא אֶלָּא כַּד מִסְתַּלְּקֵי רַחֲמֵי מִן דִּינָא:</p>\n<p>וַיְהִי כַּאֲשֶׁר הִקְרִיב לָבֹא מִצְרָיְמָה. אָמַר רַבִּי אֶלְעָזָר כַּאֲשֶׁר הִקְרִיב, כַּאֲשֶׁר קָרַב מִבָּעֵי לֵיהּ. מַאי כַּאֲשֶׁר הִקְרִיב, אֶלָּא כְּדִכְתִיב, (שמות י״ד:י׳) וּפַרְעֹה הִקְרִיב דְּאִיהוּ אַקְרִיב לְהוּ לְיִשְׂרָאֵל לְתִיוּבְתָּא. אוּף הָכָא הִקְרִיב, דְּאַקְרִיב גַּרְמֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת. לָבֹא מִצְרָיְמָה לְאַשְׁגָּחָא בְּאִנּוּן דַּרְגִּין וּלְאִתְרַחֲקָא מִנַּיְיהוּ וּלְאִתְרַחֲקָא מֵעוֹבְדֵי מִצְרַיִם.</p>\n<p>אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, כֵיוָן (ס\"א בגין) דְּנָחַת אַבְרָהָם לְמִצְרַיִם בְּלָא רְשׁוּ, אִשְׁתַּעְבִּידוּ בְּנוֹי בְּמִצְרַיִם אַרְבַּע מְאָה שְׁנִין, דְּהָא כְּתִיב וַיֵּרֶד אַבְרָם מִצְרָיְמָה. וְלָא כְּתִיב רֵד מִצְרָיִם, וְאִצְטָעַר כָּל הַהוּא לֵילְיָא בְּגִינָהּ דְּשָׂרָה.</p>\n<p>וַיֹּאמֶר אֶל שָׂרָה אִשְׁתּוֹ הִנֵּה נָא יָדַעְתִּי כִּי אִשָּׁה יְפַת מַרְאֶה אָתְּ. וְכִי עַד הַהִיא שַׁעֲתָא לָא הֲוָה יָדַע אַבְרָהָם דְּאִשָּׁה יְפַת מַרְאֶה הֲוַת. אֶלָּא הָא אוּקְמוּהָ דְּעַד הַהִיא שַׁעֲתָא לָא אִסְתַּכַּל בְּדִיוּקְנָא דְשָׂרָה בִּסְגִיאוּת צְנִיעוּתָא דְּהֲוַת בֵּינֵיהוֹן, וְכַד קָרִיב לְמִצְרַיִם אִתְגַלְיָיא אִיהִי וְחָמָא בָּהּ.</p>\n<p>דָּבָר אַחֵר בְּמָּה יָדַע, אֶלָּא עַל יְדָא דְּטוֹרַח אוֹרְחָא בַּר נָשׁ מִתְבַּזֶּה וְהִיא קָיְימָא בְּשַׁפִּירוּ דִילָהּ וְלָא אִשְׁתַּנִּי. דָּבָר אַחֵר הִנִּה נָא יָדַעְתִּי דְּחָמָא עִמָּהּ שְׁכִינְתָּא. וּבְגִין כָּךְ אִתְרְחַץ אַבְרָהָם וְאָמַר אֲחוֹתִי הִיא.</p>\n<p>וּמִלָּה דָא אִסְתָּלַּק לִתְרֵי גְּוָונִין. חַד כְּמַשְׁמָעוֹ. וְחַד כְּדִכְתִיב, (משלי ז׳:ד׳) אֱמוֹר לַחָכְמָה אֲחוֹתִי אָתְּ. וּכְתִיב אִמְרִי נָא אֲחוֹתִי אָתְּ. וּכְתִיב, (דברים ה׳:כ״ד) וְאַתְּ תְּדַבֵּר אֵלֵינוּ. לְמַעַן יִיטַב לִי בַּעֲבוּרֵךְ, כְּלַפֵּי שְׁכִינָה אָמַר בַּעֲבוּרֵךְ יִיטַב לִי קוּדְשָׁא בְּרִיךְ הוּא. וְחָיְתָה נַפְשִׁי בִּגְלָלֵךְ. בְּגִין דִּבְדָא יִסְתַּלַּק בַּר נָשׁ וְיִזְכֶּה לְאִסְתַּלְּקָא לְאָרְחָא דְחַיֵּי.</p>\n<p>אִמְרִי נָא אֲחוֹתִי וְגו'. רַבִּי יֵיסָא אָמַר יָדַע הֲוָה אַבְרָהָם דְּכֻלְהוּ מִצְרָאֵי שְׁטִיפִין אִנּוּן בְּזִמָּה, וְכֵיוָן דְּכָל הַאי <Nonei></i>יָדַע אַמַּאי לָא דָחִיל עַל אִתְּתֵיהּ דְּלָא אַהֲדַר מֵאָרְחָא וְלָא יֵיעוּל לְתַמָּן. אֶלָּא בְּגִין דְּחָמָא שְׁכִינְתָּא עִמָּהּ:</p>"],[9520011193,"<p>וַיְהִי כְּבֹא אַבְרָם מִצְרָיְמָה וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה כִּי יָפָה הִיא מְאֹד. אָמַר רַבִּי יְהוּדָה בְּתֵיבָה אָעִיל לָהּ, וּפְתָחוּ לָהּ לְמֵיסַב מִנָּה קוּסְטוּנָא. כֵּיוָן דְּאִתְפַּתַּח הֲוָה נְהוֹרָא כִּנְהוֹרָא דְּשִׁמְשָׁא הֲדָא הוּא דִכְתִיב כִּי יָפָה הִיא מְאֹד.</p>\n<p>מַאי מְאֹד, אֶלָּא דְּחָמוּ בַּתֵּיבָה דִיוּקְנָא (נ\"א נהורא) אָחֳרָא. אַפִּיקוּ לָהּ וְחָמוּ לָהּ כְּמִלְקַדְמִין הֲדָא הוּא דִכְתִיב וַיִּרְאוּ אוֹתָהּ שָׂרֵי פַרְעֹה. כֵּיוָן דִּכְתִיב וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה מַאי וַיִּרְאוּ אוֹתָהּ שָׂרֵי פַרְעֹה, אֶלָּא דְּאֲפִיקוּ לָהּ וְחָמוּ לָהּ כְּמִלְקַדְּמִין וּכְדֵין וַיְהַלְּלוּ אוֹתָהּ אֶל פַּרְעֹה וְגו'. (כאן שייך מה שבז\"ח דף לח ע\"ב)</p>\n<p>אָמַר רַבִּי יִצְחָק. וַוי לְאִנּוּן חַיָּיבַיָא דְעָלְמָא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין בַּעֲבִידְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִנּוּן לָא מִסְתַּכְּלֵי (בכלא) דְּכָל מַה דְּהֲוֵי בְּעָלְמָא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ, דְּאִיהוּ יָדַע בְּקַדְמִיתָא מַה דִּלְהוֵי בְּסוֹפָא דִּכְתִיב, (ישעיהו מ״ו:י׳) מַגִּיד מֵרִאשִׁית אַחֲרִית. וְאִיהוּ אִסְתָּכֵי וְעֲבִיד עֲבִידָן בְּקַדְמִיתָא בְּגִין לְסָלְקָא לוֹן לְבָתַר יוֹמִין.</p>\n<p>תָּא חֲזֵי אִלְמָלֵא דְּאִנְסִיבַת שָׂרַי לְגַבֵּי פַּרְעֹה, לָא אַלְקֵי הוּא, וְאַלְקָאוּתָא דָּא גָּרִים אַלְקָאוּתָא לְבָתַר כֵּן דְּיִלְקוּן מִצְרַיִם בִּנְגָעִים גְּדוֹלִים, כְּתִיב הָכָא נְגָעִים גְּדוֹלִים וּכְתִיב הָתָם (דברים ו׳:כ״ב) וַיִּתֵּן יְיָ אוֹתוֹת וּמוֹפְתִים גְּדוֹלִים וְרָעִים בְּמִצְרַיִם. מַה לְּהַלָּן עֶשֶׂר מַכּוֹת אַף כָּאן עֶשֶׂר מַכּוֹת. כְּמָה דְּעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא נִסִּין וּגְבוּרָן לְיִשְׂרָאֵל לֵילְיָא, אוּף הָכָא עֲבַד לָהּ קוּדְשָׁא בְּרִיךְ הוּא לְשָׂרָה נִסִּין וּגְבוּרָאן לֵילְיָא.</p>\n<p>רַבִּי יוֹסֵי פָּתַח וְאָמַר (תהילים ג׳:ד׳) וְאַתָּה יְיָ מָגֵן בַּעֲדִי כְּבוֹדִי וּמֵרִים רֹאשִׁי. אָמַר דָּוִד אַף עַל גַּב דְּכָל בְּנֵי עָלְמָא יֵיתוּן לַאֲגָחָא בִּי קְרָבָא, וְאַתָּה יְיָ מָגֵן בַּעֲדִי. תָּא חֲזֵי, כְּתִיב מָגֵן בַּעֲדִי. אָמַר דָּוִד לְקוּדְשָׁא בְּרִיךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם מִפְּנֵי מָה לָא עַבְדֵי בִּי חֲתִימָה דִבְרָכָה כְּמָה דְּחָתְמֵי בְּרָכָה בְּאַבְרָהָם דִּכְתִיב אָנֹכִי מָגֵן לָךְ. וְאָמְרֵי מָגֵן אַבְרָהָם.</p>\n<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְדָוִד, אַבְרָהָם כְּבָר בְּחַנְתִּיו וּצְרַפְתִּיו וְקָאִים קַמָּאי בְּקִיּוּמָא שְׁלִים. אָמַר לֵיהּ דָּוִד אִי הָכִי (תהילים כ״ו:ב׳) בְּחָנֵנִי יְיָ וְנַסֵּנִי צָרְפָה כִלְיוֹתַי וְלִבִּי. כֵּיוָן דְּעֲבַד הַהִיא מִלָּה דְּבַת שֶׁבַע אִדְכַּר דָּוִד קַמֵּיהּ עַל מַה דְּאָמַר. אָמַר (תהילים י״ז:ג׳) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַיְלָה צְרַפְתַּנִּי בַּל תִּמְצָא זַמּוֹתִי בַּל יַעֲבָר פִּי.</p>\n<p>אָמַר אֲנָא אֲמִינָא בְּחָנִנִי יְיָ וְנַסֵּנִי וְאַנְתְּ בָּחַנְתָּ לִבִּי. אֲנָא אֲמִינָא צָרְפָה כִלְיוֹתַי וְאַתְּ צְרַפְתַּנִּי בַּל תִּמְצָא לָא אַשְׁכַּחְתְּ לִי כְּדְקָא יְאוּת. זַמּוֹתִי בַּל יַעֲבָר פִּי. מַאן יִתֵּן וְהַאי מִלָּה דַּחֲשָׁבִית דְּלָא יַעֲבָר לִי פּוּמָאי,</p>\n<p>וְעִם כָּל דָּא חָתְמִין בֵּיהּ בְּרָכָה דְּקָאֲמָרָן מָגֵן דָּוִד, וּבְגִין כָּךְ אָמַר דָּוִד וְאַתָּה יְיָ מָגֵן בַּעֲדִי, כְּבוֹד וּמֵרִים רֹאשִׁי. (ד\"א ל\"ג והאי) וַדַּאי דַּרְגָּא דָּא יְקָרָא דִילִי דְּאֲנָא מִתְעַטַּרְנָא בֵּיהּ:</p>\n<p>וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים וַיְשַׁלְּחוּ אוֹתוֹ. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ מָגֵן לְצַדִּיקַיָּיא דְּלָא יִשְׁלְטוּן בְּהוּ בְּנֵי נָשָׁא, וְקוּדְשָׁא בְּרִיךְ הוּא אָגִין עַל אַבְרָהָם דְּלָא יִשְׁלְטוּן בֵּיהּ וּבְאִתְּתֵיהּ.</p>\n<p>תָּא חֲזֵי, שְׁכִינְתָּא לָא אִתְעֲדֵי מִנָּהּ דְּשָׂרָה כָּל הַהוּא לֵילְיָא, אֲתָא פַּרְעֹה לְמִקְרַב בַּהֲדָהּ, אֲתָא מַלְאַךְ וְאַלְקֵי לֵיהּ, כָּל אֵימַת דְּאֲמְרָה שָׂרָה אַלְקֵי הוּא מַלְקֵי, וְאַבְרָהָם הֲוָה מַתְקִיף בְּמָארֵיהּ דְּהָא שָׂרָה לָא יָכְלִין לְשַׁלְטָאָה עֲלָהּ הֲדָא הוּא דִכְתִיב, (משלי כ״ח:א׳) וְצַדִּיקִים כִּכְפִיר יִבְטָח, וְהָכָא נִסְיוֹנָא הוּא דְּלָא הִרְהֵר אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר רַבִּי יִצְחָק תָּא חֲזֵי, דִּבְגִין כָּךְ לָא פַקֵּיד קוּדְשָׁא בְּרִיךְ הוּא לְנַחֲתָא לְמִצְרַיִם אֶלָּא הוּא עַצְמוֹ מִגַרְמֵיהּ נָחַת, בְּגִין דְּלָא יְהֵא פִּתְחוֹן פֶּה לִבְנֵי עָלְמָא דְּאָמַר לֵיהּ כֵּן וּלְבָתַר אִצְטַעֵר עַל אִתְּתֵיהּ.</p>\n<p>רַבִּי יִצְחָק פָּתַח וְאָמַר (תהילים צ״ב:י״ג) צַדִּיק כַּתָּמָר יִפְרָח כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶּא. צַדִּיק כַּתָּמָר יִפְרָח. מִפְּנֵי מָה אַקִּישׁ צַדִּיק לְתָמָר. מַה תָּמָר כֵּיוָן דְּגָזְרִין לֵיהּ לָא סָלִיק עַד זְמַן סַגְיָא, אוּף הָכִי צַדִּיק כֵּיוָן דְּאִתְאֲבִיד מֵעָלְמָא לָא סָלִיק אַחֵר תְּחוֹתוֹי עַד זְמַן סַגְיָא. כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶא אוּף הָכִי נָמֵי.</p>\n<p>כַּתָּמָר יִפְרָח מַה תָּמָר לָא סָלִיק אֶלָּא דְּכַר וְנוּקְבָא. אוּף הָכִי צַדִּיק לָא סָלִיק אֶלָּא דְּכַר וְנוּקְבָא, דְּכַר צַדִּיק וְנוּקְבָא צַדֶּקֶת, כְּגַוְונָא דְּאַבְרָהָם וְשָׂרָה.</p>\n<p>כְּאֶרֶז בַּלְּבָנוֹן יִשְׂגֶא מָה אֶרֶז בַּלְּבָנוֹן עִלָּאָה עַל כֹּלָּא וְכֹלָּא יַתְבֵי תְּחוֹתוֹי, אוּף הָכִי צַדִּיק הוּא עִלָּאָה עַל כֹּלָּא וְכֹלָּא יַתְבֵי תְּחוֹתוֹי. וְעָלְמָא לָא קָיְימָא אֶלָּא עַל צַדִּיק חַד דִּכְתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְעֲלֵיהּ קָאִים עָלְמָא, וּבְגִינֵיהּ אִסְתְּמִיךְ, וְעֲלֵיהּ אִשְׁתִּיל.</p>\n<p>רַבִּי יְהוּדָה אָמַר וְהָא תָּנִינָן דְּעַל שִׁבְעָה סָמְכִין עָלְמָא קָיְימָא דִּכְתִיב, (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. אָמַר לֵיהּ רַבִּי יוֹסֵי הָכִי הוּא וַדַּאי, אֲבָל (הכא) כֻּלְהוּ אָחֳרָנִין בִּשְׁבִיעָאָה <Nonei></i>קָיְימֵי דְּאִיהוּ סָמְכָא דְעָלְמָא, וְאִיהוּ צַדִּיק וְדָא אַשְׁקֵי (לעלמא) וְרָוִי עָלְמָא (ס\"א מן כלא) וְזָן כֹּלָּא. וְעֲלֵיהּ כְּתִיב (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב כִּי פְּרִי מַעַלְלֵיהֶם יאכֵלוּ. וּכְתִיב, (תהילים קמ״ה:ט׳) טוֹב יְיָ לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו.</p>\n<p>אָמַר רַבִּי יִצְחָק, הָא כְּתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. דָּא הוּא סָמְכָא דְעָלְמָא קָאִים עֲלֵיהּ, וְאִיהוּ אַשְׁקֵי לְגִנְתָא (דעדן) וְגִנְתָא אִשְׁתַּקֵּי מִנֵּיהּ וּמִנֵּיהּ עֲבִידָא פֵּירִין. וְכֻלְהוּ פֵּירִין פָּרְחִין בְּעָלְמָא וְאִנּוּן קִיּוּמָא דְעָלְמָא קִיּוּמָא דְאוֹרַיְיתָא, וּמַאן נִינְהוּ, נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא דְּאִנּוּן פְּרִי עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ בְּכָל לֵילְיָא וְלֵילְיָא נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא סָלְקָן.</p>"],[9520011194,"<p>וְכַד אִתְפְּלַג לֵילְיָא קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְגִנְתָא דְעֵדֶן לְאִשְׁתַּעְשְׁעָא בְּהוּ. בְּמַאן. אָמַר רַבִּי יוֹסֵי בְּכֻלְהוּ, בֵּין אִנּוּן דִּמְדוֹרֵיהוֹן בְּהַהוּא עָלְמָא, בֵּין אִנּוּן דְּיָתְבֵי בִּמְדוֹרֵיהוֹן בְּהַאי עָלְמָא, בְּכֻלְהוּ מִשְׁתַּעֲשַׁע בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגּוּת לֵילְיָא.</p>\n<p>תָּא חֲזֵי, עָלְמָא דִלְעֵילָא אִצְטְרִיךְ לְאִתְעֲרוּתָא דְעָלְמָא תַּתָּאָה, וְכַד נִשְׁמַתְהוֹן דְּצַדִּיקַיָיא נָפְקֵי מֵהַאי עָלְמָא וְסָלְקֵי לְעֵילָא כֻּלְהוּ מִתְלַבְּשֵׁי בִּנְהוֹרָא דִלְעֵילָא בְּדִיוּקְנָא יְקָר, וּבְהוּ קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשַׁע וְתָאִיב לוֹן דְּאִינְהוּ פְּרִי עוֹבָדוֹי, וְעַל דָּא אִקְרוּן יִשְׂרָאֵל דְּאִית לוֹן נִשְׁמָתִין קַדִּישִׁין בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא, כְּמָא דְאַתְּ אָמֵר (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם, בָּנִים וַדַּאי אִיבָּא דְּעוֹבָדוֹי.</p>\n<p>אָמַר רַבִּי יֵיסָא וְאֲפִילּוּ אִנּוּן דִּבְהַאי עָלְמָא (דארעא), הֵיאַךְ. אָמַר לֵיהּ בְּגִין דִּי בְּפַלְגוּת לֵילְיָא כָּל אִנּוּן זַכָּאֵי קְשׁוֹט כֻּלְהוּ מִתְעָרֵי לְמִקְרֵי בְּאוֹרַיְיתָא וּלְמִשְׁמַע תּוּשְׁבְּחָן דְּאוֹרַיְיתָא, וְהָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל אִנּוּן צַדִּיקַיָא דִּבְגוֹ גִנְתָא דְעֵדֶן כֻּלְהוּ צַיְיתִין לְקָלֵיהוֹן, וְחוּטָא דְחֶסֶד אִתְמְשַׁךְ עֲלַיְיהוּ בִּימָמָא דִּכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי.</p>\n<p>וְעַל דָּא תּוּשְׁבְּחָן דְּסָלְקִין בְּלֵילְיָא קַמֵּיהּ דָּא תּוּשְׁבַּחְתָּא שְׁלִים. תָּא חֲזֵי, בְּשַׁעֲתָא דְיִשְׂרָאֵל הֲווּ סְגִירִין בְּבָתֵּיהוֹן כַּד קָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּכוֹרֵיהוֹן דְּמִצְרָאֵי, הֲווּ אֲמָרֵי הֲלֵילָא וְתֻשְׁבְּחָן קַמֵּיהּ.</p>\n<p>תָּא חֲזֵי, דְּדָוִד מַלְכָּא הֲוָה קָם בְּפַלְגוּת לֵילְיָא, דְּאִי תֵימָא דְּהֲוָה יָתִיב אוֹ שָׁכִיב בְּעַרְסֵיהּ וְהֲוָה אָמַר שִׁירִין וְתוּשְׁבְּחָן, לָא, אֶלָּא כְּמָה דִכְתִיב (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לְךָ. אָקוּם וַדַּאי בַּעֲמִידָה לְאִתְעַסְּקָא בְּשִׁירִין וְתוּשְׁבְּחָן דְּאוֹרַיְיתָא.</p>\n<p>וּבְגִין כָּךְ דָּוִד מַלְכָּא חַי לְעָלְמִין, וְאֲפִילּוּ בְּיוֹמֵי מַלְכָּא מְשִׁיחָא אִיהוּ מַלְכָּא. דְּהָא תְּנַן מַלְכָּא מְשִׁיחָא אִי מִן חַיָּיא הוּא דָּוִד שְׁמֵיהּ וְאִי מִן מֵתַיָיא הוּא דָּוִד שְׁמֵיהּ, וְאִיהוּ הֲוָה אִתְעַר בְּצַפְרָא עַד לָא יֵיתֵי דִּכְתִיב, (תהילים נ״ז:ט׳) עוּרָה כְבוֹדִי עוּרָה הַנֵּבֶל וְכִנּוֹר אָעִירָה שָׁחַר.</p>"],[9520011195,"<p>תָּא חֲזֵי, כָּל הַהוּא לֵילְיָא דְּשָׂרָה הֲוַת לְגַבֵּיהּ דְּפַרְעֹה אָתוּ מַלְאֲכֵי עִלָּאֵי לְזַמְרָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּשִׁירִין וְתוּשְׁבְּחָן, אָמַר לְהוּ קוּדְשָׁא בְּרִיךְ הוּא כֻּלְּכוּ זִילוּ וְעֲבִידוּ מַכְתְּשִׁין רַבְרְבִין בְּמִצְרַיִם, רְשִׁימוּ לְמַאן דְּאֲנָא זַמִּין לְמֶעְבַּד לְבָתַר, (דא) מַה כְּתִיב וַיְנַגַּע יְיָ אֶת פַּרְעֹה נְגָעִים גְּדוֹלִים וְגו'.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב וַיִּקְרָא פַּרְעֹה לְאַבְרָם וְגו'. מְנָא הֲוָה יָדַע, דְּהָא לָא כְּתִיב הָכָא כְּמָה דְּאִתְּמָר בַּאֲבִימֶלֶךְ דִּכְתִיב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא וְגו', וְהָכָא לָא אָמַר לֵיהּ מִדִּי.</p>\n<p>אָמַר רַבִּי יִצְחָק הָא כְּתִיב עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. דְּהָכִי הֲווּ אָמְרֵי לֵיהּ, עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם. דְּהָא לָא הֲוָה מְמַלֵּיל עִמֵּיהּ כְּמָה דִּמְמַלֵּיל בַּאֲבִימֶלֶךְ, אֶלָּא בְּמִלָּה דָא אִתְּמָר וְלָא יַתִּיר, מַכְתְּשָׁא דָא עַל דְּבַר שָׂרַי אֵשֶׁת אַבְרָם אִיהִי, וְלָא הֲוָה מַלִּיל (דא) עִמֵּיהּ, כְּדֵין יָדַע (הוא) דְּהָא אִתְּתֵיהּ דְּאַבְרָהָם אִיהִי, מִיָּד וַיִּקְרָא פַּרְעֹה לְאַבְרָם וַיֹּאמֶר וְגו'.</p>\n<p>וַיְצַו עָלָיו פַּרְעֹה אֲנָשִׁים. לָמָּה בְּגִין דְּלָא יִקְרַב בַּר נַשׁ בְּהוּ לְאַבְאָשָׁא לוֹן. וַיְשַׁלְּחוּ אוֹתוֹ, לְוָיָיה עֲבָדוּ לֵיהּ בְּכָל אַרְעָא דְמִצְרַיִם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא הָכִי אַנְתְּ זַמִּין לְמֶעְבַּד לִבְנוֹי אַתְּ תּוֹזִיף לוֹן מֵאַרְעָךְ דִּכְתִיב, (שמות י״ג:י״ז) וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם דְּאוֹזִיף לוֹן מִכָּל אַרְעֵיהּ.</p>\n<p>אָמַר רַבִּי אַבָּא כָּל כָּךְ לָמָּה אִזְדַּמֵּן לֵיהּ לְאַבְרָהָם וּלְמַאי אִיצְטְרִיךְ, אֶלָּא בְּגִין לְגַדְּלָא שְׁמֵיהּ דְּאַבְרָהָם וְשָׂרָה בְּעָלְמָא, <Nonei></i>דְּאָפִילּוּ בְּמִצְרַיִם דְּאִנּוּן חֳרָשֵׁי עָלְמָא וְלָא הֲוָה יָכִיל בַּר נָשׁ לְאִשְׁתְּזִיב מִנַּיְיהוּ. אִתְגַּדַּל אַבְרָהָם וְאִסְתַּלִּיק לְעֵילָא הֲדָא הוּא דִכְתִיב וַיַּעַל אַבְרָם מִמִּצְרַיִם, לְאָן אֲתַר הַנֶּגְבָּה. (ומאי הוא ואשתו וכל אשר לו, אלא לאודעא דלא גזלו מניה מדעם מאנון מתנן דיהבו ליה בדיל שרה דתהא למלכא)</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, כֹּלָּא רָזָא דְחָכְמְתָא אִיהוּ, וְקָא רָמַז הָכָא בְּחָכְמְתָא וְדַרְגִּין דִּלְתַתָּא דְּקָא נָחִית אַבְרָהָם לְעוּמְקַיָּיא דִלְהוֹן וְיָדַע לוֹן, וְלָא אִתְדַּבָּק בְּהוּ, וְתָב לְקַמֵּי מָרֵיהּ.</p>\n<p>וְלָא אִתְפַּתָּא בְּהוּ כְּאָדָם דְּכַד מָטָא לְהַהוּא דַרְגָא אִתְפַּתָּא בְּנָחָשׁ וְגָרִים מוֹתָא לְעָלְמָא. וְלָא אִתְפַּתָּא כְּנֹחַ דְּכַד נָחַת וּמָטָא לְהַהוּא דַרְגָּא מַה כְּתִיב, (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגָּל בְּתוֹךְ אָהֳלֹה. אָהֳלֹה כְּתִיב בְּה\"א.</p>\n<p>אֲבָל בְּאַבְרָהָם מַה כְּתִיב וַיַּעַל אַבְרָם מִמִּצְרַיִם. דְּסָלִיק וְלָא נָחִית, וְתָב לְאַתְרֵיהּ לְדַרְגָא עִלָּאָה דְּאִתְדַּבָּק בֵּיהּ בְּקַדְמִיתָא. וְעוֹבָדָא דָא הֲוָה, בְּגִין לְאַחֲזָאָה חָכְמָתָא דְּאִתְקַיָּים בְּקִיּוּמָא שְׁלִים כְּדְקָא חָזֵי לֵיהּ וְלָא אִתְפַּתָּא וְקָם בְּקִיּוּמָא וְתָב לְאַתְרֵיהּ. הַנֶּגְבָּה, דָּא דָרוֹם דַּרְגָּא עִלָּאָה דְּאִתְאֲחִיד בֵּיהּ בְּקַדְמִיתָא דִּכְתִיב הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. אוּף הָכָא הַנֶּגְבָּה, אֲתַר דְּאִתְדַבַּק בֵּיהּ בְּקַדְמִיתָא.</p>\n<p>תָּא חֲזֵי, רָזָא דְמִלָּה, אִי אַבְרָם לָא יֵיחוּת לְמִצְרַיִם וְלָא יִצְטָרֵף תַּמָּן בְּקַדְמִיתָא. לָא יְהֵא חוּלַק עַדְבֵיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. כְּגַוונָא דָא לִבְנוֹי כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעבַּד לֵיהּ (ד\"א לון) עַמָּא חָדָא עַמָּא שְׁלִים וּלְקָרְבָא לוֹן לְגַבֵּיהּ, אִי לָא נָחֲתוּ בְּקַדְמִיתָא לְמִצְרַיִם וְלָא יִצְטַרְפוּן תַּמָּן, לא הֲווּ עַמָּא יְחִידָא דִילֵיהּ.</p>\n<p>(סא א) כְּגַוְונָא דָא אִי לָא אִתְיְיהִיבַת אַרְעָא קַדִּישָׁא לִכְנַעַן בְּקַדְמיתָא וְיִשְׁלוֹט בָּהּ לָא הֲות אַרְעָא חוּלְקֵיהּ וְעַדְבֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וכֹלָּא רָזָא חָדָא.</p>"],[9520011196,"<p>רַבִּי שִׁמְעוֹן הֲוָה אָזִיל בְּאָרְחָא, וְהֲוָה עִמֵּיהּ רַבִּי אֶלְעָזָר בְּרֵיהּ וְרַבִּי אַבָּא וְרַבִּי יְהוּדָה. עַד דְּהֲווּ אָזְלֵי, אָמַר רַבִּי שִׁמְעוֹן תָּוַוהְנָא הֵיךְ בְּנֵי עָלְמָא לָא מַשְׁגִּיחִין לְמִנְדַע מִלֵּי דְאוֹרַיְיתָא ועָל מָה קָיְימֵי. פָּתַח וְאָמַר, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, הַאי קְרָא אוּקְמוּהָ וְאוֹקִימְנָא לֵיהּ, אֲבָל תָּא חֲזִי, נַפְשָׁא דְּבַּר נָשׁ, כָּד (איהו) סָלִיק לְעַרְסֵיהּ, נָפְקַת מִנֵּיהּ וְסָלְקָא לְעֵילָא. וְאִי תֵימָא דְּכֻלְהוּ סָלְקָאן. לָאו כָּל חַד וְחַד חָמֵי אַפֵּי מַלְכָּא, אֶלָּא נַפְשָׁא סָלְקָא וְלָא אִשְׁתָּאַר בָּהּ בַּהֲדֵי גוּפָא בַּר חַד רְשִׁימוּ (נשימו) דְּקֻיסְטָא דְּחַיּוּתָא דְּלִבָּא.</p>\n<p>וְנַפְשָׁא אָזְלָא וּבָעְיָא לְסָלְקָא. וְכַמָּה דַּרְגִּין לְדַרְגִּין לְסָלְקָא, שָׁטָאת וְהִיא אִתְעָרְעַת בְּהַנֵּי קוּמְרִין טְהִירִין דִּמְסָאֲבוּתָא. אִי הִיא דְּכִיאַת דְּלָא אִסְתָּאָבַת בִּימָמָא סָלְקָא לְעֵילָא. וְאִי לָאו דְּכִיאַת, אִסְתָּאֳבַת בֵּינַיְיהוּ וְאִתְדַּבְּקַת בְּהוּ וְלָא סָלְקָא יַתִּיר.</p>\n<p>וְתַמָּן מוֹדָעֵי לָהּ מִלִּין וְאִיהוּ אִתְדַּבְּקַת מֵאִנּוּן מִלִּין דִּזְמַן קָרִיב. וּלְזִמְנִין דְּחַיְיכִין בָּהּ וּמוֹדָעִין לָהּ מִלִּין כְּדִיבִין. וּכְדֵין אָזְלָא כְּהַאי גַּוְונָא כָּל לֵילְיָא עַד דְּיִתְעַר בַּר נָשׁ וְתָאבַת לְאַתְרָהּ. זַכָּאִין אִנּוּן צַדִּיקַיָיא דְּגָלֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא רָזִין דִּילֵיהּ בְּחֶלְמָא בְּגִין דְּיִסְתַּמְּרוּן מִן דִּינָא. וַוי לְאִנּוּן חַיָיבֵי עָלְמָא דִּמְסָאֲבִין גַּרְמַיְיהוּ וְנַפְשַׁיְיהוּ.</p>\n<p>תָּא חֲזֵי, אִנּוּן דְּלָא אִסְתָּאֲבוּ, כַּד סָלְקֵי בְּעַרְסַיְיהוּ, נַפְשָׁא סָלְקָא וְעָאלַת בֵּין כָּל הַנֵּי דַרְגִּין בְּקַדְמִיתָא וְסָלְקָא וְלָא אִתְדַּבְּקַת בְּהוּ. וּלְבָתַר אָזְלָא וְשָׁטָאת וְסָלְקָא כְּפוּם אוֹרְחָהּ.</p>\n<p>הַהִיא נַפְשָׁא דְזָכָת לְסָלְקָא אִתְחֲזִיאַת קַמֵּיהּ דִּסְבַר אַפֵּי יוֹמִין וְאִתְדַּבְּקַת בִּרְעוּתָא לְאִתְחַזָּאָה בְּתִיאוּבְתָּא עִלָּאָה לְמֶחֱמֵי בְּנוֹעַם מַלְכָּא וּלְבַקְּרָא בְּהֵיכָלֵיהּ. וְדָא הוּא בַּר נָשׁ דְּאִית לֵיהּ חוּלָקָא תָּדִיר בְּעָלְמָא דְּאָתֵי.</p>\n<p>וְדָא הִיא נַפְשָׁא דִּכְסִיפָא דִילָהּ כַּד סָלְקָא בְּקוּדְשָׁא בְּרִיךְ הוּא (תדיר), וְלָא אִתְדַבְּקַת בְּהַנֵּי זִינִין טְהִירִין אַחֲרָנִין, וְהִיא אָזְלַת בָּתַר זִינָא קַדִּישָׁא בְּאַתְרָא (ד\"א בתר אתרא) דְּנָפְקַת מִתַּמָּן. וּבְגִין כָּךְ כְּתִיב נַפְשִׁי אִוִּיתִיךָ בַּלָּיְלָה. בְּגִין לְמִרְדַּף בַּתְרָךְ וְלָא לְאִתְפַּתָּאָה בָּתַר זִינָא אָחֳרָא נוּכְרָאָה.</p>"]]});
